          "Play_A_SFX_Pierce_Knife"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Splash_Blood",
          "Play_A_SFX_Head_Explosion"
        }
      }),
      readonly({
        TalkRole = {1314},
        Content = "AvgDialog_13050_Content_21|什…么……？",
        DialogType = 2,
        RolePos = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Fall_Down"
