      readonly({
        TalkRole = {1315},
        Content = "AvgDialog_13056_Content_8|只有这么个小孩子？我们没找错地方吗？",
        DialogType = 1,
        RolePos = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Normal_Short"
        },
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        TalkRole = {1316},
        Content = "AvgDialog_13056_Content_9|没错，战略地图上画得清清楚楚，这里是女眷行宫。",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {
          1123,
          nil,
          "angry"
        },
        Content = "AvgDialog_13056_Content_10|别再靠近了！我不会手下留情的！",
        DialogType = 1,
        RolePos = {3},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx"
      }),
      readonly({
        Content = "AvgDialog_13056_Content_11|奥吉尔支起长枪，拦在了楼梯上。",
        DialogType = 3,
        AnimState = "SetRole(1123,3)",
        ShortAudioEffect = {
          "Play_A_SFX_TakeUp_Arms",
          "Play_A_SFX_Cloth_Bring_Here"
        }
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_13056_Content_12|这是最后一次警告，请离开行宫！",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        TalkRole = {1315},
        Content = "AvgDialog_13056_Content_13|喂，你听到了吗？他在说什么？“请”我们离开？",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {1315},
        Content = "AvgDialog_13056_Content_14|哈哈哈哈哈哈，太好笑了！怪不得公国如此不堪一击，居然带着孩子玩骑士过家家。",
        DialogType = 1,
        RolePos = {0},
        Sequence = "ShakeDialog"
      }),
      readonly({
        TalkRole = {1316},
        Content = "AvgDialog_13056_Content_15|小点声，吵得我耳朵疼。",
        DialogType = 1,
        RolePos = {2},
        Sequence = "SetRole(1123,4);"
      }),
      readonly({
        Content = "AvgDialog_13056_Content_16|士官无视了奥吉尔的警告，走到了卧室门前，居高临下地看着奥吉尔。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Important_People"
