      }),
      readonly({
        TalkRole = {1316},
        Content = "AvgDialog_13056_Content_17|让开。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_13056_Content_18|奥吉尔吃力地横过长枪，试图拦住士官的前进。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Cloth_Bring_Here"
