        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1316},
        Content = "AvgDialog_13056_Content_20|你知道吗，骑士的武器不适合你。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        DialogType = 3,
