        Content = "AvgDialog_15364_Content_4|不，不……",
        DialogType = 1,
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Show_Something"
        }
      }),
      readonly({
        Content = "AvgDialog_15364_Content_5|现场混乱不堪，从四面八方涌来的人流将你和奥古斯特彻底隔开。你只能看着他被警察们强行拖走。",
        DialogType = 3
