        BgID = {
          "SScene_PalaceHallMoonight"
        },
        BgTransition = 4,
        Audio = {
          "Stop_Avg_Mus"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Bedroom"
        }
      }),
      readonly({
        Content = "AvgDialog_15364_Content_12|你从角落的阴影中走出，再度站到她的面前。",
        DialogType = 3,
        Sequence = "SetRole(1343,3)",
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Normal_Short_Leave"
        },
        Audio = {
          "Play_A_MUS_Peaceful_Sad_109BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_15364_Content_13|这里没有白日喧嚣的打扰，正是适合说话的时候。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_15364_Content_14|珊小姐，奥古斯特先生今天被人带走了。他说……\n你骗过了所有人。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_15364_Content_15|这里的“所有人”也包括我吗？",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_15364_Content_16|……",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_15364_Content_17|你曾保证会和我一起回家。这是真的吗？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1343},
        Content = "AvgDialog_15364_Content_18|……",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_15364_Content_19|雕塑依旧保持缄默。即使所有人的生活都因她而偏离，她也不曾垂下眺望远方的双眼。",
        DialogType = 3
