      readonly({
        Content = "AvgDialog_15607_Content_18|她朝你伸出手。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Show_Sash"
        }
      }),
      readonly({
        TalkRole = {
          1544,
          nil,
          "serious"
        },
        Content = "AvgDialog_15607_Content_19|帮我……救……",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        NextChatID = {"1", "2"},
        Content = "AvgDialog_15607_Content_20|你只知道你会帮她，见证她作为「人类」的结局。",
        DialogType = 3
      }),
      readonly({
        ChatID = "1",
        Content = "AvgDialog_15607_Content_21|握住她的手",
