        Content = "AvgDialog_15607_Content_25|谢谢……",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        Content = "AvgDialog_15607_Content_26|虚影如气泡般炸开消散，只剩下那明灭不定的光球，还在散发着最后的光。",
        DialogType = 3,
