    BaseSortID = 1,
    data_list = readonly({
      readonly({
        BaseSortID = 1,
        Content = "AvgDialog_18727_Content_1|不期而遇",
        Chapter = "Phantom in the Rainy Town;An Unexpected Encounter;Part 1",
        DialogType = 4,
        BgID = {
