        }
      }),
      readonly({
        TalkRole = {1570},
        Content = "AvgDialog_18717_Content_9|我坐在观众席上，看了人生中第一场电影。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        TalkRole = {
          1570,
