      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_18717_Content_23|……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_18717_Content_24|你轻轻握住达芙黛尔的手。与想象中不同，她的手很柔软，也很温暖。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Thouch_Cloth"
