      }),
      readonly({
        TalkRole = {
          1147,
          nil,
          "smile2"
        },
        Content = "AvgDialog_18717_Content_25|握紧了哦，守密人。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        Content = "AvgDialog_18717_Content_26|你脚下一轻，随即被拽入一个幽深的维度。",
        DialogType = 3,
        RoleHide = {1},
