          "Play_A_SFX_BlackHole"
        },
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        TalkRole = {1147},
        Content = "AvgDialog_18717_Content_27|欢迎回到我的“千面幻象”。",
        DialogType = 1,
        RoleHide = {1},
        Audio = {
          "Play_A_MUS_Dafudaier_Sea_120BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_18717_Content_28|又是那片熟悉的原质之海，头颅们依旧随着浪潮起伏不定。",
        DialogType = 3,
        ScreenEffect = {
