  [18710] = {
    ID = 18710,
    CnID = "大型支线_达芙黛尔_关卡7_前",
    BaseSortID = 13,
    data_list = readonly({
      readonly({
        BaseSortID = 13,
        Content = "AvgDialog_18710_Content_1|野兽王国",
        Chapter = "Phantom in the Rainy Town;Animal's Kingdom;Part 7",
        DialogType = 4,
        BgID = {
          "SScene_Black"
        },
        ShortAudioEffect = {
          "Play_UI_AVG_Chapter_Pop"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_18710_Content_2|我是一头野兽……我是一个病人。\n\n我是一个无可救药之人。",
        DialogType = 7,
        Audio = {
          "Play_A_MUS_Emo_89BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_18710_Content_3|白天，我躲在城市的阴影里，腆着肚皮四脚朝天，呼呼大睡。",
        DialogType = 7
      }),
      readonly({
        Content = "AvgDialog_18710_Content_4|夜晚，我像鬼魅一般彷徨街头，寻找一个又一个头颅。",
        DialogType = 7
      }),
      readonly({
        Content = "AvgDialog_18710_Content_5|<Red:头颅。头颅。头颅。>",
        DialogType = 7
      }),
      readonly({
        Content = "AvgDialog_18710_Content_6|<RedBig:头颅。\n        头颅。\n                头颅。\n                        头颅。\n                                头颅。\n                                        头颅……>",
        DialogType = 7
      }),
      readonly({
        Content = "AvgDialog_18710_Content_7|我的脑子再也无法思考生存、爱与尊严。\n\n它早已被那些饥渴的狂想塞得满满当当。",
        DialogType = 7
      }),
      readonly({
        Content = "AvgDialog_18710_Content_8|我是一个无可救药之人。",
        DialogType = 7
      }),
      readonly({
        Content = "AvgDialog_18710_Content_9|15@1年，圣佩德罗市",
        DialogType = 6,
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        Content = "AvgDialog_18710_Content_10|那是个晴朗的夏夜，我像往常一样辛勤地搬运着我的“战利品”。",
        DialogType = 3,
        ScreenEffect = {"retro", 1},
        BgID = {
          "SScene_LondonFog"
        },
        ShortAudioEffect = {
          "Play_A_SFX_DragCorpse02"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_London_Night"
        }
      }),
      readonly({
        TalkRole = {1271},
        Content = "AvgDialog_18710_Content_11|<Shake:头……更多的头……>",
        DialogType = 1,
        RolePos = {0},
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_18710_Content_12|嗒。嗒。嗒。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Highheel"
        }
      }),
      readonly({
        Content = "AvgDialog_18710_Content_13|轻盈的脚步声悄然而至，头顶传来一个温柔的声音。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1572},
        Content = "AvgDialog_18710_Content_14|呵……瞧瞧我都找到了什么？一头走失的小野兽。",
        DialogType = 1,
        PlayEnterAnim = 1,
        Sequence = "FadeDarkRole(1572,1)"
      }),
      readonly({
        Content = "AvgDialog_18710_Content_15|那天晚上，一个女人来到我身边。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18710_Content_16|当她靠近我时，我闻到一股很好闻的香气。\n是花与雾的气味。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Fog_Disappear",
          "500"
        }
      }),
      readonly({
        Content = "AvgDialog_18710_Content_17|这是来自另一个世界的气味，它和我的王国就像白天与黑夜一样泾渭分明，本不该有任何交集。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18710_Content_18|但她还是脚踩恶臭泥泞的泔水，穿过城市的阴影，向我伸出手。",
