        }
      }),
      readonly({
        TalkRole = {1264},
        Content = "AvgDialog_18718_Content_18|这里虽然简陋，一杯茶还是能添上的。",
        DialogType = 1,
        RoleExit = {1264},
        ExitDirection = {"1264:1"}
