        },
        Audio = {
          "Set_Avg_Mus_As_More"
        },
        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        Content = "AvgDialog_18725_Content_10|<RedItalic:星期天他喝了十瓶酒，丢掉了工作，丢掉了老婆。>",
        DialogType = 7
      }),
      readonly({
        Content = "AvgDialog_18725_Content_11|有人轻轻哼着毫无节律变化的童谣。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18725_Content_12|干涩的旋律如同一只潮湿无形的手，轻抚着你后颈处早已直立的汗毛。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_DevilWhisper"
        }
      }),
      readonly({
        Content = "AvgDialog_18725_Content_13|<RedItalic:老弗里曼哇哇哭，星期一又喝了十一瓶酒……>",
        DialogType = 7
      }),
      readonly({
        Content = "AvgDialog_18725_Content_14|伴随木板嘎吱作响的声音，哈莉特悄无声息地站在幽暗的廊道前。",
        DialogType = 3,
        Sequence = "SetRole(1264,3)",
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Old_Wooden_Floor02"
        }
      }),
      readonly({
        TalkRole = {
          1264,
          nil,
          "smile"
        },
        Content = "AvgDialog_18725_Content_15|没错，老弗里曼是我的丈夫。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_18725_Content_16|什么？！",
