        DialogType = 6,
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        TalkRole = {1371},
        Content = "AvgDialog_18769_Content_3|真见鬼，那女的不见了。",
        DialogType = 1,
        RolePos = {2},
        PlayEnterAnim = 1,
        BgID = {
          "SScene_SnowCage"
        },
