        }
      }),
      readonly({
        TalkRole = {1372},
        Content = "AvgDialog_18769_Content_4|呵呵。现在知道躲起来了？等找到她，先砍断她的腿……",
        DialogType = 1,
        RolePos = {4},
        PlayEnterAnim = 1
      }),
      readonly({
        TalkRole = {1373},
        Content = "AvgDialog_18769_Content_5|喂，尤乌哈希，你见过阿格里帕吗？",
        DialogType = 1,
        RoleHide = {1371, 1372}
