        Content = "AvgDialog_14530_Content_27|唤醒室？是做唤醒相关的训练吗？",
        DialogType = 1,
        RolePos = {4},
        Audio = {
          "Play_A_MUS_Peace_School_Life_114BPM",
          "800"
