        DialogType = 1
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_23356_Content_14|<Big:德高望重的哈罗德公爵和他的独子尼古拉斯·哈罗德！>",
        DialogType = 1,
        AnimState = "avg_dialog_Amplification",
