        Audio = {
          "Play_A_MUS_Funeral_Chp0"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_OutDoor"
        }
      }),
      readonly({
        TalkRole = {1577},
        Content = "AvgDialog_23356_Content_18|她是父神最虔诚的女儿，一位品性高洁、令人钦佩的女性……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1578},
        Content = "AvgDialog_23356_Content_19|哈啾……<Big:哈啾！>",
        DialogType = 1,
        RolePos = {2},
        RoleShake = {0},
        Sequence = "SetRole(1182,4)"
      }),
      readonly({
        TalkRole = {1182},
        Content = "AvgDialog_23356_Content_20|公爵大人这是感冒了？您一直在打喷嚏。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1578},
        Content = "AvgDialog_23356_Content_21|我被这些俗艳花卉的气味熏得受不了……把它们运过来少说也要花几千雷欧坊吧？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1578},
        Content = "AvgDialog_23356_Content_22|索蕾尔到死都维持着始终如一的暴发户做派，倒是令人钦佩……哈啾！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1182},
        Content = "AvgDialog_23356_Content_23|确实令人钦佩。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1182},
        Content = "AvgDialog_23356_Content_24|这样的行事作风能为外面的八卦记者和市民提供不少谈资，难怪她能成为伦蒂尼恩的大众偶像。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1578},
        Content = "AvgDialog_23356_Content_25|哼。不入流的伎俩。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_23356_Content_26|德克斯特耸了耸肩，百无聊赖地环顾了一下四周。",
        DialogType = 3,
        RoleHide = {1},
        AnimState = "UI_Story_Panel_AvgDialogBg_zuoyou_vx",
