        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        Content = "AvgDialog_23356_Content_29|<Gray:她下葬穿的这身衣裳，是法兰绒缝制的吧？质感真不错……>",
        DialogType = 7
