        BgID = {
          "CGDynamic_C01_012"
        }
      }),
      readonly({
        TalkRole = {1577},
        Content = "AvgDialog_23356_Content_40|……愿父神庇佑，我的孩子。",
        DialogType = 1,
        RoleHide = {1182},
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        Content = "AvgDialog_23356_Content_41|夜幕降临，一辆簇新的费迪南德·波尔舍汽车行驶在凹凸不平的石子路上。",
        DialogType = 3,
        RoleHide = {1},
        BgTransition = 6,
        ShortAudioEffect = {
          "Play_A_SFX_Car_Passing_By"
        },
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        TalkRole = {1578},
        Content = "AvgDialog_23356_Content_42|真见鬼，走到哪里都是那些小报记者。",
        DialogType = 2,
        BgID = {
          "SScene_InCarNight"
        },
        BgTransition = 4,
        Audio = {
          "Play_A_MUS_Strange_001_118BPM_Ver2"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_InCar"
        }
      }),
      readonly({
        TalkRole = {1578},
        Content = "AvgDialog_23356_Content_43|外面都在谣传我和尼古拉斯为了争抢索蕾尔大打出手，真是无稽之谈！",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1582},
        Content = "AvgDialog_23356_Content_44|平民怎么会理解公爵大人真正的所思所想？他们更愿意相信那些俗套荒诞的爱情故事。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1578},
        Content = "AvgDialog_23356_Content_45|爱情，哼。尼古拉斯也和我说这叫“爱情”。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1578},
        Content = "AvgDialog_23356_Content_46|平时他俩怎么玩闹我都可以当做没看见，可这女人竟打起了肖尔迪奇城郊那片猎场的主意。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1578},
        Content = "AvgDialog_23356_Content_47|贪婪必将招来祸端，那就别怪我们不客气了……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_23356_Content_48|——！！",
        DialogType = 3,
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Brake"
        }
      }),
      readonly({
        Content = "AvgDialog_23356_Content_49|汽车猛地停了下来，尖锐的刹车声刺破了独属夜晚的宁静。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1578},
        Content = "AvgDialog_23356_Content_50|<Shake:哎哟！！我的腰……>",
        DialogType = 2,
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_InCar"
        }
      }),
      readonly({
        TalkRole = {1582},
        Content = "AvgDialog_23356_Content_51|你的车技可是越来越离谱了，弗雷德。连刹车都不会了？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1105},
        Content = "AvgDialog_23356_Content_52|<Shake:不，老爷……是、是前面有……东西……>",
        DialogType = 2,
