        RoleHide = {1118},
        Sequence = "SetRole(1132,3,serious)",
        ShortAudioEffect = {
          "Play_A_SFX_Cloth_Bring_Here"
        }
      }),
      readonly({
        TalkRole = {
          1132,
          nil,
          "serious"
        },
        Content = "AvgDialog_23369_Content_27|你们最好只是想去看戏的，别想打什么歪主意。",
        DialogType = 1,
        Audio = {
          "Play_A_MUS_Strange_001_118BPM"
        }
      }),
      readonly({
        TalkRole = {
          1132,
          nil,
          "serious"
        },
        Content = "AvgDialog_23369_Content_28|索蕾尔夫人要是有什么闪失，珈伦不会放过你们的。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
