        BgID = {
          "CGDynamic_C01_012"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Thriller_05"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_23369_Content_30|他……？",
        DialogType = 2,
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
      }),
      readonly({
        TalkRole = {
          1132,
          nil,
          "Shy"
        },
        Content = "AvgDialog_23369_Content_31|哎呀，珈伦好像不小心说漏嘴了，真糟糕！",
        DialogType = 1,
        RoleShake = {0},
        BgID = {
          "SScene_CourtYard"
        },
        BgTransition = 4,
        ShortAudioEffect = {
          "Play_A_SFX_Emm"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_London_Morning"
        }
      }),
      readonly({
        TalkRole = {1132},
        Content = "AvgDialog_23369_Content_32|总而言之，做好你们分内的事，别问不该问的。\n再会哟，我的警官大人~",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_23369_Content_33|珈伦朝你们俏皮地眨了眨眼，随后吃力地拎起地上的水桶，吭哧吭哧地离开了。",
        DialogType = 3,
        RoleExit = {1132},
