  [23353] = {
    ID = 23353,
    CnID = "大型支线_索蕾尔_关卡5_前",
    BaseSortID = 10,
    data_list = readonly({
      readonly({
        BaseSortID = 10,
        Content = "AvgDialog_23353_Content_1|卵",
