      }),
      readonly({
        TalkRole = {
          1137,
          nil,
          "sad1"
        },
        Content = "AvgDialog_23351_Content_5|不是说要来保护我吗？我已经等你很久啦。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_23351_Content_6|她漫不经心地笑着，语气中却带着一丝不易觉察的落寞。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_23351_Content_7|抱歉，索蕾尔夫人……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_23351_Content_8|<Red:嘻嘻。>",
