        DialogType = 6,
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        TalkRole = {1594},
        Content = "AvgDialog_23359_Content_3|索蕾尔，我美丽的索蕾尔。这是给你买的新裙子，你最爱的白色。",
        DialogType = 2,
        BgID = {
          "SScene_PalaceHallMoonight"
        },
