        },
        Content = "AvgDialog_23881_Content_3|唔——！！",
        DialogType = 1,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx"
      }),
      readonly({
        Content = "AvgDialog_23881_Content_4|索蕾尔瘫坐在地。在她身下，一滩暗红的血迹在裙底慢慢扩大。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_CrimeScene"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Carcass_blood"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_23881_Content_5|夫人，您、您流血了！",
        DialogType = 2,
        ShortAudioEffect = {
          "Play_A_SFX_Hit_Jump_Shock"
        }
      }),
      readonly({
        Content = "AvgDialog_23881_Content_6|索蕾尔细细抹去嘴角溢出的鲜血。即使在这样的时刻，她也绝不会丢失半分仪态。",
        DialogType = 3,
