        }
      }),
      readonly({
        Content = "AvgDialog_23884_Content_97|一声短促而熟悉的冷笑突兀地扎进耳朵。",
        DialogType = 3,
        ScreenEffect = {"blackSmoke", 1},
        BgID = {
          "SScene_PalaceHallRose"
        }
      }),
      readonly({
        TalkRole = {
          1137,
