        RolePos = {4}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_4873_Content_8|总感觉我也看过那本书…说了这么多，萝坦你呢？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1124,
          nil,
          "Scorn"
        },
        Content = "AvgDialog_4873_Content_9|我什么？",
        DialogType = 1,
        RolePos = {3},
        RoleHide = {1123}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_4873_Content_10|故事。你不想拍摄你的故事吗？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1124,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_4873_Content_11|我的任务是把你们完完整整地带回学校。\n写剧本、拍电影这种事儿可别算上我。",
        DialogType = 1,
        RolePos = {3},
        Audio = {
          "Set_Avg_Mus_As_More_And_More"
        }
      }),
      readonly({
        DialogType = 3,
        Sequence = "PlayVideo(Blade_Flash1.mp4)",
