        AudioAmbient = {
          "Play_A_SFX_Amb_Bedroom"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_4899_Content_4|好久不见，<Blue:奥尔拉小姐>。",
        DialogType = 2,
        BgID = {
          "SScene_BedRoomDay"
        },
        BgTransition = 4,
        Sequence = "SetRole(1570,3)"
      }),
      readonly({
        TalkRole = {
          1570,
          nil,
          "smile"
        },
        Content = "AvgDialog_4899_Content_5|早上好，守密人。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1570,
          nil,
          "smile"
        },
        Content = "AvgDialog_4899_Content_6|这位小客人是……？",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_4899_Content_7|你向诗人解释了一番，有关拍摄，有关剧本，有关莉莉……",
        DialogType = 6,
        BgID = {
          "SScene_Black"
        },
        Sequence = "SlowCaption",
        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        TalkRole = {1570},
        Content = "AvgDialog_4899_Content_8|原来如此，为了测试朵尔小姐改造过的摄像机，你们需要拍摄一部影片……",
        DialogType = 1,
        BgID = {
          "SScene_BedRoomDay"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Early_Morning_Woods"
        }
      }),
      readonly({
        TalkRole = {
          1570,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_4899_Content_9|但也许你还记得，我只是个微不足道的诗人…在电影剧本的撰写上，我远远称不上“合格”。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_4899_Content_10|不不不，奥尔拉小姐理解错了。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1570},
        Content = "AvgDialog_4899_Content_11|您来拜访我，难道不是为了剧本吗？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_4899_Content_12|是，又不是。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_4899_Content_13|你低头看着几乎挂在你腿上的莉莉，轻轻将她推到了奥尔拉面前。",
        DialogType = 3,
        Sequence = "SetRole(1130,2);SetRole(1570,4)",
        ShortAudioEffect = {
          "Play_A_SFX_Pat_Cloth",
          "800"
        }
      }),
      readonly({
        TalkRole = {1570},
        Content = "AvgDialog_4899_Content_14|<Italic:意料外的生命，于时间之外迎来盛放……>",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {
          1570,
          nil,
          "smile"
        },
        Content = "AvgDialog_4899_Content_15|你好，莉莉。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1130},
        Content = "AvgDialog_4899_Content_16|您、您好！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_4899_Content_17|我们想向您请教，创作故事的方法。",
        DialogType = 2,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
