      readonly({
        Content = "AvgDialog_4889_Content_4|萝坦反射性把小唤醒体们拦在身后，双手充满警惕地握紧了剑柄。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Shake_sword"
