      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_4889_Content_5|抱歉，我第一次用这个扬声器。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1124},
        Content = "AvgDialog_4889_Content_6|还想玩一会儿？",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_4889_Content_7|你摇了摇头，再次按下了扬声器的开关，同时也将照明灯再次对准了布景中央。",
        DialogType = 3,
