        RolePos = {3},
        RoleHide = {1642},
        BgID = {
          "CGDynamic_C01_012"
        }
      }),
      readonly({
        Content = "AvgDialog_35989_Content_75|小丑绽开一个大大的笑容，脸上的油彩化作一点点金色的星光。",
        DialogType = 3,
        ScreenEffect = {"starlight", 1},
        ShortAudioEffect = {
          "Play_A_SFX_Meteor_Passing_By_02"
        }
      }),
      readonly({
        TalkRole = {1645},
        Content = "AvgDialog_35989_Content_76|现在我已经超额完成任务啦，是时候回去咯~",
