        }
      }),
      readonly({
        TalkRole = {
          1104,
          nil,
          "Smile"
        },
        Content = "AvgDialog_13946_Content_6|醒了？",
        DialogType = 1,
        ScreenEffect = {"awake", 2},
        Sequence = "FadeDarkRole(1104,1)"
      }),
      readonly({
        Content = "AvgDialog_13946_Content_7|海水卷起被日光烤至发烫的浪花，微咸的海风将浓重的腥气捎至鼻腔。",
        DialogType = 3,
        Audio = {
          "Play_A_Mus_AfterWar_Ver4_118BPM"
