        ShortAudioEffect = {
          "Play_A_SFX_Hit_Push"
        }
      }),
      readonly({
        Content = "AvgDialog_24297_Content_10|重赏之下必有勇夫。战士们发出兴奋的嘘声，兵刃激鸣，震颤出激动的金戈之声。",
