        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_6773_Content_85|另一个“希洛”狂妄地放声大笑，将一切汹涌的恶意在笑声里尽情释放。",
        DialogType = 3,
        Sequence = "SetRole(1304,2,smile)"
