        },
        BanSpeedUp = 1
      }),
      readonly({
        Content = "AvgDialog_8232_Content_2|悔过",
        Chapter = "Color of Thy Blood;Act of Penance;Part 1",
        DialogType = 4,
        BgID = {
          "SScene_Black"
        },
        ShortAudioEffect = {
          "Play_UI_AVG_Chapter_Pop"
