        }
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_8229_Content_20|你警告过我的，不要再以他人的苦痛为生，不要再欺骗。我应该改正的，但我一直没听……咳！",
        DialogType = 1,
        RolePos = {0}
