        Audio = {
          "Stop_Avg_Mus"
        },
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        TalkRole = {
          1651,
          nil,
          "angry"
        },
        Content = "AvgDialog_8229_Content_33|你本就应该被审判，傲慢的罪人！",
        DialogType = 1,
        RoleHide = {1135},
