        RolePos = {0}
      }),
      readonly({
        Content = "AvgDialog_38729_Content_11|人们的目光变得空茫，身体愈发放松。慌乱与恐惧一扫而空，取而代之的是舒缓和宁静。",
        DialogType = 3
      }),
      readonly({
