      readonly({
        TalkRole = {
          1651,
          nil,
          "serious"
        },
        Content = "AvgDialog_38729_Content_16|……你不该救我的。",
        DialogType = 1,
        RolePos = {4},
        Sequence = "SetRole(1135,2)"
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38729_Content_17|“凡是迷途知返的，都能回到我的怀抱”。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {
          1651,
          nil,
          "serious"
        },
        Content = "AvgDialog_38729_Content_18|“因为你们皆是我的子，而我爱着你们所有”。\n但你错了，主教，《圣典》也错了。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {
          1651,
          nil,
