        Content = "AvgDialog_47175_Content_48|姐姐！",
        DialogType = 10,
        DialogAnim = 1,
        RolePos = {2},
        Sequence = "Quote"
      }),
      readonly({
        Content = "AvgDialog_47175_Content_49|声音传进弥利亚姆的耳中。她猛然抬头，看见自己前方那个熟悉的身影。",
        DialogType = 10,
