        Sequence = "Quote",
        ShortAudioEffect = {
          "Play_A_SFX_OMG"
        }
      }),
      readonly({
        TalkRole = {1720},
        Content = "AvgDialog_47175_Content_51|姐姐，过了这么久了，你怎么一点都没变？你看我，我长高了！",
        DialogType = 10,
        RolePos = {2},
        Sequence = "Quote"
      }),
      readonly({
        TalkRole = {1782},
        Content = "AvgDialog_47175_Content_52|弥利亚姆……你在神殿里，过得还好吗？",
        DialogType = 10,
        RolePos = {0},
        Sequence = "Quote"
      }),
      readonly({
        TalkRole = {1782},
        Content = "AvgDialog_47175_Content_53|好久都没见到你……妈妈想你了。",
        DialogType = 10,
        RolePos = {0},
        Sequence = "Quote"
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "scared"
        },
        Content = "AvgDialog_47175_Content_54|母亲……母亲……您……",
        DialogType = 10,
        RolePos = {4},
        Sequence = "Quote"
      }),
      readonly({
        Content = "AvgDialog_47175_Content_55|弥利亚姆愣愣地看着向自己走来的两人。身后响起脚步声。她缓缓转过身去。",
        DialogType = 10,
