        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Lightly_Clothes_Rub_01"
        }
      }),
      readonly({
        Content = "AvgDialog_47175_Content_81|年幼的新王沉默了片刻，向前一步。",
        DialogType = 10,
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Slow_Short"
        }
      }),
      readonly({
        TalkRole = {1159},
        Content = "AvgDialog_47175_Content_82|余，神明的代行者，利莫里亚的王。",
        DialogType = 10,
        BgID = {
          "SScene_StoneTemple"
        },
        BgTransition = 4,
        Sequence = "Quote"
      }),
      readonly({
        TalkRole = {1159},
        Content = "AvgDialog_47175_Content_83|余……将为利莫里亚，带来神国。",
        DialogType = 10,
        Sequence = "Quote"
      }),
      readonly({
        TalkRole = {1734},
        Content = "AvgDialog_47175_Content_84|神明……神明庇佑利莫里亚！",
