        DialogType = 10,
        Sequence = "Quote"
      }),
      readonly({
        TalkRole = {1734},
        Content = "AvgDialog_54067_Content_42|“愿您的慧眼洞察灾祸，\n愿您的智慧引领子民！”",
        DialogType = 10,
        RolePos = {0},
        RoleHide = {1734},
        Sequence = "Quote"
      }),
      readonly({
