        Sequence = "SlowCaption",
        AudioAmbient = {
          "Play_A_SFX_Amb_Body_Immersion"
        }
      }),
      readonly({
        TalkRole = {1025},
        Content = "AvgDialog_47170_Content_3|「让家人的拥抱抚慰疲惫的身躯，让故乡的气息治愈你漂泊的灵魂。」",
        DialogType = 6,
        Sequence = "SlowCaption"
      }),
      readonly({
        TalkRole = {1168},
        Content = "AvgDialog_47170_Content_4|「父亲？……」",
        DialogType = 10,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_47170_Content_5|意识和感知逐渐回到了弥利亚姆身上。半梦半醒之间，她感到自己正被温暖的海水包裹。",
        DialogType = 10,
        RoleHide = {1},
