        ShortAudioEffect = {
          "Play_A_SFX_Tinnitus"
        },
        Audio = {
          "Play_A_MUS_Shan_Sea_118BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_47170_Content_6|声音朦朦胧胧地响着，太阳的轮廓穿透海水，影影绰绰地在上方浮现。",
        DialogType = 10
      }),
      readonly({
        Content = "AvgDialog_47170_Content_7|这是一场无梦的长眠。弥利亚姆不知道自己睡了多久，或许一整天？或是一个星期？",
        DialogType = 10
      }),
      readonly({
        Content = "AvgDialog_47170_Content_8|意识逐渐地清晰起来，和她的身体整合在一起。隐约中，一群人从海面上向她伸出手。",
        DialogType = 10,
        ShortAudioEffect = {
          "Play_A_SFX_LoJeiSi_Plaster_Ocean"
        }
      }),
      readonly({
        Content = "AvgDialog_47170_Content_9|父亲，母亲，妹妹，老主祭，王，黛博拉……他们一起伸出手，向她发出了邀请。",
        DialogType = 10
      }),
      readonly({
        TalkRole = {1025},
        Content = "AvgDialog_47170_Content_10|「醒来吧，回到家人的怀抱……」",
        DialogType = 10
      }),
      readonly({
        TalkRole = {1168},
        Content = "AvgDialog_47170_Content_11|「父亲！……」",
        DialogType = 10,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Out_Of_Water"
        }
      }),
      readonly({
        Content = "AvgDialog_47170_Content_12|她猛然睁开眼，跃出海面。",
        DialogType = 10,
        RoleHide = {1},
        BgID = {
          "SScene_PalaceHallDay"
        },
        BgTransition = 2,
        AudioAmbient = {
          "Play_A_SFX_Amb_Inthe_ExhibitionHall"
        }
      }),
      readonly({
        TalkRole = {1750},
        Content = "AvgDialog_47170_Content_13|「醒了！塔利斯老爷，她醒了！」",
        DialogType = 10,
        RoleHide = {1},
        Sequence = "FadeDarkRole(1750,1)",
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "Scared"
        },
        Content = "AvgDialog_47170_Content_14|「这里是？……」",
        DialogType = 10
      }),
      readonly({
        Content = "AvgDialog_47170_Content_15|弥利亚姆身处一个宽阔豪华的大厅之中，跪在地上一圈仪式法阵中央。",
        DialogType = 10,
        RoleHide = {1},
        AudioTalk = {
          "Play_A_SFX_Lightly_Clothes_Rub_01"
        }
      }),
      readonly({
        Content = "AvgDialog_47170_Content_16|周围的人长着她从未见过的脸，穿着她从未见过的服饰，激动地大喊大叫。",
        DialogType = 10
      }),
      readonly({
        Content = "AvgDialog_47170_Content_17|一个中年男人站在法阵外，疲惫又兴奋地望着她。",
        DialogType = 10
      }),
      readonly({
        TalkRole = {1728},
        Content = "AvgDialog_47170_Content_18|「成功了……我召唤出了魔像！我研究了一辈子……终于成功了！！」",
        DialogType = 10,
        RolePos = {2},
        RoleShake = {0},
        Sequence = "FadeDarkRole(1728,1);SetRole(1168,4,EyeOpen)",
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "EyeOpen"
        },
        Content = "AvgDialog_47170_Content_19|「王……王去了哪？这里不是利莫里亚？」",
        DialogType = 10,
        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_47170_Content_20|那个看上去有些面熟的侍女疑惑地盯着她。",
        DialogType = 10
      }),
      readonly({
        TalkRole = {1750},
        Content = "AvgDialog_47170_Content_21|「利莫里亚？那是什么？」",
        DialogType = 10,
        RolePos = {0},
        RoleHide = {1750}
      }),
      readonly({
        TalkRole = {1728},
        Content = "AvgDialog_47170_Content_22|「大概是个什么古老的文明之类的……谁知道呢？」",
        DialogType = 10,
        RolePos = {2},
        Sequence = "FadeDarkRole(1728,1)"
      }),
      readonly({
        TalkRole = {1728},
        Content = "AvgDialog_47170_Content_23|「看她的装束，一定是个很重要的人……我的努力，一定没有白费！」",
        DialogType = 10,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_47170_Content_24|他看着弥利亚姆的目光变得越来越炽热。他走向弥利亚姆，伸出手放在她的额头前。",
        DialogType = 10,
        AudioTalk = {
          "Play_A_SFX_Thouch_Cloth",
          "700"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Normal_Short"
        }
      }),
      readonly({
        TalkRole = {1728},
        Content = "AvgDialog_47170_Content_25|「我是你的链接者……现在，睁开眼，好好看着这一切吧……」",
        DialogType = 10,
        RolePos = {2},
        Sequence = "SetRole(1168,4,EyeOpen);FadeDarkRole(1728,1)"
      }),
      readonly({
        Content = "AvgDialog_47170_Content_26|现实短暂地消失了。无数的信息灌入弥利亚姆的脑海，像是一片海洋将她淹没。",
        DialogType = 10,
        RoleHide = {1},
        ScreenEffect = {"disturb", 1},
        BgID = {
          "SScene_IllusionWhite"
        },
        BgTransition = 2,
        AudioTalk = {
          "Play_A_SFX_The_Remember"
        },
        ShortAudioEffect = {
          "Play_Play_A_SFX_Memory_Confusion"
        },
        Audio = {
          "Play_A_Mus_Tulu_Old_City_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Fog"
        }
      }),
      readonly({
        Content = "AvgDialog_47170_Content_27|她看见了故乡的沉没，看见了海面的变化，看见孤岛与大陆相连。",
        DialogType = 10,
        ShortAudioEffect = {
          "Play_A_SFX_Crashing_Waves"
        }
      }),
      readonly({
        Content = "AvgDialog_47170_Content_28|她看见，新的文明诞生，新的国度建立，新的信徒颂念新的祷词，新的王登上新的王座。",
        DialogType = 10
      }),
      readonly({
        Content = "AvgDialog_47170_Content_29|她看见，漫长的时光在无数个日夜交替中快速流逝，利莫里亚消失在这个世界的记忆里，没有留有任何的痕迹。",
        DialogType = 10,
        ShortAudioEffect = {
          "Play_A_SFX_Wind_Magic"
        }
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "Scared"
        },
