      }),
      readonly({
        TalkRole = {1729},
        Content = "AvgDialog_47168_Content_115|？？！这是……怎么回事？！",
        DialogType = 10,
        RoleShake = {0},
        Sequence = "Quote",
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
      }),
      readonly({
        Content = "AvgDialog_47168_Content_116|绞索仍然还在，但塔利斯感受不到自己对绳索的控制。无论他如何施咒，那条绳索都躺在那里，一动不动。",
        DialogType = 11,
