        RolePos = {4},
        RoleShake = {0},
        Sequence = "Quote",
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
      }),
      readonly({
        TalkRole = {1729},
        Content = "AvgDialog_47168_Content_139|在我的书房……书桌里面……有一本书，记载着我的所有研究结果。",
        DialogType = 10,
        RolePos = {4},
        Sequence = "Quote"
