        Content = "AvgDialog_47168_Content_140|关于魔像的内容，全都写在里面！",
        DialogType = 10,
        RolePos = {4},
        Sequence = "Quote"
      }),
      readonly({
        Content = "AvgDialog_47168_Content_141|弥利亚姆看了他一眼，点了点头。",
        DialogType = 10
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "smile"
        },
        Content = "AvgDialog_47168_Content_142|我知道，你说的是真话。",
        DialogType = 10,
        RolePos = {2},
        Sequence = "Quote"
      }),
      readonly({
        TalkRole = {
          1168,
