        RoleHide = {1}
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "EyeOpen"
        },
        Content = "AvgDialog_47167_Content_96|你享受它，不是吗？",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {
          1166,
          nil,
          "threat"
        },
        Content = "AvgDialog_47167_Content_97|厉害啊……女巫大人……",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "EyeOpen"
        },
        Content = "AvgDialog_47167_Content_98|告诉我你知道的信息，在这之后，我将赐予你一个轻松的死亡。",
