        ShortAudioEffect = {
          "Play_A_SFX_Lightly_Clothes_Rub_02"
        }
      }),
      readonly({
        Content = "AvgDialog_47166_Content_15|如今，她再次出现在了这里。很快，她就会将利莫里亚重新带回这片海域。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "EyeOpen"
