      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "EyeOpen"
        },
        Content = "AvgDialog_47166_Content_19|唤醒王，需要找到王死后留下的银色物质，这是仪式的必需品。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {
