        ShortAudioEffect = {
          "Play_A_SFX_Water_Board_02"
        }
      }),
      readonly({
        TalkRole = {1730},
        Content = "AvgDialog_47166_Content_93|戈利亚大人，看来您的心情不错。这个太阳，也让您想起了非利士故乡的海岸了吧？",
