  [48139] = {
    ID = 48139,
    CnID = "繁衍狂欢_希洛",
    BaseSortID = 15,
    data_list = readonly({
      readonly({
        BaseSortID = 15,
        Content = "AvgDialog_48139_Content_1|——哗啦。",
        DialogType = 3,
        BgID = {
          "SScene_Black"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Chain_Steps_01"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_train_run"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_48139_Content_2|起身的动作牵动了链条，金属碰撞的声响在黑暗中不断回荡。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1025},
        Content = "AvgDialog_48139_Content_3|你醒了，事不宜迟，让我们开始吧。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48139_Content_4|这声音是……希洛？！你这是干什么？我以为我们之间那些误会什么的已经解开了。",
        DialogType = 2,
        ScreenEffect = {
          "awake",
          1,
          1
        },
        BgID = {
          "SScene_InsideSubway_Dark"
        },
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        Sequence = "SetRole(1138,3)",
        Audio = {
          "Play_A_Mus_Xiluo_Corruption_Chp3_118BPM"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48139_Content_5|现在把我绑在这里又是怎么回事？",
        DialogType = 2,
        ScreenEffect = {"awake", 2},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx"
      }),
      readonly({
        TalkRole = {
          1138,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_48139_Content_6|确实……我们之间已经不存在立场冲突了。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48139_Content_7|希洛在你面前单膝跪下，用手中的黏液腐蚀了束缚在你腿上的铁链。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_GetUp"
        }
      }),
      readonly({
        TalkRole = {1138, nil},
        Content = "AvgDialog_48139_Content_8|给你解开了，但别想着跑。这个地下轨道已经在我们的战斗中废弃了，你也不会找到其他帮手的。",
        DialogType = 1,
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Chain_Steps"
        }
      }),
      readonly({
        TalkRole = {
          1138,
          nil,
          "Avoid"
        },
        Content = "AvgDialog_48139_Content_9|我需要你帮我一个忙。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48139_Content_10|如果是帮忙的话，大可以直接来弥萨格找我——唔？！",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_48139_Content_11|她单手扼上了你的咽喉，周身的黏液变换成锋利的尖刃划开了校服领口。刃面抵在颈间，让你的每次呼吸都处于危险之中。",
        DialogType = 3,
        RoleHide = {1},
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        AudioTalk = {
          "Play_A_SFX_Thouch_Cloth"
        },
        ShortAudioEffect = {
          "Play_A_SFX_The_Blade_Crossed_02",
          "100"
        }
      }),
      readonly({
        TalkRole = {
          1138,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_48139_Content_12|嘘……安静些。这些疱种不能受惊吓。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48139_Content_13|一根手指压上了你的嘴唇，在希洛的示意下，你看向她身后的脓疱——",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Caress02"
        }
      }),
      readonly({
        TalkRole = {1138},
        Content = "AvgDialog_48139_Content_14|这些新生的脓疱自我分裂而来，但它们尚无自我意识……无法成为我复仇的助力。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48139_Content_15|还不够有自我意识吗？",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_48139_Content_16|脓疱表现得异常活跃，它们现在贴在你的脚边，互相碰撞间发出咕叽咕叽的怪声。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Tentacles_SuckBlood",
          "Play_A_SFX_Tentacles_StickOut"
        }
      }),
      readonly({
        TalkRole = {
          1138,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_48139_Content_17|不够，所以我需要你帮助我。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48139_Content_18|我？",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_48139_Content_19|希洛强硬地拉着你的手，按在了裸露的大腿上，黏腻的触感悄无声息地滑进了裂开的领口。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Thouch_Cloth"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48139_Content_20|喂？！希洛你要做什么？！",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
      }),
      readonly({
        Content = "AvgDialog_48139_Content_21|它们湿润地走过每一寸肌肤，像淌入河床的水流，顺着肌肉的纹理不断向下。",
        DialogType = 3,
        AudioTalk = {
          "Play_A_SFX_Tentacles_StickOut",
          "300"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Slime_Squirm_Input",
          "Play_A_SFX_Tentacles_SuckBlood"
        }
      }),
      readonly({
        Content = "AvgDialog_48139_Content_22|它们的主人扣住了你的手，殷红的双眼格外明艳，似乎马上就要燃烧殆尽。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Thouch_Hand"
        }
      }),
      readonly({
        TalkRole = {1138},
        Content = "AvgDialog_48139_Content_23|用你的知能，赐予它们真正的「意识」。",
        DialogType = 1,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [48142] = {
    ID = 48142,
    CnID = "繁衍狂欢_萨尔瓦多",
    BaseSortID = 16,
    data_list = readonly({
      readonly({
        BaseSortID = 16,
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_1|您百忙之中能抽出宝贵时间，专程赶来大圣堂。这份恩情，我将没齿难忘。",
        DialogType = 1,
        BgID = {
          "SScene_ChurchDay"
        },
        Audio = {
          "Play_A_MUS_Sarewa_Chuch_91BPM",
          "200"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Mist"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48142_Content_2|没有的事，只要能帮上萨尔瓦多主教的忙……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_48142_Content_3|告解室昏暗逼仄，你在橡木椅子上如坐针毡，但自己为什么会被叫过来的「好奇」远远盖过了惶恐。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Lightly_Clothes_Rub_01"
        }
      }),
      readonly({
        Content = "AvgDialog_48142_Content_4|通常而言，萨尔瓦多才是那个坐在告解室里的人。可你一赶来大圣堂，他就让你坐进了这里，一定有特殊的原因。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_5|请允许我略去更多的繁文缛节，苍白之火，并聆听我的忏悔。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_6|近日，我……不知为何浮现出了不应当的渴望。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48142_Content_7|他的声音像远山中的回音，一点点沉降、渗透进告解室古老的木壁。低沉的嗓音束缚住了一头无名的野兽，唯恐牠触及那不可视的禁忌。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_8|我必须承认，尽管我知晓这些欲望，却不曾真切体会过它们，更不知道它们是如何盖过父神的荣光，侵染我的内心的。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_9|但，正如医者同样需要医治，恐怕我这个代行者，也需要向父神的使者告解，请求指引与宽恕。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48142_Content_10|……我知道了。\n勒姆瓦希圣树的崩解，让世界各地的唤醒体都出现了强烈的……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48142_Content_11|咳、咳，强烈的……",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx"
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_12|原来如此，是受到了异常催化的「繁衍的欲望」在呼唤我。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_13|抱歉，我失态了。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48142_Content_14|……不，没有的事。我、我宽恕您的罪过，这么说就可以了吗？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_15|是我疏忽了，您没有参与告解的经验。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48142_Content_16|萨尔瓦多打开了告解室的小窗，将双手搭在了窗棂上，手心向上面对着你。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Door_Sliding"
        }
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_17|如果可以的话，请握住我的手吧。",
        DialogType = 1,
        Audio = {
          "Play_A_MUS_Sarewa_Cure_73BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_48142_Content_18|（伸出双手）",
        DialogType = 5
      }),
      readonly({
        Content = "AvgDialog_48142_Content_19|即使你们都带着手套，也无法阻隔他那异常的体温。像灵魂沸腾时升起的热焰，不可抵抗地灼烧着你的血脉。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Lightly_Clothes_Rub_02"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Floodlight"
        }
      }),
      readonly({
        Content = "AvgDialog_48142_Content_20|胸口的银钥也灼热发烫，让你们的灵魂一层层剥落，只留下最赤裸、袒露的内核。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_21|接下来，请复述我的话。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_22|罪如枷锁，但赦免与救赎的钥匙，亦存于枷锁之上。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48142_Content_23|罪如枷锁，但赦免与救赎的钥匙，亦存于枷锁之上。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_48142_Content_24|内心被德行之苦焚尽，他已尝恶果。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48142_Content_25|内心被德行之苦焚尽，他已尝恶果……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_48142_Content_26|一道闪电般的灵感弥合了脑中的文字，在萨尔瓦多说下去前，一种本能控制着你先一步出了声。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48142_Content_27|……仁慈的父神，请允他光明地行走，请宽恕他的罪。",
        DialogType = 7,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {
          1135,
          nil,
          "smile"
        },
        Content = "AvgDialog_48142_Content_28|您也听见了父神的指引……",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1135,
          nil,
          "smile"
        },
        Content = "AvgDialog_48142_Content_29|苍白的使者，感谢您再次驱散了我的黑暗。",
        DialogType = 1,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [48238] = {
    ID = 48238,
    CnID = "繁衍狂欢_莉兹",
    BaseSortID = 17,
    data_list = readonly({
      readonly({
        BaseSortID = 17,
        TalkRole = {1001},
        Content = "AvgDialog_48238_Content_1|有好一些了吗，莉兹？",
        DialogType = 2,
        BgID = {
          "SScene_OperaHouse"
        },
        Sequence = "SetRole(1146,3,ShutEye)",
        Audio = {
          "Play_A_MUS_Emo_89BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Inthe_ExhibitionHall"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_48238_Content_2|空无一人的剧院里，少女摇了摇头。你听见她紊乱的呼吸，看见她在暗淡光线下微微发红的脸颊。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Caress03"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48238_Content_3|本来以为，剧院能让你心情平静下来，消除掉圣河的影响。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48238_Content_4|或许可以做点别的什么来转移一下注意力。我想想……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_48238_Content_5|绿色的眼眸闪动，黑色的裙摆在你面前划出一道弧线，少女熟练地登上了舞台。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_Stage"
        },
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_GetUp"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48238_Content_6|我以为，你现在对跳舞这件事仍有心结……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1146,
          nil,
          "Smile"
        },
        Content = "AvgDialog_48238_Content_7|我可没说要跳。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48238_Content_8|那你的意思是……？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1146,
          nil,
          "Smile"
        },
        Content = "AvgDialog_48238_Content_9|我来教你跳舞吧，守密人。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48238_Content_10|一只手从台上伸出，优雅地递到你面前。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Lightly_Clothes_Rub_02"
        }
      }),
      readonly({
        TalkRole = {
          1001,
          "UI_Story_D_Image_Face_Surprise2.png"
        },
        Content = "AvgDialog_48238_Content_11|我？可是我从来没……喂……",
        DialogType = 2,
        Audio = {
          "Stop_Avg_Mus"
        },
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        Content = "AvgDialog_48238_Content_12|没等你说完，那只手不由分说将你拉到了台上。",
        DialogType = 3,
        RoleHide = {1},
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_GetUp"
        }
      }),
      readonly({
        TalkRole = {1146, nil},
        Content = "AvgDialog_48238_Content_13|……请扶住我的腰，守密人。",
        DialogType = 1,
        Audio = {
          "Play_A_MUS_Dreamy_Memories_109BPM"
        }
      }),
      readonly({
        TalkRole = {1146, nil},
        Content = "AvgDialog_48238_Content_14|我还是没有办法跳舞，但我想，我可以把那些美丽的动作教给你。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1146,
          nil,
          "smile"
        },
        Content = "AvgDialog_48238_Content_15|要帮我解决圣河的影响，这可是你自己说的……",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48238_Content_16|那只手领着你搭在腰间的那一刻，匀称的身体颤动了一下。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Caress02"
        }
      }),
      readonly({
        Content = "AvgDialog_48238_Content_17|指腹传来绸缎冰凉的触感。绸缎之下，柔软、紧致的腰腹随着呼吸微微起伏着。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Caress"
        }
      }),
      readonly({
        TalkRole = {
          1001,
          "UI_Story_D_Image_Face_Sweat.png"
        },
        Content = "AvgDialog_48238_Content_18|我完全没有接触过芭蕾……这样真的可以吗？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1146,
          nil,
          "Smile"
        },
        Content = "AvgDialog_48238_Content_19|跟着音乐，做你想做的事，就好了。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1146,
          nil,
          "Smile"
        },
        Content = "AvgDialog_48238_Content_20|请记住，芭蕾的秘密，是旋转。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48238_Content_21|从双手到腰腹，从腰腹到双腿。舞者带领着你，完成每一个优雅的动作，感受她身体每一个部位细微的变化。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "CGDynamic_C01_012"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Show_Sash"
        }
      }),
      readonly({
        Content = "AvgDialog_48238_Content_22|踢腿。下腰。跳跃。",
        DialogType = 3,
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        Content = "AvgDialog_48238_Content_23|轻灵的音乐在空无一人的剧院回荡，一道清冷光束追随着舞台上的你们。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_48238_Content_24|你们一同旋转着。莉兹脸色愈发绯红，绿色的双眸带着羞怯望着你。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48238_Content_25|我跳得怎么样？",
        DialogType = 2,
        BgID = {
          "SScene_Stage"
        },
        Sequence = "SetRole(1146,3,Shy)"
      }),
      readonly({
        TalkRole = {
          1146,
          nil,
          "Smile"
        },
        Content = "AvgDialog_48238_Content_26|一无是处。但这会是我最喜欢的舞蹈表演，守密人。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48238_Content_27|我们要不要转慢一点？我觉得有点……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_48238_Content_28|绿色的眼眸轻轻合上，冰冷的双唇吻住了你。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        Sequence = "SetRole(1146,3,ShutEye)",
        ShortAudioEffect = {
          "Play_A_SFX_Caress"
        }
      }),
      readonly({
        Content = "AvgDialog_48238_Content_29|旋转。旋转。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_48238_Content_30|白色的发丝随风飘扬，翠绿的火焰包裹住你们，没有任何温度，随着音乐一同跃动。黑绿相间的舞蹈服，在空中划出天鹅般的弧线。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_48238_Content_31|晕眩。你想说晕眩。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_48238_Content_32|莉兹越来越沉重的呼吸拍打在你的脸上，你下意识双臂用力，环住她的腰，沉重的力度让她微微皱起眉。你们旋转着。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Caress03"
        }
      }),
      readonly({
        TalkRole = {
          1146,
          nil,
          "Smile"
        },
        Content = "AvgDialog_48238_Content_33|请记住，守密人。芭蕾的秘密，是旋转……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_48238_Content_34|今夜，剧院的流光下，一对舞者迷失在旋转里。",
        DialogType = 3,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [48556] = {
    ID = 48556,
    CnID = "繁衍狂欢_汀克特",
    BaseSortID = 18,
    data_list = readonly({
      readonly({
        BaseSortID = 18,
        TalkRole = {
          1149,
          nil,
          "Shy"
        },
        Content = "AvgDialog_48556_Content_1|守密人，如果方便的话，您是否现在能为我稍加驻足？",
        DialogType = 1,
        BgID = {
          "SScene_ExamineRoom"
        },
        Audio = {
          "Play_A_Mus_Peace_Talk_Ver2_118BPM",
          "500"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48556_Content_2|当然，最近在学校里遇上什么不开心的事情了吗？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1149},
        Content = "AvgDialog_48556_Content_3|不、不……并不是这么回事。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1149,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_48556_Content_4|只是我有一首歌，无论如何……都想要唱给你听。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48556_Content_5|你点点头，再度坐在了休息室软塌上——只是一首歌而已。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_GetUp"
        }
      }),
      readonly({
        Content = "AvgDialog_48556_Content_6|唤醒体眉眼间的不安消弭于须臾，精致得不似凡物的脸上展开一个你看不懂的笑容——",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Caress03"
        }
      }),
      readonly({
        TalkRole = {
          1149,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_48556_Content_7|只是因您而诞生的歌，也是只为您而唱的歌。",
        DialogType = 1,
        BgID = {
          "CGDynamic_C01_012"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Sunlight"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Floodlight"
        }
      }),
      readonly({
        Content = "AvgDialog_48556_Content_8|意识在歌声入耳时，被裹挟着深入了一片迷离的幻境中。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_GnosticSpace"
        },
        BgTransition = 4,
        Audio = {
          "Play_A_Mus_Consciousness_95BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_48556_Content_9|汀克特的歌声绕过了理智的防线，顺着肉体的缝隙潜进了灵魂——",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_48556_Content_10|那绝非卡达斯应有的旋律，贯入颞横回的声音一如寰宇般幽魅，又闪亮着点点晨星的温柔。",
        DialogType = 3,
        ScreenEffect = {"starlight", 1},
        BgID = {
          "CGDynamic_C00M_02WhiteOut"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Sunlight",
          "500"
        }
      }),
      readonly({
        Content = "AvgDialog_48556_Content_11|意识成为了一艘无舵的船，在汀克特歌声的牵引下，漂泊向欲望的彼岸。",
        DialogType = 3,
        BgID = {
          "SScene_White"
        }
      }),
      readonly({
        Content = "AvgDialog_48556_Content_12|唇角印下了冰冷湿润的触感，咽喉中窜起无名的暗火。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_48556_Content_13|再次睁眼，汀克特也正在抬头，她的嘴唇看起来格外湿润饱满。",
        DialogType = 3,
        ScreenEffect = {"starlight", 2},
        BgID = {
          "SScene_ExamineRoom"
        },
        BgTransition = 2,
        Sequence = "SetRole(1149,3,Shy)",
        Audio = {
          "Play_A_Mus_Peace_Talk_Ver1_118BPM"
        },
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        Content = "AvgDialog_48556_Content_14|一个难以置信答案在你的嘴边呼之欲出，但理智很快被再次落在唇边的吟诵卷走。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_48556_Content_15|歌声玩弄着内心深处的不堪欲望，现实与幻想的界限再次模糊，无力抗拒，也无力逃脱。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1149,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_48556_Content_16|嘘……只此夜，请成为我歌声的俘虏……",
        DialogType = 1,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [48555] = {
    ID = 48555,
    CnID = "繁衍狂欢_菲茵特",
    BaseSortID = 19,
    data_list = readonly({
      readonly({
        BaseSortID = 19,
        Content = "AvgDialog_48555_Content_1|走过教学楼的又一个转角，从今早就萦绕着你的低气压变得更加严重，挤压得你几乎无法呼吸。",
        DialogType = 3,
        BgID = {
          "SScene_SchoolNight"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Normal_Short"
        },
        Audio = {
          "Play_A_Mus_Peace_Talk_Ver2_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Field_Night"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_48555_Content_2|你扶墙蹲下，动作之间目光捕捉到了一个熟悉的影子一闪而过。",
        DialogType = 3,
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_GetUp"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48555_Content_3|……菲茵特？是你吗？",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_48555_Content_4|白色影子停顿了片刻，最终不再隐藏自己的存在。白色框架载着它的主人飘浮到了你身前。",
        DialogType = 3,
        Sequence = "SetRole(1143,3,Sad)",
        ShortAudioEffect = {
          "Play_A_SFX_Sunlight"
        }
      }),
      readonly({
        TalkRole = {1143, nil},
        Content = "AvgDialog_48555_Content_5|……守密人。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48555_Content_6|她向你伸出手，似乎想要爬出「摇篮」——但离开「摇篮」这个限制器，只会让她的本能更加肆无忌惮。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Lightly_Clothes_Rub_01"
        }
      }),
      readonly({
        Content = "AvgDialog_48555_Content_7|菲茵特很快意识到了自己的异常，于是最终只抿着嘴，拧掉了「摇篮」上最靠近她身体的球囊。",
        DialogType = 3,
        Sequence = "SetRole(1143,3,Serious)"
      }),
      readonly({
        TalkRole = {
          1143,
          nil,
          "Shy"
        },
        Content = "AvgDialog_48555_Content_8|请收下……收下这个。",
        DialogType = 1,
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        Content = "AvgDialog_48555_Content_9|你伸出手，取球囊时指尖触到了她柔软的掌心。菲茵特立刻浑身一颤，蜷缩着躲进了摇篮的更深处。",
        DialogType = 3,
        RoleShake = {1143},
        ShortAudioEffect = {
          "Play_A_SFX_Caress02"
        },
        Audio = {
          "Play_A_Mus_Peace_Talk_Ver1_118BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_48555_Content_10|球囊在你的掌心发散着微弱的荧光，涌动着磅礴的生命力。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_White"
        },
        BgTransition = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Sunlight02"
        }
      }),
      readonly({
        Content = "AvgDialog_48555_Content_11|半透明的囊壁中，形似蝉翼的枝条双双合拢，它无规律地不时振翅，仿佛正处于一场绵长的梦境中。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Meteor_Passing_By_01"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48555_Content_12|这是……？",
        DialogType = 2,
        BgID = {
          "SScene_SchoolNight"
        },
        BgTransition = 3,
        Sequence = "SetRole(1143,3,Shy)"
      }),
      readonly({
        Content = "AvgDialog_48555_Content_13|菲茵特见你没有拒绝她的礼物，这才长舒一口气，露出了满足的笑。",
        DialogType = 3,
        Sequence = "SetRole(1143,3,Smile)"
      }),
      readonly({
        TalkRole = {
          1143,
          nil,
          "smile"
        },
        Content = "AvgDialog_48555_Content_14|是我们@2一族的新生种，只要是成熟的我们，都会结出这样的果实。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1143,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_48555_Content_15|在过去那么久那么久的时间里，我从来没有发过芽……我原本以为，我永远都不会成为完整的@2。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48555_Content_16|<Small:异常发育……又是勒姆瓦希那边带来的影响。>",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48555_Content_17|菲茵特现在感觉如何呢？发芽以后，身体有没有其他异常？",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_48555_Content_18|菲茵特摇了摇头，稚嫩的脸上写满欣喜。",
        DialogType = 3,
        Sequence = "SetRole(1143,3,Smile)",
        ShortAudioEffect = {
          "Play_A_SFX_Caress02"
        }
      }),
      readonly({
        TalkRole = {
          1143,
          nil,
          "smile"
        },
        Content = "AvgDialog_48555_Content_19|很热……脑袋、四肢都感觉很热。或许这就是汀克特说过的，成为大人的感觉？",
        DialogType = 1,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [48597] = {
    ID = 48597,
    CnID = "繁衍狂欢_宁菲亚",
    BaseSortID = 20,
    data_list = readonly({
      readonly({
        BaseSortID = 20,
        TalkRole = {1001},
        Content = "AvgDialog_48597_Content_1|冷静下来了吗？",
        DialogType = 2,
        BgID = {
          "SScene_BedRoom"
        },
        Sequence = "SetRole(1128,3,sad)",
        Audio = {
          "Play_A_Mus_Peace_Talk_Ver1_118BPM",
          "500"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Bedroom"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        TalkRole = {
          1128,
          nil,
          "sad"
        },
        Content = "AvgDialog_48597_Content_2|啊、嗯，抱歉……",
        DialogType = 1,
        RoleShake = {0}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48597_Content_3|别担心，最近大家都受到圣河泛滥的影响，有些超出常规的举动也在意料之中。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1128,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_48597_Content_4|我明白，只是……与我太过深入的接触，便会被我体内的“毒”侵染。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48597_Content_5|你望向自己的手掌，刚才触及宁菲亚那枯瘦妖异骨骼之处，已泛起淡淡的青紫。",
        DialogType = 3,
        RoleHide = {1},
        AudioAmbient = {
          "Play_A_SFX_Lightly_Clothes_Rub_01"
        }
      }),
      readonly({
        TalkRole = {1128, nil},
        Content = "AvgDialog_48597_Content_6|我知道……我知道怎么治愈它。\n请您跟我来。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48597_Content_7|海潮呼啸，腥咸的海风拂起宁菲亚鬓边的软发，她抬手压了压帽檐，黑色的绢花随着她的动作轻晃。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_SeasideNight"
        },
        BgTransition = 6,
        ShortAudioEffect = {
          "Play_A_SFX_Waters_PourForth"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Sea"
        }
      }),
      readonly({
        TalkRole = {1128},
        Content = "AvgDialog_48597_Content_8|这具骨骼中富集的毒素，会消融于海水中。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1128},
        Content = "AvgDialog_48597_Content_9|既然“解药”已经近在咫尺了，我能提一个任性的要求吗？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1128,
          nil,
          "shy"
        },
        Content = "AvgDialog_48597_Content_10|我想要……像刚才那样，再次拥抱您。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48597_Content_11|你点了点头。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Caress02"
        }
      }),
      readonly({
        Content = "AvgDialog_48597_Content_12|然后，冰冷的躯干贴上了你。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Thouch_Cloth"
        },
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        TalkRole = {
          1128,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_48597_Content_13|在疗养院的那些日子，我从未体会过这样的温暖。\n若是有您一直在身边，那该有多好……",
        DialogType = 1,
        RolePos = {
          2,
          "AvgHorizontal"
        },
        Audio = {
          "Play_A_MUS_PeaceTalk_Comfort_118BPM"
        }
      }),
      readonly({
        TalkRole = {
          1128,
          nil,
          "sad"
        },
        Content = "AvgDialog_48597_Content_14|这种温暖就像另一种毒药，渐渐将我吞噬。\n我时常会想，若是海水终究还是将我们分离了，那该是多么孤独啊……",
        DialogType = 1,
        RolePos = {
          2,
          "AvgHorizontal"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_48597_Content_15|你可以一直留在这里的。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_48597_Content_16|静默持续了数十秒，直到凝滞的呼吸又恢复正常，她才轻轻松开你。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Lightly_Clothes_Rub_02"
        }
      }),
      readonly({
        TalkRole = {1128},
        Content = "AvgDialog_48597_Content_17|我们走吧，该去“治疗”了。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_48597_Content_18|宁菲亚牵着你的手，一步一步陷入海的怀抱。\n海水轻柔地抬起她衣摆，如同承托一朵缓缓绽放的淡紫睡莲。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Crashing_Waves"
        }
      }),
      readonly({
        Content = "AvgDialog_48597_Content_19|她的手很冷，目光却几乎将你烫伤。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1128,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_48597_Content_20|您安心吧，海水会荡涤我留在您身体里的毒。",
        DialogType = 1,
        RolePos = {
          2,
          "AvgHorizontal"
        }
      }),
      readonly({
        TalkRole = {1128},
        Content = "AvgDialog_48597_Content_21|至于您留在我心中的“毒”……我会好好珍藏的。",
        DialogType = 1,
        RolePos = {
          2,
          "AvgHorizontal"
        },
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [48598] = {
    ID = 48598,
    CnID = "繁衍狂欢_达芙黛尔",
    BaseSortID = 21,
    data_list = readonly({
      readonly({
        BaseSortID = 21,
        Content = "AvgDialog_48598_Content_1|你认得这里，你曾在某次事件中，被此地的主人迎入过这个空间。",
        DialogType = 3,
        BgID = {
          "SScene_Black"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_48598_Content_2|仰躺在深色的水面上，你的眼睛对着灰白的太阳，身边的头颅嬉笑着、互相辱骂着、独自哀叹着。",
        DialogType = 3,
        BgID = {
          "SScene_HyleSeaPeace"
        },
        BgTransition = 2,
        ShortAudioEffect = {
          "Play_A_SFX_Bubbles_Surge_01"
        },
        Audio = {
          "Play_A_MUS_Dafudaier_Sea_120BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_PristineOcean"
        }
      }),
      readonly({
        Content = "AvgDialog_48598_Content_3|它们接踵而至，撞在你的胳膊上，叫你险些面朝下栽进水面——",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_AVG_Diving",
          "Play_A_SFX_Tap_Stone"
        }
      }),
      readonly({
        Content = "AvgDialog_48598_Content_4|原质之海，维度魔女的藏身处，达芙黛尔的至为珍贵之所。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_48598_Content_5|你为什么会在这里？是又一次达芙黛尔的邀请吗？还是说，这只是一场荒诞的梦……",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_48598_Content_6|你的四肢舒展着，任由原质之海将你推向不存在的彼岸。难以计数的头颅在灰色海浪中相互推搡，骨头碰撞的声音清脆又瘆人。",
