  [49095] = {
    ID = 49095,
    CnID = "繁衍狂欢_图鲁",
    BaseSortID = 27,
    data_list = readonly({
      readonly({
        BaseSortID = 27,
        Content = "AvgDialog_49095_Content_1|你在向梦的更深处坠落。",
        DialogType = 3,
        BgID = {
          "C05/Video_C05_02.mp4"
        },
        BgTransition = 2,
        Audio = {
          "Play_A_MUS_Peace_Sad_103BPM",
