  [100303] = {
    ID = 100303,
    CnID = "繁衍狂欢_皮克曼",
    BaseSortID = 51,
    data_list = readonly({
      readonly({
        BaseSortID = 51,
        TalkRole = {
          1962,
          nil,
          "Nervous"
        },
        Content = "AvgDialog_100303_Content_1|呼……呼……不对……还是不对……",
        DialogType = 1,
        BgID = {
          "SScene_ExhibitionSp_Normal"
        },
        AudioTalk = {
          "Play_A_SFX_Turn_Jump"
        },
        Audio = {
