        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        Audio = {
          "Play_A_SFX_Shit"
        },
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        Content = "AvgDialog_22127_Content_98|在蜿蜒的轨道上，一只巨大的毛毛虫停在你们面前。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1570,
          nil,
          "Surprised"
        },
        Content = "AvgDialog_22127_Content_99|啊！和我想的一样！是毛毛虫电车！",
        DialogType = 1,
        RoleShake = {0}
      }),
      readonly({
        TalkRole = {1556},
        Content = "AvgDialog_22127_Content_100|您好，如果不坐车的话，我就要开走了。还有其他客人在等着呢。",
        DialogType = 1,
        RolePos = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Caterpillar_Talk_B"
        }
      }),
      readonly({
        Content = "AvgDialog_22127_Content_101|你警惕地注视着它。毛毛虫电车看上去似乎没有敌意。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_22127_Content_102|请问，这辆车能到美第奇大道吗？",
