        Content = "AvgDialog_22125_Content_29|轰轰——",
        DialogType = 1,
        BgID = {
          "SScene_PoetryStreet1"
        },
        BgTransition = 1,
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
