        }
      }),
      readonly({
        TalkRole = {1789},
        Content = "AvgDialog_22132_Content_2|救火！快救火啊！",
        DialogType = 1,
        RolePos = {2},
        RoleShake = {0},
        ScreenEffect = {
          "retro",
          1,
          "flame",
          1
        },
        BgID = {
