        Audio = {
          "Play_A_SFX_Cut_Rope"
        }
      }),
      readonly({
        Content = "AvgDialog_22111_Content_88|一朵玫瑰被剪下。柯蕾特拿着它，递到了奥尔拉面前。",
        DialogType = 3,
        RoleHide = {1},
