          "SScene_CG_SD_L_D06_3"
        },
        BgTransition = 2,
        Audio = {
          "Play_A_SFX_Show_Something"
        }
      }),
      readonly({
        TalkRole = {
          1784,
          nil,
          "sad"
        },
        Content = "AvgDialog_22111_Content_89|一首好诗，奥尔拉……我就用我的花，来换你的诗吧。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_22111_Content_90|砰——",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "CGDynamic_SD_L_D06_4"
        },
        AnimState = "CG/CG_SD/Prefab/CGDynamic_SD_L_D06_4.prefab",
        ShortAudioEffect = {
