        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {
          1128,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_22128_Content_6|我不知道奥尔拉在哪。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_22128_Content_7|啊？！怎么可能！她都已经回来一天了，都还没联系你吗！",
        DialogType = 1,
        RolePos = {4},
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_emmm"
        }
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_22128_Content_8|难道外界关于你们两个关系不好的传闻是真的？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_22128_Content_9|是因为文学爱好者之间的互相轻贱吗？还是因为成为了情敌？！",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1128},
        Content = "AvgDialog_22128_Content_10|……我还有点事，请允许我先告辞……",
        DialogType = 1,
        RolePos = {2},
        RoleExit = {1128},
        ExitDirection = {"1128:1"}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_22128_Content_11|喂喂喂！宁菲亚小姐！",
