        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        Sequence = "SetRole(1799,3)",
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
      }),
      readonly({
        TalkRole = {1799},
        Content = "AvgDialog_58289_Content_41|抱歉，守密人%sirormadam%！你刚才似乎太专注了。我叫了你好几声……",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1800},
        Content = "AvgDialog_58289_Content_42|你不记得我了吗？我是艾尔莎，我们一起上过朵尔小姐的融蚀导论。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
