        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_58289_Content_68|莱克先生？！",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Ops"
        }
      }),
      readonly({
        Content = "AvgDialog_58289_Content_69|莱克收起兽爪，步伐轻快地朝你走了过来。",
