        RolePos = {2},
        Sequence = "SetRole(1574,4)"
      }),
      readonly({
        TalkRole = {1574},
        Content = "AvgDialog_58294_Content_41|真遗憾。最近我一直在反思，自己的样貌是否太过凶恶，以至于大家都害怕我。",
        DialogType = 1,
