          "Play_A_SFX_Hit_Jump_Shock"
        },
        Audio = {
          "Play_A_MUS_Sad_80_8_6_Main"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Starlight"
        }
      }),
      readonly({
        Content = "AvgDialog_58329_Content_64|下一秒，眼前的绘卷消失，黑暗再度回归。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_BlackHole"
        }
      }),
      readonly({
        Content = "AvgDialog_58329_Content_65|没有沙漠、没有祭司和绘卷，你独自一人躺在漆黑的棺材里。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_58329_Content_66|思绪似乎还陷在卡纳克的回忆中，无尽的悲伤将你笼罩。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_58329_Content_67|眼泪再也止不住，就像永远也望不到尽头的雨幕。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_58329_Content_68|<Change>不……我……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_58329_Content_69|<Change>我只是想活着……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_58329_Content_70|咚。咚咚。",
