        RoleHide = {1},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_OldCall_Door_01"
        }
      }),
      readonly({
        TalkRole = {1125},
        Content = "AvgDialog_58326_Content_16|第二个问题，你是我们中的一员吗？这里的“我们”是指进入那家伙密境的人。",
        DialogType = 1,
        RolePos = {
