        DialogType = 3,
        RoleHide = {1},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_OldCall_Door_01"
        }
      }),
      readonly({
        TalkRole = {1125},
        Content = "AvgDialog_58326_Content_18|很好，我的直觉不会骗我。第三个问题……",
        DialogType = 1,
        RolePos = {
          2,
          "AvgHorizontal"
        }
      }),
      readonly({
