  [58332] = {
    ID = 58332,
    CnID = "大型支线_莱克_关卡11_前",
    BaseSortID = 11,
    data_list = readonly({
      readonly({
        BaseSortID = 11,
        Content = "AvgDialog_58332_Content_1|最后的致意",
