      }),
      readonly({
        Content = "AvgDialog_81527_Content_39|仅仅是站起了身，二人主动与被动的关系就好像完全转变了。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_GetUp"
        }
