        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        Content = "AvgDialog_81527_Content_63|卡斯托尔没有理由拒绝这样一根救命稻草。",
        DialogType = 3,
        BgID = {
          "SScene_DesertDay"
        },
