        Audio = {
          "Play_A_MUS_Undergound_Main_104BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Monster_Swarm"
        }
      }),
      readonly({
        Content = "AvgDialog_81523_Content_97|卡斯托尔小心地不发出声响，避开怪物身上一条条蠕动着滴落不明液体的漆黑树枝。",
