        Content = "AvgDialog_81523_Content_113|（苏摩利·波利斯。）",
        DialogType = 1,
        RoleHide = {1134}
      }),
      readonly({
        Content = "AvgDialog_81523_Content_114|卡斯托尔掀开盖布摩挲着箱子上金属刻印的标签，双手颤抖着打开一口口箱子上的锁。",
        DialogType = 3,
        ShortAudioEffect = {
