      readonly({
        Content = "AvgDialog_81523_Content_136|刚刚检查完其他箱子的商队成员睁着几双充满困惑的眼睛，直直对上了箱子里波吕克斯同样茫然的双眼。",
        DialogType = 3,
        RoleHide = {1922},
