        BgID = {
          "SScene_Black"
        },
        BgTransition = 4,
        ShortAudioEffect = {
          "Play_A_SFX_Church_Door"
        }
      }),
      readonly({
        Content = "AvgDialog_71794_Content_14|几个小萝卜头似的孩子探头探脑、鬼鬼祟祟钻进了神殿。",
        DialogType = 3,
        ShortAudioEffect = {
