        ShortAudioEffect = {
          "Play_A_SFX_OMG"
        }
      }),
      readonly({
        TalkRole = {1132},
        Content = "AvgDialog_80279_Content_7|珈伦跟主人讲哦，珈伦感觉自己来到了一个大大大宴会！",
