        DialogType = 6,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        Sequence = "MiddleCaption"
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_89879_Content_14|这里就是塞勒菲斯？",
