      readonly({
        ChatID = "CH1",
        NextChatID = {"A1", "A2"},
        TalkRole = {1001},
        Content = "AvgDialog_89879_Content_17|奇怪，这里怎么一个人都没有……",
        DialogType = 2,
        RoleHide = {1},
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
