  [89875] = {
    ID = 89875,
    CnID = "支线剧情_1.5周年_战斗1",
    BaseSortID = 2,
    data_list = readonly({
      readonly({
        BaseSortID = 2,
        Content = "AvgDialog_89875_Content_1|尽管萨尔瓦多竭尽全力，黑色的粘液却不断扩散，彻底将那头驴吞噬殆尽。",
