        DialogType = 1,
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        Content = "AvgDialog_89875_Content_4|萨尔瓦多没有说话，他静默地站在原地，浑身充满了悲伤。",
        DialogType = 3,
        RoleHide = {1874},
        Sequence = "SetRole(1135,3)"
