        Content = "AvgDialog_89875_Content_7|你说什么？最后一条生命！？",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
