          "Play_A_MUS_Shanhu_Peace"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Sea_01",
          "200"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_89875_Content_28|珊？",
        DialogType = 2,
