  [89881] = {
    ID = 89881,
    CnID = "支线剧情_1.5周年_战斗5",
    BaseSortID = 6,
    data_list = readonly({
      readonly({
        BaseSortID = 6,
        Content = "AvgDialog_89881_Content_1|由于海怪数量太多，这场战斗注定会被拖得很久。\n但你不能这样。你要尽快找到奥瑞塔。",
        DialogType = 3,
        BgID = {
          "SScene_SeasideDay"
        },
        Audio = {
          "Play_A_MUS_PressureHigh_80BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Sea_Coastal"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_89881_Content_2|为此，你握住了胸口的银钥匙。",
        DialogType = 3,
        ScreenEffect = {
          "keyWorkEffect",
          1
        },
        ShortAudioEffect = {
          "Play_A_SFX_Brooches_Launch"
        }
      }),
      readonly({
        Content = "AvgDialog_89881_Content_3|熟悉的晕眩感里，克莱门汀出现。",
        DialogType = 3,
        ScreenEffect = {
          "keyWorkEffect",
          2,
          "disturb",
          1
        },
        BgID = {
          "SScene_pendulum"
        },
        BgTransition = 2,
        Sequence = "SetRole(1190,3)",
        AudioTalk = {
          "Play_A_SFX_Butterfly_Flash_A",
          "500"
        },
        ShortAudioEffect = {
          "Play_Play_A_SFX_Memory_Confusion"
