        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_89876_Content_8|奥瑞塔，不要相信这些鬼话。他们在利用你。",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
