        },
        ShortAudioEffect = {
          "Play_A_SFX_Snap_Stitching_01",
          "500"
        }
      }),
      readonly({
        Content = "AvgDialog_91727_Content_88|淡淡的银光闪烁消失，阿格里帕惊讶地抬起头，开怀地笑了起来。",
        DialogType = 3,
        RoleHide = {1993},
        ScreenEffect = {
          "redScreen",
          2,
          "keyWorkEffect",
          1
