        Sequence = "SetRole(1140,3,Surprised2)",
        AudioTalk = {
          "Play_A_SFX_xing"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Show_Lock",
          "500"
        }
      }),
      readonly({
        TalkRole = {
          1140,
          nil,
          "Excited"
        },
        Content = "AvgDialog_91727_Content_89|成功了！什么银芯科技，区区厨房，还不是被老娘征服了！",
        DialogType = 1,
        ScreenEffect = {
          "keyWorkEffect",
          2
        },
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx"
      }),
      readonly({
        Content = "AvgDialog_91727_Content_90|她与尤乌哈希对视一眼，不约而同地哼了一声，一起轰然捶飞了失效的门板。",
        DialogType = 3,
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
