      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_95476_Content_29|……卢修斯，想笑就笑吧。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {2009},
        Content = "AvgDialog_95476_Content_30|哈哈哈哈哈哈，对，对不起，你刚才的表情太精彩了。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        Content = "AvgDialog_95476_Content_31|看着同一个屋檐下的友人肆无忌惮地大笑，你深深地叹了口气。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_95476_Content_32|哎……我要干活了，别打扰我干活！",
