  [98293] = {
    ID = 98293,
    CnID = "夏活上篇_弹出剧情",
    BaseSortID = 1,
    data_list = readonly({
      readonly({
        BaseSortID = 1,
        Content = "AvgDialog_98293_Content_1|刺眼的阳光里，你见到金色的沙滩和不断拍击的碧蓝海浪。",
        DialogType = 3,
        ScreenEffect = {"awake", 1},
        BgID = {
          "SScene_SandyBeach"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Gentle_Waves",
          "Stop_Avg_CG_Audio"
        },
        Audio = {
          "Play_A_MUS_Summer_activities_relaxed_102BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Beach_Seagull_Chirp"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_98293_Content_2|这是……伦蒂尼恩的海边？",
        DialogType = 2,
        ScreenEffect = {"awake", 2}
      }),
      readonly({
        TalkRole = {
          1001,
          "UI_Story_D_Image_Face_Surprise2.png"
        },
        Content = "AvgDialog_98293_Content_3|为什么我会在这里？！",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Surprise"
        }
      }),
      readonly({
        Content = "AvgDialog_98293_Content_4|就在你思考之际，一道熟悉的声音打乱了你的思绪。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {2049},
        Content = "AvgDialog_98293_Content_5|%player%，你傻傻站在那里干什么？还不过来帮本小姐提下午茶。",
        DialogType = 1,
        PlayEnterAnim = 1,
        ShortAudioEffect = {
          "Play_A_SFX_Emm"
        }
      }),
      readonly({
        TalkRole = {
          1001,
          "UI_Story_D_Image_Face_Surprise2.png"
        },
        Content = "AvgDialog_98293_Content_6|墨菲！？",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_OMG"
        }
      }),
      readonly({
        TalkRole = {2049},
        Content = "AvgDialog_98293_Content_7|当然是我。这地方真是糟糕……",
        DialogType = 1
      }),
      readonly({
        TalkRole = {2049, "ShutEye"},
        Content = "AvgDialog_98293_Content_8|还好我提前准备了墨镜和伞，不然都要被晒黑了。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_98293_Content_9|那把阳伞在她的手中不停转着位置，却怎么都遮不住全身的皮肤，很快这位淑女就在原地恼怒地跺起脚来。",
        DialogType = 3,
        RoleShake = {2049},
        ShortAudioEffect = {
          "Play_A_SFX_Cartoon_Angry4"
        },
        AudioManageEvent = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        TalkRole = {1134},
        Content = "AvgDialog_98293_Content_10|哎呀，这么快就厌倦了吗？当初可是你吵闹着要来海边度假的。",
        DialogType = 1,
        RolePos = {2},
        Sequence = "SetRole(2049,4,ShutEye)"
      }),
      readonly({
        TalkRole = {2049},
        Content = "AvgDialog_98293_Content_11|我才没有厌倦，我只是……哼，本小姐不需要向你解释什么。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {2049},
        Content = "AvgDialog_98293_Content_12|%player%，赶紧跟我走。摆躺椅、沏茶、还有涂防晒霜……我还有好多事情要你帮忙呢。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_98293_Content_13|墨菲高高扬起下巴，示意你过去。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_98293_Content_14|泰旖丝轻轻笑了，一只蜜色的手臂温柔伸向了你。",
        DialogType = 3,
        AudioTalk = {
          "Play_A_SFX_Show_Sash"
        }
      }),
      readonly({
        TalkRole = {1134, "Smile"},
        Content = "AvgDialog_98293_Content_15|或许，你更想来我的身边，与我水乳相融，对不对，%player%？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        ChatID = "CH1",
        NextChatID = {"A1", "A2"},
        TalkRole = {1001},
        Content = "AvgDialog_98293_Content_16|……",
        DialogType = 2
      }),
      readonly({
        ChatID = "A1",
        Content = "AvgDialog_98293_Content_17|走向墨菲",
        DialogType = 5
      }),
      readonly({
        NextChatID = {"CH1_END"},
        Content = "AvgDialog_98293_Content_18|你没有动，因为你很清楚，无论是墨菲还是泰旖丝都不该出现在这里。",
        DialogType = 3,
        Audio = {
          "Play_A_MUS_After_War_Tired_118BPM"
        }
      }),
      readonly({
        ChatID = "A2",
        Content = "AvgDialog_98293_Content_19|走向泰旖丝",
        DialogType = 5
      }),
      readonly({
        NextChatID = {"CH1_END"},
        Content = "AvgDialog_98293_Content_20|你没有动，因为你很清楚，无论是墨菲还是泰旖丝都不该出现在这里。",
        DialogType = 3,
        RolePos = {1},
        Audio = {
          "Play_A_MUS_After_War_Tired_118BPM"
        }
      }),
      readonly({
        ChatID = "CH1_END",
        Content = "AvgDialog_98293_Content_21|她们属于你已经回不去的「那个世界」。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_98293_Content_22|<Small:这到底是怎么回事……>",
        DialogType = 2,
        RoleHide = {1},
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [98108] = {
    ID = 98108,
    CnID = "夏活上篇_关卡1_前",
    BaseSortID = 2,
    data_list = readonly({
      readonly({
        BaseSortID = 2,
        Content = "AvgDialog_98108_Content_1|高温预警",
        Chapter = "See You, Neverland;Heatwave Alert;Part 1",
        DialogType = 4,
        BgID = {
          "SScene_Black"
        },
        AudioTalk = {
          "Stop_Avg_CG_Audio"
        },
        ShortAudioEffect = {
          "Play_UI_AVG_Chapter_Pop"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_98108_Content_2|面对泰旖丝和墨菲灼灼的目光，你没有答应任何一人的邀请，在过于反常的美好中，你生出一种不敢相信的惶惑。",
        DialogType = 3,
        BgID = {
          "SScene_SandyBeach"
        },
        Sequence = "SetRole(1134,2,Smile);SetRole(2049,4)",
        Audio = {
          "Play_A_MUS_Summer_activities_relaxed_102BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Beach_Seagull_Chirp"
        }
      }),
      readonly({
        Content = "AvgDialog_98108_Content_3|你强自镇定，转移视线，见到了奥尔拉、菲茵特、潘狄娅，远处的莱克、图鲁，以及更远处的唤醒体……",
        DialogType = 3,
        RoleHide = {1134, 2049},
        Sequence = "SetRole(2048,3);SetRole(2051,1);SetRole(2050,5)"
      }),
      readonly({
        Content = "AvgDialog_98108_Content_4|几乎所有你认识的唤醒体都在这里——这样的场景，显然不可能出现在现实里。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_98108_Content_5|……",
        DialogType = 2,
        RoleHide = {1},
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        TalkRole = {
          2050,
          nil,
          "Smile"
        },
        Content = "AvgDialog_98108_Content_6|哎呀，怎么苦着一张脸，我们来海边可是来尽情享受甜蜜和爱的哦♡",
        DialogType = 1,
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Desert_Footsteps_01"
        },
        Audio = {
          "Play_A_MUS_PanDiYa_Theme_Normal_118BPM"
        }
      }),
      readonly({
        TalkRole = {
          2050,
          nil,
          "Dream"
        },
        Content = "AvgDialog_98108_Content_7|冰棒好凉，人家被冰到了，%player%，要不要和我来一场热♡烈的游戏呢？",
        DialogType = 1,
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Cute_Cartoon02"
        }
      }),
      readonly({
        TalkRole = {
          1001,
          "UI_Story_D_Image_Face_Sweat.png"
        },
        Content = "AvgDialog_98108_Content_8|……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_98108_Content_9|眼见潘狄娅越走越近，你不得不说些什么转移她的注意力。",
        DialogType = 3,
        AnimState = "AvgRoleScale",
        ShortAudioEffect = {
          "Play_A_SFX_Show_Something"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_98108_Content_10|咳咳，潘、潘狄娅，你们怎么会来海边度假？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {2049},
        Content = "AvgDialog_98108_Content_11|当然是因为伦蒂尼恩太热了！",
        DialogType = 1,
        RoleHide = {2050},
        RoleShake = {0},
        AudioTalk = {
          "Play_A_SFX_Emm"
        }
      }),
      readonly({
        TalkRole = {2050, "Serious"},
        Content = "AvgDialog_98108_Content_12|是呀，伦蒂尼恩不知道为什么变得越来越热，人家虽然享受太阳的热情，但是太过热情会让蜡烛都融化的呀。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {2051},
        Content = "AvgDialog_98108_Content_13|所以，我们就决定来到海边度假。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {2051},
        Content = "AvgDialog_98108_Content_14|啊，我戴了泳圈，会待在水里，和海边的游客保持距离，不会伤害到大家的……",
        DialogType = 1,
        AudioTalk = {
          "Play_A_SFX_chuochuo"
        },
        AudioManageEvent = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        Content = "AvgDialog_98108_Content_15|菲茵特说着，握紧了游泳圈，显然有些紧张不安，于是你安抚地摸摸她的头。",
        DialogType = 3,
        RolePos = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_98108_Content_16|没关系，我会在这里照看着你们的。所以菲茵特，不用紧张，尽情享受度假就好。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          2051,
          nil,
          "Smile"
        },
        Content = "AvgDialog_98108_Content_17|谢谢你，%player%。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_98108_Content_18|菲茵特轻轻用头蹭蹭你的手，眉毛弯弯地笑了起来。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Caress02"
        },
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        TalkRole = {2049, "Surprised"},
        Content = "AvgDialog_98108_Content_19|呼……可是海边，为什么也这么热……",
        DialogType = 1,
        Audio = {
          "Play_A_MUS_Fun_3_118BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_98108_Content_20|墨菲不停用手扇风，但天气是如此炎热，她的脸很快就热得像熟苹果一样。",
        DialogType = 3,
        RolePos = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Cartoon_Angry"
        }
      }),
      readonly({
        TalkRole = {2049, "Shy"},
        Content = "AvgDialog_98108_Content_21|你们、你们不觉得天气越来越热了吗？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {2048},
        Content = "AvgDialog_98108_Content_22|我、我也这样觉得，墨菲小姐。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {2048, "ShutEye"},
        Content = "AvgDialog_98108_Content_23|光的瀑布倾泻不止，海面上浮起千万个日冕破碎的遗物，万物也随其一同枯萎。",
        DialogType = 1,
        ShortAudioEffect = {
          "Play_A_SFX_Sunlight02"
        }
      }),
      readonly({
        TalkRole = {2048, "ShutEye"},
        Content = "AvgDialog_98108_Content_24|酷烈的热浪，即便戴上太阳帽也无法阻挡。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {2048},
        Content = "AvgDialog_98108_Content_25|这样的场景使我想到了曾经看过的、遥远磐龙国的传说……",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1134},
        Content = "AvgDialog_98108_Content_26|磐龙国的传说……你是指「射日」的故事吗？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {2048},
        Content = "AvgDialog_98108_Content_27|是的。相传当太阳灼烧万物时，便会有英雄挺身而出，将它射落……",
        DialogType = 1
      }),
      readonly({
        TalkRole = {2049},
        Content = "AvgDialog_98108_Content_28|本小姐可没时间听什么传说故事，现在最重要的是找个阴凉的地方躲一躲啊！",
        DialogType = 1,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Cartoon_Angry4"
        }
      }),
      readonly({
        TalkRole = {2049, "Surprised"},
        Content = "AvgDialog_98108_Content_29|等等！天上的太阳……",
        DialogType = 1,
        RoleShake = {1},
        AudioTalk = {
          "Play_A_SFX_gulu"
        }
      }),
      readonly({
        Content = "AvgDialog_98108_Content_30|墨菲惊呼一声，跟随着她的视线，你们纷纷抬头看向了天空。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_Sunny"
        },
        BgTransition = 4,
        AnimState = "avg_dialog_Amplification",
        ShortAudioEffect = {
          "Play_A_SFX_Zoom_In"
        },
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        TalkRole = {2049, "Surprised"},
        Content = "AvgDialog_98108_Content_31|是我的错觉吗？我怎么觉得……太阳似乎在移动!?",
        DialogType = 2,
        Audio = {
          "Play_A_MUS_Pressure_80BPM"
        }
      }),
      readonly({
        TalkRole = {
          1001,
          "UI_Story_D_Image_Face_Surprise1.png"
        },
        Content = "AvgDialog_98108_Content_32|不是错觉。它、它确实在坠落向地面。",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Hit_Jump_Shock"
        }
      }),
      readonly({
        TalkRole = {2048, "Surprised"},
        Content = "AvgDialog_98108_Content_33|难道是「射日」的传说应验了……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1134},
        Content = "AvgDialog_98108_Content_34|这里可没有什么「射日」英雄，只有可爱的小树苗。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1134, "Smile"},
        Content = "AvgDialog_98108_Content_35|但要是继续傻站在这里，所有人可都要被烤成木乃伊了呀。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_98108_Content_36|经过泰旖丝的提醒，你猛地反应过来，高喊出声。",
        DialogType = 3,
        RolePos = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_98108_Content_37|所有人都撤退，远离这里！太阳就要坠落下来了！",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        AudioTalk = {
