      readonly({
        TalkRole = {1132, "Twinkie"},
        Content = "AvgDialog_98097_Content_3|珈伦也想要和主人一组，沙滩排球什么的，珈伦也可以打！",
        DialogType = 1,
        AudioTalk = {
          "Play_A_SFX_kawayi"
