        AudioManageEvent = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        TalkRole = {1141},
        Content = "AvgDialog_98097_Content_12|哈哈哈，又生气了，没用的女人？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1141},
        Content = "AvgDialog_98097_Content_13|来吧，不如现在就先打一场，看看谁最有资格……",
        DialogType = 1,
        RoleShake = {1},
        AudioTalk = {
          "Play_A_SFX_Cloth_Bring_Here"
        }
      }),
      readonly({
        TalkRole = {
          1001,
          "UI_Story_D_Image_Face_Angry.png"
        },
        Content = "AvgDialog_98097_Content_14|……你们都冷静一下！！！",
        DialogType = 2,
        RoleHide = {1},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        AudioTalk = {
          "Play_A_SFX_Cartoon_Angry4"
        },
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        Content = "AvgDialog_98097_Content_15|你大吼一声，忍无可忍挡在了尤乌哈希、阿格里帕和血链·希洛之间。",
        DialogType = 3,
        Sequence = "SetRole(1141,1);SetRole(1140,3,Furious);SetRole(1244,5)",
        AudioTalk = {
          "Play_A_SFX_Turn_Jump"
        },
        Audio = {
          "Play_A_MUS_Fun_Afraid_118BPM"
        }
      }),
      readonly({
        TalkRole = {1141},
        Content = "AvgDialog_98097_Content_16|哦，你有了自己的决定？那好，说出来。",
        DialogType = 1,
        RoleHide = {1140, 1244}
      }),
      readonly({
        TalkRole = {
          1140,
          nil,
          "Angry2"
        },
        Content = "AvgDialog_98097_Content_17|记住，你最好仔细考虑一下再说话，不然事情可能会变得无法收场……",
        DialogType = 1
      }),
      readonly({
        TalkRole = {2047, "Serious"},
        Content = "AvgDialog_98097_Content_18|%player%，不必听她的，无论你做出什么决定，我都会支持你。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_98097_Content_19|阿格里帕面露不悦，想要再说什么，但你摇了摇头，阻止了她。",
