        ShortAudioEffect = {
          "Play_A_SFX_Gun_Hammer_Click_B",
          "350"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_98097_Content_25|我会作为裁判，监督你们完成这场比赛！",
        DialogType = 2,
        RoleHide = {1},
        Audio = {
          "Stop_Avg_Mus"
        }
