        DialogType = 3,
        Sequence = "WaterColor(2027,1,0.5,0.2)",
        AudioTalk = {
          "Play_A_SFX_Mud_Once_A"
        }
      }),
      readonly({
        TalkRole = {2027},
        Content = "AvgDialog_98285_Content_17|让自己贴近于这个世界的色彩，才能触及到这个世界的真实。您不觉得吗，画家先生？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1962,
          nil,
          "Excited"
        },
        Content = "AvgDialog_98285_Content_18|当然！当然！给我来十罐！",
        DialogType = 1,
        RolePos = {3},
        RoleShake = {0},
        AudioTalk = {
          "Play_A_SFX_cing"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_98285_Content_19|皮克曼，我先说好，我可不想陪你玩这个……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1962},
        Content = "AvgDialog_98285_Content_20|这怎么行，埃弗！你可是一位革新派的艺术家！",
        DialogType = 1
      }),
      readonly({
