        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_98285_Content_32|「王邸管家正招募画家为宴会作画，报名名额已满，欢迎大家前往现场观看……」",
        DialogType = 2
