        RoleShake = {1},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        AudioTalk = {
          "Play_A_SFX_cing"
        }
      }),
      readonly({
        Content = "AvgDialog_98285_Content_34|一大群人围在前方，皮克曼不由分说拉着你凑上前。攒动的人头里，你们奋力往前挤去。",
        DialogType = 3,
