        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1155, "Sad2"},
        Content = "AvgDialog_97162_Content_80|躯干编号EA307881，电机编号MF311028，自动人偶艾瑞卡。",
        DialogType = 1,
        RoleHide = {1},
