        Content = "AvgDialog_97162_Content_85|真正重要的是你，守密人%player%。哪怕……",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1155, "Smile"},
        Content = "AvgDialog_97162_Content_86|<Shake:情感模块超载……超、载……>",
        DialogType = 1,
        RoleHide = {1},
