        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_97209_Content_2|握着属于艾瑞卡的房树人绘画，你静静愣在原地。",
        DialogType = 3,
        BgID = {
          "SScene_HTPErica"
        },
        AudioTalk = {
