        RoleHide = {1},
        AudioTalk = {
          "Play_A_SFX_Show_Sash"
        },
        AudioManageEvent = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        Content = "AvgDialog_123118_Content_8|痛苦与绝望随着浓雾慢慢渗入倾听者的血肉，筋骨，直达灵魂。",
