      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_123119_Content_27|苍白的使者，我绝不会让你在我之前倒下。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_123119_Content_28|你的回应是一抹理解的笑容。",
        DialogType = 3,
        RoleHide = {1}
