      }),
      readonly({
        TalkRole = {2142},
        Content = "AvgDialog_120296_Content_3|侬呀就是嘴巴坏，她送侬的扇子，还不是爱不释手呀？",
        DialogType = 1,
        RolePos = {4},
        RoleShake = {0},
