        AudioAmbient = {
          "Play_A_SFX_Be_Hit_Normal",
          "400"
        }
      }),
      readonly({
        TalkRole = {2138},
        Content = "AvgDialog_120297_Content_80|<Red:神女>已经降临了，从此她会<Red:永远>属于我。什么功名利禄，对我来说已经没有意义了。只要有<Red:神女>相伴，一切牺牲都是值得的！",
        DialogType = 1,
