        NextChatID = {"80", "81"},
        TalkRole = {
          2225,
          nil,
          "Serious"
        },
        Content = "AvgDialog_120298_Content_79|妾身用雾滋养她，用权欲浇灌她，妾身爱她，您为何还对妾身兴师问罪？",
        DialogType = 1
      }),
      readonly({
        ChatID = "80",
        NextChatID = {"82"},
        Content = "AvgDialog_120298_Content_80|那不是爱",
