        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_126909_Content_11|<Shake:嗯……好困啊。>\n在列车上睡觉，无论睡多久都睡不够。",
        DialogType = 2,
        ScreenEffect = {"awake", 1},
        BgID = {
          "SScene_InsideSubway_Light"
