        ShortAudioEffect = {
          "Play_A_SFX_Wind_Lost"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_126908_Content_37|！！！唔！！",
        DialogType = 2,
        ScreenEffect = {
          "speedLine",
          2,
          "continueShake",
          2
        },
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        AudioTalk = {
          "Play_A_SFX_Hit_Jump_Shock"
        },
