        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        Content = "AvgDialog_126907_Content_11|艾尔莎双眼放光，一把拉过你，然后以迅雷不及掩耳之势开始了本应由你主导的舞蹈。",
        DialogType = 3,
