        }
      }),
      readonly({
        Content = "AvgDialog_126907_Content_12|她的力道之大，几乎要将你甩出去，她慌慌张张地凭着蛮力又将你拉回。",
        DialogType = 3,
        AnimState = "avg_dialog_Lessen",
