    BaseSortID = 2,
    data_list = readonly({
      readonly({
        BaseSortID = 2,
        Content = "AvgDialog_118701_Content_1|守候",
        Chapter = "We Will Meet Again;Waiting;Part 2",
        DialogType = 4,
        BgID = {
