  [122641] = {
    ID = 122641,
    CnID = "支线_二周年世界BOSS_气泡剧情1",
    BaseSortID = 7,
    data_list = readonly({
      readonly({
        BaseSortID = 7,
        TalkRole = {1833},
        Content = "AvgDialog_122641_Content_1|……@3！！……",
        DialogType = 1,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx;UI_Story_Panel_AvgDialogBg_doudong_vx"
      }),
      readonly({
        Content = "AvgDialog_122641_Content_2|熟悉的威压。熟悉的目光。熟悉的几乎将你大脑撕裂的疼痛。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_122641_Content_3|呵……又见面了，托乎瓦波，至高的神明……虽然你无法听见，但是我得感谢你。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_122641_Content_4|你曾让我死过一次，在这次死亡里，我领悟到了一个至理……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_122641_Content_5|你紧握银钥，直视着祂的意志投下的目光。甚至连你自己都没有发现，你的嘴角带着一抹微笑。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_122641_Content_6|你让我知道，在你这个宏伟的梦境里，没有任何事情不可改变，没有任何事物不可战胜。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_122641_Content_7|为了再次相见，我们已经等待了许久……即便是你，也休想挡住我们的路！",
        DialogType = 2
      })
    })
  },
  [122645] = {
    ID = 122645,
    CnID = "支线_二周年世界BOSS_气泡剧情2",
    BaseSortID = 8,
    data_list = readonly({
      readonly({
        BaseSortID = 8,
        Content = "AvgDialog_122645_Content_1|遥远的维度中，一颗光点正在微微闪烁。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_122645_Content_2|那是……波吕克斯的「圣心」？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_122645_Content_3|他们的寻找也已经开始了……他们现在，一定也处在危险之中。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_122645_Content_4|我还记得第一次面对你时的恐惧，托乎瓦波。这一次，我不会让他们久等的！",
        DialogType = 2
      })
    })
  },
  [122646] = {
    ID = 122646,
    CnID = "支线_二周年世界BOSS_气泡剧情3",
    BaseSortID = 9,
    data_list = readonly({
      readonly({
        BaseSortID = 9,
        Content = "AvgDialog_122646_Content_1|强烈的刺痛袭向你的每一根骨头、每一寸血肉。你忍受着这钻心的痛苦，艰难地笑起来。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_122646_Content_2|痴愚的神明，你不知道，在你的梦境里，有许多痛苦远远超越了肉体……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_122646_Content_3|那样的痛苦，我不会让它再出现的！",
        DialogType = 2
      })
    })
  },
  [122644] = {
    ID = 122644,
    CnID = "支线_二周年世界BOSS_气泡剧情4",
    BaseSortID = 10,
    data_list = readonly({
      readonly({
        BaseSortID = 10,
        Content = "AvgDialog_122644_Content_1|世界在你面前崩塌、重建，至亲在你面前死去、复生。那道迷乱的目光，将宇宙一切的混乱带到你的精神之中。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_122644_Content_2|无序，迷乱，困惑……你的权柄带来的，依然是这些东西。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_122644_Content_3|你的目光从未迷惑我，托乎瓦波。曾经如此，现今亦然。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_122644_Content_4|银光闪耀。在那些无尽的幻象之中，你找到了那条与它对决的道路——",
        DialogType = 3
      })
    })
  },
  [122643] = {
