        DialogType = 1,
        ScreenEffect = {
          "continueShake",
          1
        }
      }),
      readonly({
        Content = "AvgDialog_122642_Content_2|强烈的冲击让整个维度开始破碎。你睁开发红的眼，望向那个越来越接近实体的眼瞳。",
        DialogType = 3,
        ScreenEffect = {
