        BanSpeedUp = 1
      }),
      readonly({
        TalkRole = {1794},
        Content = "AvgDialog_119923_Content_2|你还要装睡到什么时候？我可爱的小狗。",
        DialogType = 1,
        RoleHide = {0},
        AudioTalk = {
