        BgID = {
          "SScene_LightBearerTemple"
        },
        Audio = {
          "Play_A_MUS_DeadEnd_Ver3_118BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_90537_Content_58|再一次梦到卡斯托尔后，波吕克斯于深夜中悚然惊醒。",
        DialogType = 3,
        AudioTalk = {
