  [139663] = {
    ID = 139663,
    CnID = "联动剧情_沙耶之歌_关卡2_后",
    BaseSortID = 3,
    data_list = readonly({
      readonly({
        BaseSortID = 3,
        TalkRole = {1001},
        Content = "AvgDialog_139663_Content_1|这些怪物是……",
        DialogType = 2,
        BgID = {
          "SScene_Dandelion"
        },
        Audio = {
          "Play_A_MUS_Shaye_guidance_00"
        },
        AudioAmbient = {
