          "SScene_Black"
        },
        AudioManageEvent = {
          "Play_UI_AVG_Chapter_Pop",
          "Stop_Avg_CG_Audio",
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        },
        BanSpeedUp = 1
      }),
      readonly({
        Content = "AvgDialog_139661_Content_2|天地是由沙构成的。",
        DialogType = 3,
        ScreenEffect = {"speedLine", 1},
        BgID = {
          "SScene_DesertDay"
        },
        AudioTalk = {
          "Play_A_SFX_Desert_Sand"
        },
