        ScreenEffect = {
          "redScreen",
          1,
          "disturb",
          1
        },
        AudioTalk = {
          "Play_A_SFX_Thriller_04"
        }
      }),
      readonly({
        Content = "AvgDialog_142892_Content_56|话音刚落，魇带着倒钩的尾巴从窗外向你的口袋垂去。",
