          "Play_A_SFX_Pangtuosi_Whistle_Echo_Tail_A",
          "Play_A_SFX_Wing_Flap_Large_Crowd_Far"
        }
      }),
      readonly({
        Content = "AvgDialog_142890_Content_51|然后，你听见了……<Red:「你」>的声音。",
        DialogType = 3,
        AudioTalk = {
          "Play_A_SFX_Abstract_Finger_Touch_Silvery",
          "600"
        },
        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_142890_Content_52|我想，<Red:「我」>已经做出了选择。",
        DialogType = 2,
        ScreenEffect = {
          "mucus",
          2,
          "disturb",
          2,
          "continueShake",
          2
        },
        BgTransition = 2,
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        Content = "AvgDialog_142890_Content_53|从识海深处，一道灵性挣扎而出。",
        DialogType = 3,
        ScreenEffect = {
          "keyWorkEffect",
          1
        },
        BgTransition = 2,
        AudioTalk = {
