        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        TalkRole = {
          2350,
          nil,
          "Smile"
        },
        Content = "AvgDialog_142888_Content_38|你们想错了，雅格……<Red:%player%>。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_142888_Content_39|！！！？？？",
        DialogType = 2,
        RoleHide = {1},
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        AudioTalk = {
          "Play_A_SFX_Hit_Jump_Shock"
        },
        Audio = {
          "Play_A_MUS_Pangtuosi_rage_130"
        }
      }),
      readonly({
