        Audio = {
          "Play_A_MUS_Qisui_sneaking_86"
        }
      }),
      readonly({
        TalkRole = {
          1165,
          nil,
          "Angry"
        },
        Content = "AvgDialog_142888_Content_70|庞托斯叔叔好坏啊！不可以这样！",
        DialogType = 1,
        RoleShake = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_142888_Content_71|就是，怎么这么坏啊庞托斯！",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx"
      }),
      readonly({
        Content = "AvgDialog_142888_Content_72|你正气势汹汹地跟奥瑞塔嘀嘀咕咕在梦境中的经历，一扭头……",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_142888_Content_73|就被同样兴致勃勃插着兜在门边不知道听了多久的某人吓了一跳。",
        DialogType = 3,
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        AudioTalk = {
