        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        AudioTalk = {
          "Play_A_SFX_Hit_Jump_Shock"
        }
      }),
      readonly({
        Content = "AvgDialog_142852_Content_12|……",
        DialogType = 3,
        Sequence = "PlayVideo(Blade_Flash3.mp4)",
        AudioTalk = {
          "Play_Blade_Flash3"
        }
      }),
      readonly({
        Content = "AvgDialog_142852_Content_13|两股风从你身边刮过，温热的液体喷溅在你的身上。",
        DialogType = 3,
        ScreenEffect = {
          "speedLine",
