          "Play_A_MUS_Weilian_Death_Intro_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Floodlight"
        }
      }),
      readonly({
        Content = "AvgDialog_72006_Content_82|紫雾翻腾。",
        DialogType = 3,
        ScreenEffect = {"whiteSmoke", 1},
        ShortAudioEffect = {
          "Play_A_SFX_Psychedelic_Mist"
        }
      }),
      readonly({
        TalkRole = {1147},
        Content = "AvgDialog_72006_Content_83|明码标价，童叟无欺……达芙黛尔的小店能为你做些什么呢？",
        DialogType = 1,
        ScreenEffect = {
          "keyWorkEffect",
          2
        },
