        Sequence = "AvgRoleScale",
        ShortAudioEffect = {
          "Play_A_SFX_Caress02"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_72000_Content_7|（既然雕塑家协会和罗杰斯的情况与之前一致，那么……）",
        DialogType = 2,
        RoleHide = {1},
        Audio = {
          "Play_A_MUS_Thinking_001_118BPM",
          "500"
