  [78100] = {
    ID = 78100,
    CnID = "2.0主线剧情_关卡1_13_B68二阶段",
    BaseSortID = 26,
    data_list = readonly({
      readonly({
        BaseSortID = 26,
        TalkRole = {1876},
        Content = "AvgDialog_78100_Content_1|呼、呼……坚持了这么久，我都有点疲惫了。",
