      }),
      readonly({
        ChatID = "CH1",
        NextChatID = {"A1", "A2"},
        TalkRole = {1874},
        Content = "AvgDialog_73796_Content_21|人的大脑有诸多缺陷，视觉欺骗就是其一。试着深入接触看看。",
        DialogType = 1,
        RolePos = {
          2,
          "AvgVertical"
