        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
      }),
      readonly({
        Content = "AvgDialog_73796_Content_42|你轻手轻脚走到门口，悄悄将门拉开了一道缝隙。",
        DialogType = 3,
