        ShortAudioEffect = {
          "Play_A_SFX_Splash_Blood",
          "500"
        }
      }),
      readonly({
        TalkRole = {1884},
        Content = "AvgDialog_73796_Content_47|不！不！我不要变成虫子，我不要！",
        DialogType = 1,
        RoleShake = {0},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
