        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Cloth_Bring_Here"
        },
        Audio = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        TalkRole = {1307},
        Content = "AvgDialog_73799_Content_59|嘘，耐心。捕猎的最大技巧，就是耐心。",
        DialogType = 1,
        Audio = {
          "Play_A_MUS_Strange_002_118BPM"
        }
      }),
      readonly({
        TalkRole = {1307},
        Content = "AvgDialog_73799_Content_60|这场狩猎中，不是你吃了我，就是我吃了你。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_73799_Content_61|哒、哒、哒——巡逻队的脚步声越来越近，越来越清晰。\n你必须做出抉择。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_LeatherShoes_Walk"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_73799_Content_62|加入死亡，就不会再畏惧死亡。\n而我，已在死亡之中。",
        DialogType = 2,
        Audio = {
          "Set_Avg_Mus_As_More_And_More"
        }
      }),
      readonly({
        TalkRole = {1307},
        Content = "AvgDialog_73799_Content_63|嗯？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_73799_Content_64|你说得对，这场狩猎，不是你吃了我，就是我吃了你。",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_73799_Content_65|而我，有想要活下去的理由。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_73799_Content_66|说着，你握住了胸前的银钥匙。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Show_Something"
        }
      }),
      readonly({
        Content = "AvgDialog_73799_Content_67|意识的丝缕在你的脑海中拂动，阿尔比诺看清楚了你眼中的坚定。",
        DialogType = 3,
        ScreenEffect = {
          "keyWorkEffect",
          1
        },
        ShortAudioEffect = {
          "Play_A_SFX_Brooches_Launch"
        }
      }),
      readonly({
        TalkRole = {1307},
        Content = "AvgDialog_73799_Content_68|……",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1307},
        Content = "AvgDialog_73799_Content_69|我只是来这里度假，舒缓身心而已，为什么总是遇到这样的事情？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1307},
        Content = "AvgDialog_73799_Content_70|放轻松，就像我愿赌服输，帮助那个小家伙逃走一样，你也有其他选择。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1307},
        Content = "AvgDialog_73799_Content_71|请进，我的客人。阿尔比诺的心灵，欢迎你的光临。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_73799_Content_72|阿尔比诺绅士地抬手，但他的目光望着你。",
