        ShortAudioEffect = {
          "Play_A_SFX_No_Signal"
        },
        Audio = {
          "Play_A_MUS_Underground_Mist_104BPM"
        }
      }),
      readonly({
        TalkRole = {1874},
        Content = "AvgDialog_73797_Content_17|%player%，你是我的小狗……不能在我视……出现任……意外……",
        DialogType = 1,
        RolePos = {
          2,
          "AvgVertical"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Brooches_Shine"
        }
      }),
      readonly({
        Content = "AvgDialog_73797_Content_18|断断续续的话语，在意识模糊中消失。\n当你清醒时，你只听到了熟悉的脚步声。",
        DialogType = 3,
