        ShortAudioEffect = {
          "Play_A_SFX_Partially_Struck_C"
        }
      }),
      readonly({
        Content = "AvgDialog_73797_Content_75|在染血的视线里，你看到了自己的敌人——一群天真又残忍的孩童。",
        DialogType = 3,
        ScreenEffect = {
          "bloodSmoke",
          1,
