        Content = "AvgDialog_73793_Content_1|威廉，不要哭。这并不值得。",
        DialogType = 1,
        ScreenEffect = {"oldFilm", 1},
        BgID = {
          "SScene_PalaceHallDay"
        },
        Sequence = "DarkRole(1921,1)",
        ShortAudioEffect = {
