        Content = "AvgDialog_74311_Content_19|！！！",
        DialogType = 1,
        RoleHide = {1893},
        Sequence = "DarkRole(1893,2)",
        ShortAudioEffect = {
          "Play_A_SFX_Hit_Jump_Shock"
        }
      }),
      readonly({
        Content = "AvgDialog_74311_Content_20|已经不会哭的小威廉安静地闭上了眼睛。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
