      }),
      readonly({
        Content = "AvgDialog_74311_Content_21|妈妈死了，爸爸视他为耻辱，他已经失去了一切。",
        DialogType = 3,
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
