        RolePos = {
          2,
          "AvgVertical"
        }
      }),
      readonly({
        TalkRole = {
          1874,
          nil,
          "Serious"
        },
        Content = "AvgDialog_73792_Content_67|活下去，我的小狗，因为你的命，是我的。",
        DialogType = 1,
