      readonly({
        TalkRole = {
          1822,
          nil,
          "Null"
        },
        Content = "AvgDialog_73783_Content_39|我想以人的身份，去看看真正的世界，去过新的生活。",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
