      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_73783_Content_53|克莱门汀，我承认你的把戏起作用了。我确实无法伤害他们，因为他们的行为符合人性，让我想起了曾经见过的人类。",
        DialogType = 2,
        ScreenEffect = {"redScreen", 2}
