        ScreenEffect = {"redScreen", 2},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
      }),
      readonly({
        Content = "AvgDialog_73783_Content_59|它们欢呼，它们雀跃，它们游走在人的躯体上，一点点割裂人的灵魂，涂抹上虫的色彩。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_73783_Content_60|嘘，嘘，转变就要开始。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_73783_Content_61|<Shake:啊啊啊啊！！！——>",
