          "Play_A_SFX_Carcass_blood"
        },
        Audio = {
          "Play_A_MUS_Horror_Faster_Thriller_170BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_73778_Content_3|施害者动作温柔，近乎爱抚，手段却残酷异常。",
        DialogType = 3,
        Sequence = "SetRole(1190,2,Smile)"
      }),
      readonly({
        TalkRole = {
          1946,
