        ShortAudioEffect = {
          "Play_A_SFX_LightThe_Flame"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Flame_Burning"
        }
      }),
      readonly({
        Content = "AvgDialog_73778_Content_26|一片慌乱中，你潜伏在黑暗里，见到克莱门汀离开，才闯进屋内。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_73778_Content_27|克莱门汀，我来救——",
        DialogType = 2,
        ScreenEffect = {"flame", 2},
        BgID = {
          "SScene_TownST_Night"
        },
        BgTransition = 4,
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        Content = "AvgDialog_73778_Content_28|你的声音戛然而止，因为重伤的克莱门汀无法再和你逃离这里。",
        DialogType = 3,
        Sequence = "SetRole(1946,3,Sad)"
      }),
      readonly({
        Content = "AvgDialog_73778_Content_29|她就要死了。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_73778_Content_30|……",
