        Audio = {
          "Play_A_MUS_KeLai_So_Sad_127BPM"
        }
      }),
      readonly({
        TalkRole = {
          1946,
          nil,
          "Surprised"
        },
        Content = "AvgDialog_73778_Content_31|%player%……？",
