        ShortAudioEffect = {
          "Play_A_SFX_Show_Something"
        }
      }),
      readonly({
        TalkRole = {
          1190,
          nil,
          "Happy"
        },
        Content = "AvgDialog_73780_Content_15|我将它链接到了这里——",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_73780_Content_16|你是指……银芯？！",
