        ScreenEffect = {
          "keyWorkEffect",
          1
        },
        AudioTalk = {
          "Play_A_SFX_Brooches_Shine_Get"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Floodlight"
        }
      }),
      readonly({
        Content = "AvgDialog_89089_Content_17|你曾与托乎瓦波对视，你对唤醒体的力量熟稔于心。你有信心，即使身前这个男人拥有驾驭整座城邦的强大力量，你也能够靠这一击冲出去。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_89089_Content_18|唔——这……这是……",
        DialogType = 2,
        RoleHide = {1},
        ScreenEffect = {
