      }),
      readonly({
        TalkRole = {1144},
        Content = "AvgDialog_89083_Content_104|让我们，好好迎接我们的客人吧。",
        DialogType = 1,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
