        Audio = {
          "Set_Avg_Mus_As_More"
        }
      }),
      readonly({
        Content = "AvgDialog_89076_Content_16|戈利亚微微眯着的眼睛扫视着，最终定格在你手中闪耀的银钥匙上。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_89076_Content_17|你们的那堆烂骨头军队的确数量庞大，但有我戈利亚在，你们想要破坏仪式，可没那么容易。",
        DialogType = 1,
        ScreenEffect = {"whiteSmoke", 2}
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_89076_Content_18|力量，时间，一切都站在我这边。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_89076_Content_19|你之前说，我们可以成为朋友，对吗？",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_89076_Content_20|戈利亚咧开嘴，露出他的尖牙。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_89076_Content_21|我能看到你身上不一样的地方，一种我从未在这个世界上见到的力量。这是你的价值。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_89076_Content_22|从现在起，站在蹈海者这一边。等我们攻破食尸鬼的王城，你将会得到你应得的那一部分。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_89076_Content_23|或许我们还会有再次并肩作战的那一天，但一定不是现在。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_89076_Content_24|你站在杜勒赛因身旁，闪烁的银光里，那些存在于你记忆中的虚影出现在你身后。",
