        },
        BgTransition = 4,
        AudioTalk = {
          "Play_A_SFX_Sea_Zombie_Monster_Roar_Angry_C"
        }
      }),
      readonly({
        Content = "AvgDialog_89071_Content_30|当最后一声骨骼咬合的脆响传来，战场中央矗立起山峦般的畸变体。",
        DialogType = 3,
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        AudioTalk = {
