        AudioTalk = {
          "Play_A_SFX_Runes_Steam"
        }
      }),
      readonly({
        Content = "AvgDialog_97173_Content_8|来自地底的深邃能量在薄雾中凝聚成若隐若现的黑色花瓣，自整座城邦上空飘落。",
        DialogType = 3,
        ScreenEffect = {
          "redScreen",
          2,
          "blackFlower",
          1
