      readonly({
        TalkRole = {1144},
        Content = "AvgDialog_89077_Content_65|很重要……我一定……",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_89077_Content_66|杜勒赛因的声音微弱，但眼里的神情不容拒绝。你来到他面前。",
        DialogType = 3,
        RoleHide = {1}
