        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        },
        BanSpeedUp = 1
      }),
      readonly({
        Content = "AvgDialog_117504_Content_2|满目鱼腥气中，紫袍的女人皱了皱眉，转身向一旁的法洛思。",
        DialogType = 3,
        BgID = {
          "SScene_Apt_Deck"
        },
        Sequence = "SetRole(1168,2);SetRole(1162,4)",
        Audio = {
