      readonly({
        TalkRole = {2102},
        Content = "AvgDialog_118125_Content_3|……",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_118125_Content_4|抱着纺轮的女人神色哀伤地凝望着你。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_118125_Content_5|你有什么想和我说的吗？",
