        BgTransition = 1,
        Sequence = "SetRole(1166,2,Serious);SetRole(1168,4)",
        AudioTalk = {
          "Play_A_SFX_Footstep_Misty_two"
        },
        Audio = {
          "Play_A_Mus_After_War_Chp4_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Cabin"
        }
      }),
      readonly({
        Content = "AvgDialog_118125_Content_25|经过巴洛克风格的圣母像壁画、替代黄铜壁灯的小型提灯和安静无人的卧室群。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_118125_Content_26|他们没有接触，没有说话，紧张气氛盘绕在二人之间。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_118125_Content_27|弥利亚姆在船长室门口停下，转身推开了门。",
