          "450"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_118124_Content_2|搞定！别乱动，小心伤着你！",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          2100,
          nil,
          "Angry"
        },
        Content = "AvgDialog_118124_Content_3|烦死了！再这样的话我要咬你了！",
        DialogType = 1,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        AudioTalk = {
          "Play_A_SFX_Show_Sash"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_118124_Content_4|还是这样不装腔作势比较像你啊，墨菲。",
        DialogType = 2,
        Audio = {
          "Play_A_MUS_Fun_Chao_118BPM"
        }
      }),
      readonly({
        TalkRole = {
          2100,
          nil,
          "Angry"
        },
        Content = "AvgDialog_118124_Content_5|少废话！羞辱神母的罪责等我恢复自由，一并和你算！",
        DialogType = 1,
        RoleShake = {0},
        AudioTalk = {
          "Play_A_SFX_PullOut"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_118124_Content_6|不过，门外的脚步声是不是越来越密集了？",
        DialogType = 2,
        AudioTalk = {
          "Play_A_SFX_AVG_Sea__MonsterFoot"
        }
      }),
      readonly({
        Content = "AvgDialog_118124_Content_7|噗叽噗叽的脚步声汇合成汪洋，不断有矮小壮硕的身躯砸在起居室大门上，发出沉闷的砰砰声。",
        DialogType = 3,
