      readonly({
        Content = "AvgDialog_118123_Content_4|你拔出一把小刀，切断绳索，然后腾身落地。",
        DialogType = 3,
        ScreenEffect = {"speedLine", 2},
        BgID = {
          "SScene_Apt_Deck"
