  [118962] = {
    ID = 118962,
    CnID = "主线_星辰章4_关卡5_后",
    BaseSortID = 10,
    data_list = readonly({
      readonly({
        BaseSortID = 10,
        Content = "AvgDialog_118962_Content_1|你掩上驾驶舱的门，插上插栓，听着追逐的脚步声转向另一个方向，这才回身来观察你的小小人质。",
