        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Two_Guys_Slow",
          "500"
        }
      }),
      readonly({
        TalkRole = {
          2100,
          nil,
          "Delicious"
        },
        Content = "AvgDialog_118963_Content_17|我们一定要爬上这种地方吗？",
        DialogType = 1,
        BgID = {
          "SScene_Apt_Deck"
        },
        BgTransition = 1,
        AudioTalk = {
