        Audio = {
          "Play_A_MUS_Benmo_fall_0"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Starlight"
        }
      }),
      readonly({
        Content = "AvgDialog_118957_Content_49|对抗融蚀的旅程，被黑色噩梦缠绕的两个世界，许多相似或相同的脸彼此重合……",
        DialogType = 3
      }),
      readonly({
