        RolePos = {2},
        Sequence = "SetRole(2263,4)"
      }),
      readonly({
        TalkRole = {2263},
        Content = "AvgDialog_131216_Content_50|一名优秀的调酒师，要懂得倾听客人的心声。这是属于调酒师的秘密，亲爱的客人。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_131216_Content_51|调酒师如同小鹿般轻巧地跃过威廉锋利的目光。她的手指在嘴边轻轻摇了摇，然后指向了你。",
