        AudioTalk = {
          "Play_A_SFX_Footstep_Bad_Misty_2"
        }
      }),
      readonly({
        TalkRole = {2267},
        Content = "AvgDialog_131224_Content_19|这位顾客，我从您的眼睛里看到了迷茫。",
        DialogType = 1,
        AudioTalk = {
          "Play_A_SFX_Whisper"
        },
        Audio = {
