      readonly({
        Content = "AvgDialog_131205_Content_2|叮叮——",
        DialogType = 3,
        BgID = {
          "SScene_DesertInnDay"
        },
        AudioTalk = {
          "Play_A_SFX_Small_Bell_Hit_Rushy"
        },
