      readonly({
        Content = "AvgDialog_131220_Content_39|弥萨格典礼室的舞台上，她为你一人旋转。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_131220_Content_40|伦蒂尼恩的星空下，她踮起的脚尖触碰夜空中飞舞的萤光。",
