      readonly({
        Content = "AvgDialog_131209_Content_81|神圣血腥的灯光下，污秽的壁画上延伸出无数的黑影，挡在你的面前……",
        DialogType = 3,
        AudioTalk = {
          "Play_A_SFX_Black_Mist_Surges_03",
