        AudioTalk = {
          "Play_A_SFX_Metal_Spinning_Wheel_Abstract_A"
        }
      }),
      readonly({
        TalkRole = {2287},
        Content = "AvgDialog_131213_Content_17|我亲爱的使徒啊……我们的信徒为你带来了你最为渴望的祭品。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_131213_Content_18|丝线轻转，暗色纺轮猛然绽放，将幽暗黏腻的光洒向舞台的每一个角落。",
