        AudioAmbient = {
          "Play_A_SFX_Amb_NO_Thinking"
        }
      }),
      readonly({
        Content = "AvgDialog_131213_Content_31|祂没有面孔，没有形状。祂是神明忠诚的传令者，遥望着虚空之中神明沉睡的方向。",
        DialogType = 3,
        AudioTalk = {
