        AudioTalk = {
          "Play_A_SFX_Hit_Jump_Shock"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_131213_Content_63|呵呵呵呵……哈哈哈哈！故事的第三幕，降临？……哈，哈哈。第三幕，没错。但这不是你的故事，亲爱的涅芙蕾亚。",
        DialogType = 1,
        RolePos = {0},
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_131213_Content_64|第三幕故事，由我来书写。而我将这故事命名为——<Big:<color=#98918C>欢愉</color>！>",
        DialogType = 1,
        RolePos = {0},
        ScreenEffect = {"blackSmoke", 1},
        AudioTalk = {
          "Play_A_SFX_Black_Mist_Surges_02"
        }
      }),
      readonly({
