        Content = "AvgDialog_145527_Content_58|<Shake:<Red:「捂住耳朵，不要听。」>>",
        DialogType = 2
      }),
      readonly({
        TalkRole = {2402},
        Content = "AvgDialog_145527_Content_59|<Shake:「听见歌声的人，会被引诱，被吞噬……然后升到天上，变成<Red:月亮>。」>",
