        ScreenEffect = {
          "smoke",
          2,
          "flame",
          2
        },
        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        TalkRole = {2402},
        Content = "AvgDialog_145527_Content_109|好了，本次登山的危险性和应急预案已经和大家讲解完毕了。",
        DialogType = 1,
        BgID = {
          "SScene_SnowMountaintown"
        },
