      }),
      readonly({
        Content = "AvgDialog_145527_Content_115|……",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_145527_Content_116|…………",
        DialogType = 3,
        ScreenEffect = {"snow", 1},
