        DialogType = 3,
        RoleHide = {1},
        AnimState = "UI_Story_Panel_AvgDialogBg_zuoyou_vx"
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_145520_Content_14|我们是登山队的，来这里避避风雪，没有恶意的。",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
