      readonly({
        TalkRole = {
          2419,
          nil,
          "Surprised"
        },
        Content = "AvgDialog_145520_Content_33|啊……？",
        DialogType = 1,
        RolePos = {4},
        Audio = {
          "Play_A_MUS_Kalabu_sneaking_120"
        }
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Serious"
