        Content = "AvgDialog_145520_Content_47|戏看够了吗？",
        DialogType = 1,
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_145520_Content_48|咳，那个，卡斯托尔，欢迎你加入我们探险队。",
