          "Play_A_SFX_Howling_Wind_Weak_A"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Street_Fog"
        }
      }),
      readonly({
        TalkRole = {1149},
        Content = "AvgDialog_145520_Content_64|你刚才说，你在寻找你的孪生兄弟，对吗？",
        DialogType = 1,
        RolePos = {4},
        Sequence = "SetRole(2419,2)"
