      }),
      readonly({
        TalkRole = {2414},
        Content = "AvgDialog_145518_Content_5|湖里有什么东西吗？",
        DialogType = 1,
        RolePos = {2},
        Sequence = "SetRole(1149,4)",
        AudioManageEvent = {
          "Stop_Avg_Amb_Long_Fideout"
        }
