        Audio = {
          "Play_A_SFX_Amb_NO_Thinking"
        }
      }),
      readonly({
        Content = "AvgDialog_145518_Content_16|汀克特咬了咬嘴唇。",
        DialogType = 3,
        RoleHide = {1143},
        ScreenEffect = {"disturb", 2},
        Sequence = "SetRole(1149,3,Angry2)",
        AudioTalk = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        TalkRole = {
          1149,
          nil,
          "Angry2"
