          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_145522_Content_2|风雪小了，可天色却比风雪大作时更难看。",
        DialogType = 3,
        BgID = {
          "SScene_Overcast"
        },
        BgTransition = 2,
        AudioTalk = {
          "Play_A_SFX_Howling_Wind_Weak_A"
