        },
        Content = "AvgDialog_145522_Content_53|<Shake:<Big:波吕克斯……！！！>>",
        DialogType = 1,
        RoleShake = {0},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        AudioTalk = {
