        }
      }),
      readonly({
        TalkRole = {2404},
        Content = "AvgDialog_145522_Content_54|<Italic:……哥哥，我冷……>",
        DialogType = 1,
        ScreenEffect = {"disturb", 1},
        AudioTalk = {
          "Play_A_SFX_DevilWhisper",
          "Play_A_SFX_Whisper"
        },
        AudioAmbient = {
          "Play_Play_A_SFX_Memory_Confusion",
          "Play_A_SFX_Tinnitus"
        }
      }),
      readonly({
        TalkRole = {2404},
        Content = "AvgDialog_145522_Content_55|<Italic:哥哥，禁闭室好黑，好暗，好可怕……求求你……让我出去……教主大人……>",
        DialogType = 1
      }),
      readonly({
        TalkRole = {2404},
        Content = "AvgDialog_145522_Content_56|<Shake:<Italic:……哥哥，你怎么不来找我……>>",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          2419,
          nil,
          "Surprised"
        },
        Content = "AvgDialog_145522_Content_57|波吕克斯！！你等等我，我这就来——",
