          "600"
        },
        AudioAmbient = {
          "Play_A_SFX_Monster_Wendigo_Roar"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_145526_Content_32|<Big:威廉，准备！！>",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
