        },
        Content = "AvgDialog_145511_Content_19|<Shake:唔！！>",
        DialogType = 1,
        RoleShake = {0},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        AudioTalk = {
          "Play_A_SFX_Hit_Jump_Shock"
        }
      }),
      readonly({
        Content = "AvgDialog_145511_Content_20|卡斯托尔闷哼了一声，可他没有退缩。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145511_Content_21|别浪费卡斯托尔创造的机会，就现在！",
        DialogType = 2,
