  [145514] = {
    ID = 145514,
    CnID = "主线_星辰章6_关卡7_BOSS战后",
    BaseSortID = 14,
    data_list = readonly({
      readonly({
        BaseSortID = 14,
        Content = "AvgDialog_145514_Content_1|最后一只温迪戈，散在了卡斯托尔的影子下。",
        DialogType = 3,
        ScreenEffect = {"snow", 1},
        BgID = {
          "SScene_SnowRoad"
        },
        BgTransition = 6,
        AudioTalk = {
          "Play_A_SFX_Fog_Disappear_re",
          "Play_Play_A_SFX_SteamFly"
        },
        Audio = {
          "Play_A_Mus_AfterWar_Ver4_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Howling_Wind_Widge_Lv2"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_145514_Content_2|然后掠过耳畔的风突然变得清明起来。风里不再夹杂任何声音了。",
        DialogType = 3,
        AudioTalk = {
          "Play_A_SFX_Howling_Wind_Weak_C"
        }
      }),
      readonly({
        Content = "AvgDialog_145514_Content_3|安静意味着安全，这种安全却让人怅然若失。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_145514_Content_4|伊芙琳看了一眼卡斯托尔的翅膀，但她的神色如常，仿佛天底下每个人都隐藏着一对翅膀一样自然。",
        DialogType = 3,
        Sequence = "SetRole(1920,4,Pain);SetRole(2414,2);"
      }),
      readonly({
        TalkRole = {2414},
        Content = "AvgDialog_145514_Content_5|我来替你包扎。",
        DialogType = 1,
        RolePos = {2},
        AudioTalk = {
          "Play_A_SFX_Lightly_Clothes_Rub_01"
        },
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        TalkRole = {
          1920,
          nil,
          "Sad"
        },
        Content = "AvgDialog_145514_Content_6|抱歉……一直隐藏这一点。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {
          2414,
          nil,
          "Smile"
        },
        Content = "AvgDialog_145514_Content_7|没关系。我们都是来寻找死者复生级别的超凡奇迹的……在这种时候发现打破常识的存在，是好消息才对。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Smile2"
        },
        Content = "AvgDialog_145514_Content_8|再说了，你那身斗篷连睡觉都不肯摘下，谁都知道你身上有秘密。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_145514_Content_9|尽管语带埋怨，但你明显感觉到，经过这场战斗的大家开始卸下心防，熟络了起来。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Cute"
        },
        Content = "AvgDialog_145514_Content_10|或许人与人之间的关系，就是从释放出某个小秘密开始的，对吧？",
        DialogType = 1,
        AnimState = "avg_dialog_Amplification",
        AudioTalk = {
          "Play_A_SFX_Cloth_Movement_Light_B"
        },
        ShortAudioEffect = {
          "Play_A_SFX_ruuu",
          "400"
        }
      }),
      readonly({
        Content = "AvgDialog_145514_Content_11|不知何时，卡拉布贴近前来，笑眯眯地在你面前说出了你心里所想的话语。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_12|交换秘密可不是单方面的。",
        DialogType = 1,
        RolePos = {2},
        Sequence = "SetRole(1145,4,Smile2)",
        Audio = {
          "Play_A_MUS_Xueshan_solemn_130"
        }
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_13|你呼唤过很多次的那个罗莎姨妈，是什么很重要的人吗？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Cute"
        },
        Content = "AvgDialog_145514_Content_14|当然是我编的了。你不会真信了吧？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Proud"
        },
        Content = "AvgDialog_145514_Content_15|哼哼，骗过呆子不稀奇，骗过你可是不容易。",
        DialogType = 1,
        RolePos = {4},
        RoleShake = {0},
        ShakeDirection = {1},
        AudioTalk = {
          "Play_A_SFX_chuochuo"
        }
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_16|让温迪戈相信你被蛊惑了，远比骗过我难。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_17|他们能听见你心底的声音，然后用风复述出来。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Cute"
        },
        Content = "AvgDialog_145514_Content_18|那又有谁知道呢？可能雪山女神心里的故事太多，每一种都像是真的吧？",
        DialogType = 1,
        RolePos = {4},
        RoleShake = {0},
        ShakeDirection = {1},
        AudioTalk = {
          "Play_A_SFX_Emm"
        }
      }),
      readonly({
        Content = "AvgDialog_145514_Content_19|卡拉布用俏皮话轻巧地滑了过去。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_20|既然你不愿意说，我们肯定也不会逼问。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_21|但真心是种很宝贵的东西，即使你是个骗子，也最好不要让大家的期望落空。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_22|这是我的真心建议，听不听由你。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_145514_Content_23|威廉说完，赶到队伍前方去了。",
        DialogType = 3,
        ExitDirection = {"1183:1"},
        AudioTalk = {
          "Play_A_SFX_Footstep_Snow_Run_Single"
        }
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Angry"
        },
        Content = "AvgDialog_145514_Content_24|什么嘛。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Cute"
        },
        Content = "AvgDialog_145514_Content_25|{Male=恩公,Female=恩人}，你肯定不会像他一样不解人意的对吧？",
        DialogType = 1,
        RolePos = {3},
        RoleShake = {0},
        ShakeDirection = {1},
        AudioTalk = {
          "Play_A_SFX_cing"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_145514_Content_26|我和威廉并肩作战了很长时间，他不是一个喜欢说多余话的人。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_145514_Content_27|在我的印象里，他给过的每条建议，都行之有效。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Cry2"
        },
        Content = "AvgDialog_145514_Content_28|<Shake:呜呜，{Male=恩公,Female=恩人}，你也好冷漠……>",
        DialogType = 1,
        RolePos = {3},
        ExitDirection = {"1145:2"},
        AudioTalk = {
          "Play_A_SFX_Fun_Fear_02"
        }
      }),
      readonly({
        Content = "AvgDialog_145514_Content_29|卡拉布假装难过地走开了，你则追上了正和纳拉卡攀谈的威廉。",
        DialogType = 3,
        AudioTalk = {
          "Play_A_SFX_Snow_Walk_Couple"
        }
      }),
      readonly({
        Content = "AvgDialog_145514_Content_30|他眼神示意你走开两步，直到一侧的人听不见你们的低语。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_31|刚才和温迪戈的战斗，你有没有觉得奇怪？",
        DialogType = 1,
        BgID = {
          "SScene_SnowMountaintop"
        },
        BgTransition = 1,
        Audio = {
          "Play_A_MUS_Strange_Shock_001_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Howling_Wind_Widge_Lv2"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_145514_Content_32|哪里？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_33|纳拉卡。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_34|你回想一下，从风里那些声音响起，到温迪戈现身，到方才合围——",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_35|纳拉卡，有没有，在任何一个瞬间，被任何一只温迪戈贴近过？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_145514_Content_36|卡拉布在扮演受骗者时被温迪戈扑袭，伊芙琳被那只最高的温迪戈扫倒，卡斯托尔被咬掉了一片羽毛……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_37|包括前一次被温迪戈蛊惑时，纳拉卡好像也没有受到任何影响。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_145514_Content_38|你的意思是……",
        DialogType = 2,
        Audio = {
          "Play_A_MUS_Xueshan_repression_130"
        },
        AudioManageEvent = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_39|我没有意思。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_40|往上走还有四五天，我们没有别的向导可换。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_41|我希望是我多虑了，但我们不得不保持警惕。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145514_Content_42|这一路上，我们已经失去了一个汀克特。我不想再因为我的疏忽，让任何人留在这座山上。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_145514_Content_43|风从岩脊外缘绕过来。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        AudioTalk = {
          "Play_A_SFX_Howling_Wind_Weak_A"
        }
      }),
      readonly({
        Content = "AvgDialog_145514_Content_44|绕过远处那道蹲着敲冰的背影。",
        DialogType = 3,
        AudioTalk = {
          "Play_A_SFX_Amb_Axe_Hit_Ice"
        }
      }),
      readonly({
        Content = "AvgDialog_145514_Content_45|纳拉卡的镐尖磕在鞋底冰碴上，发出一下一下、稳定得像钟摆一样的声音。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_145514_Content_46|-海拔 6500米-",
        DialogType = 6,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [145521] = {
    ID = 145521,
    CnID = "主线_星辰章6_关卡8_前",
    BaseSortID = 15,
    data_list = readonly({
      readonly({
        BaseSortID = 15,
        Content = "AvgDialog_145521_Content_1|围炉夜话",
        Chapter = "Chapter 6;;Part 8",
        DialogType = 4,
        AudioTalk = {
          "Play_UI_AVG_Chapter_Pop",
          "Stop_Avg_CG_Audio",
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
