        Content = "AvgDialog_145517_Content_20|罪人……卡斯托尔……圣光将昭示你的罪孽。",
        DialogType = 1,
        RoleShake = {0},
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
