      }),
      readonly({
        TalkRole = {1922},
        Content = "AvgDialog_145517_Content_26|<Red:<Shake:跪伏于提灯下吧，吾将宽宥你的罪行，准许你以新的形态，重生于无罪的净土！>>",
        DialogType = 1,
        AudioTalk = {
          "Play_A_SFX_Lantern_cult_sound_effects"
        }
      }),
      readonly({
        Content = "AvgDialog_145517_Content_27|卡斯托尔没有听从。他只是向着波吕克斯继续前进。",
        DialogType = 3,
        AnimState = "avg_dialog_Amplification",
        Sequence = "SetRole(1922,3,Pain);",
        AudioTalk = {
