        ShortAudioEffect = {
          "Play_A_SFX_Zoom_In"
        }
      }),
      readonly({
        Content = "AvgDialog_145517_Content_28|即使那是温迪戈也无所谓。他只是前进。",
        DialogType = 3,
        AudioTalk = {
          "Play_A_SFX_Snow_Cloth_Footstep_Slow_C",
          "400"
        }
      }),
      readonly({
        Content = "AvgDialog_145517_Content_29|波吕克斯把刀举了起来。熟悉的刀。在上一次追捕中，卡斯托尔曾被它贯穿胸膛。",
        DialogType = 3,
        AudioTalk = {
          "Stop_A_SFX_Amb_Heartbeat_Hard_NeedStop"
