      readonly({
        Content = "AvgDialog_145532_Content_28|卡拉布已经率先翻过了最后一道冰崖。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_145532_Content_29|向上，是这趟旅程的终点，实现一切愿望的应许之地。",
