        },
        AudioAmbient = {
          "Play_A_SFX_Footstep_Bad_Misty_Once_06",
          "600"
        }
      }),
      readonly({
        Content = "AvgDialog_145512_Content_36|摩伊赖的丝线，来自阿拉克涅的赠予。",
        DialogType = 3,
        Sequence = "ShowItem(148479)",
        AudioTalk = {
          "Play_A_SFX_Magic_Threads_Emerged_From_Darkness"
