    BaseSortID = 25,
    data_list = readonly({
      readonly({
        BaseSortID = 25,
        Content = "AvgDialog_145529_Content_1|另一种春天",
        Chapter = "Chapter 6;;Part 14",
        DialogType = 4,
        AudioTalk = {
          "Play_UI_AVG_Chapter_Pop",
          "Stop_Avg_CG_Audio",
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_145529_Content_2|黑暗。无尽的黑暗。",
        DialogType = 3,
        BgID = {
          "SScene_Black"
        },
        BgTransition = 2,
        AudioAmbient = {
          "Play_A_SFX_Amb_Worm_Inside_Organic"
        }
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Hate"
        },
        Content = "AvgDialog_145529_Content_3|痛痛痛……我这是在哪里？",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_145529_Content_4|不用询问她也知道。她在蠕虫的腹中。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Hate"
        },
        Content = "AvgDialog_145529_Content_5|该死，骗人进来，自己反被吃了。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Surprised"
        },
        Content = "AvgDialog_145529_Content_6|等等，这是什么？丝线……？",
        DialogType = 2,
        RoleHide = {1},
        BgID = {
          "SScene_CG_SD_S_C01EX_8"
        },
        AudioTalk = {
          "Play_A_SFX_Magic_Threads_Emerged_From_Darkness"
        }
      }),
      readonly({
        Content = "AvgDialog_145529_Content_7|一根晶亮莹润的丝线，自远方的黑暗中探出，悬停在卡拉布的面前。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Shout"
        },
        Content = "AvgDialog_145529_Content_8|不管了不管了，你最好不是骗我的！",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_145529_Content_9|你从昏沉中醒来，眼前是一片柔软、潮湿而压抑的空洞。",
        DialogType = 3,
        ScreenEffect = {"awake", 1},
        BgID = {
          "SScene_RedWorld"
        },
        BgTransition = 1,
        Sequence = "SetRole(1183,2);SetRole(2402,4);",
        AudioTalk = {
          "Play_A_SFX_Cloth_Movement_Light_A",
          "400"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_145529_Content_10|<Shake:这里是……什么地方……？>",
        DialogType = 2,
        ScreenEffect = {"awake", 2}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145529_Content_11|根据卡拉布最后的话语推断，我们现在，正位于山的腹中。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145529_Content_12|当务之急，是找到逃出去的路。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {2402},
        Content = "AvgDialog_145529_Content_13|这地方我也没来过，恐怕当不了你们的向导了。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145529_Content_14|别担心，我们经历过远比这更难的时刻。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_145529_Content_15|%player%，你手上那是什么？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_145529_Content_16|咦，这是……阿拉克涅的丝线……",
        DialogType = 2,
        RoleHide = {1},
        BgID = {
          "CG_C206_012"
        },
        BgTransition = 2,
        AudioTalk = {
          "Play_A_SFX_Magic_Threads_Wrap_Finger_Light_Burst"
        },
        AudioManageEvent = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        Content = "AvgDialog_145529_Content_17|不知何时，这支丝线悄悄缠在了你的小指上。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_145529_Content_18|那条原本沉寂温润的丝线，此刻正闪耀流动着迷幻的光泽，尾端自然地延伸向远方的黑暗中。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_145529_Content_19|这是命运的指引？跟着它向前看看吧。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_145529_Content_20|卡拉布循着丝线，不知前进了多久。在丝线的尽头，出现了一缕光。",
        DialogType = 3,
        BgID = {
          "SScene_CG_SD_S_C06_17"
        },
        BgTransition = 6,
        AudioTalk = {
          "Play_A_SFX_Mirror_Evil_Light_02"
        }
      }),
      readonly({
        TalkRole = {
          1145,
          nil,
          "Surprised"
        },
        Content = "AvgDialog_145529_Content_21|光……？",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_145529_Content_22|光影骤然变幻。",
        DialogType = 3,
        ScreenEffect = {"disturb", 1},
