        ScreenEffect = {"disturb", 2},
        BgID = {
          "SScene_IllusionWhite"
        }
      }),
      readonly({
        TalkRole = {2408},
        Content = "AvgDialog_145529_Content_24|喂，卡拉布，慢点！",
        DialogType = 1,
        RolePos = {4},
