    CnID = "测试剧情_滤镜预览",
    BaseSortID = 10,
    data_list = readonly({
      readonly({
        BaseSortID = 10,
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_1|喂，醒醒！",
        DialogType = 1,
        ScreenEffect = {"awake", 1},
        BgID = {
          "SScene_LondonDaytime"
        }
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_2|嗯？你问刚才那个睁眼又闭上的效果是什么？",
        DialogType = 1,
        ScreenEffect = {"awake", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_3|咳咳，这可是我们的睁眼滤镜哦！",
        DialogType = 1,
        ScreenEffect = {"awake", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_4|除此之外，我们还有很多其他滤镜，来和汉娜温习一遍吧！",
        DialogType = 1,
        ScreenEffect = {"awake", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_5|说起1900年的伦敦，大家的第一反应是什么呢？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_6|答案当然是雾咯！",
        DialogType = 1,
        ScreenEffect = {"smoke", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_7|白茫茫的一片，是不是勾起了大家的时代回忆？",
        DialogType = 1,
        ScreenEffect = {"smoke", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_8|说起回忆，我们还有回忆滤镜哦，就像现在这样！",
        DialogType = 1,
        ScreenEffect = {"retro", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_9|怎么样，是不是有点老电影的质感？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_10|回忆时间结束！接下来可是我们的重头戏——",
        DialogType = 1,
        ScreenEffect = {"retro", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_11|模拟融蚀浆流淌的粘液滤镜！",
        DialogType = 1,
        ScreenEffect = {"mucus", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_12|这是一个比较长的滤镜，建议配合多句对白食用哦。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_13|……",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_14|……",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_15|好了，时间到！下面来到我们的天气模块——",
        DialogType = 1,
        ScreenEffect = {"mucus", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_16|下雪啦！",
        DialogType = 1,
        ScreenEffect = {"snow", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_17|阿嚏！阿嚏！今天穿得有点少了……",
        DialogType = 1,
        ScreenEffect = {"snow", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_18|着火啦！",
        DialogType = 1,
        ScreenEffect = {"flame", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_19|天干物燥，小心火烛！",
        DialogType = 1,
        ScreenEffect = {"flame", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_20|下雨啦！",
        DialogType = 1,
        ScreenEffect = {"rain", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_21|汉娜的心也随着下雨天变得有些忧郁了呢。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_22|看了那么多滤镜，脑袋是不是有点晕乎乎的？",
        DialogType = 1,
        ScreenEffect = {"rain", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_23|嘻嘻，那就加倍剂量，请出咱们的眩晕滤镜！",
        DialogType = 1,
        ScreenEffect = {"disturb", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_24|怎么样，是不是很晕，很晕……",
        DialogType = 1,
        ScreenEffect = {"disturb", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_25|接下来我们搞点浪漫的玫瑰！红花启动！",
        DialogType = 1,
        ScreenEffect = {"redFlower", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_26|浪不浪漫我不知道，但花粉过敏的同学有难了，因为——",
        DialogType = 1,
        ScreenEffect = {"redFlower", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_27|紧随红玫瑰之后的是哥特玫瑰！黑花启动！",
        DialogType = 1,
        ScreenEffect = {
          "blackFlower",
          1
        }
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_28|然后是让大家都摸不着头脑，不知道该用在哪里的神秘效果——",
        DialogType = 1,
        ScreenEffect = {
          "blackFlower",
          2
        }
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_29|血雾！",
        DialogType = 1,
        ScreenEffect = {"bloodSmoke", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_30|看着还怪酷的，姑且还是留着吧。",
        DialogType = 1,
        ScreenEffect = {"bloodSmoke", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_31|血雾看完了，来看看黑雾是怎么样的吧。",
        DialogType = 1,
        ScreenEffect = {"blackSmoke", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_32|黑漆漆——阴森森——伦蒂尼恩像鬼屋——",
        DialogType = 1,
        ScreenEffect = {"blackSmoke", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_33|看了这么多眼睛都累了，眨眨眼缓解一下。",
        DialogType = 1,
        ScreenEffect = {"blinkEye", 1}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_34|唔不行不行，之后还是得去找点眼药水才行。",
        DialogType = 1,
        ScreenEffect = {"blinkEye", 2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_35|好啦，以上就是目前全部的滤镜效果啦。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18823_Content_36|本期的汉娜滤镜小课堂结束，咱们下期再会哦~！",
        DialogType = 1,
        RoleExit = {1179},
        ExitDirection = {"1179:1"}
      })
    })
  },
  [18785] = {
    ID = 18785,
    CnID = "测试剧情_5_10_仪式回忆",
    BaseSortID = 11,
    data_list = readonly({
      readonly({
        BaseSortID = 11,
        Content = "AvgDialog_18785_Content_1|扭曲的现实",
        Chapter = "Chapter 5;Twisted Reality;Part 10",
        DialogType = 4,
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        Content = "AvgDialog_18785_Content_2|被折断翅膀的雏鸟，落入了黑色水潭。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18785_Content_3|主祭的絮絮祷言飘忽而坚实，狂热的言辞穿透黑色黏液，化为利刃剖开了雏鸟的胸腔。",
        DialogType = 3,
        BgID = {
          "SScene_Blood"
        },
        BgTransition = 5
      }),
      readonly({
        Content = "AvgDialog_18785_Content_4|鲜红色的液体从胸口上浮，在归于平静的黑色水面上妖冶绽放——",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18785_Content_5|她却在不断下沉，带着血迹的根，沉入最深处，沉入一个柔软而阴冷的怀抱。",
        DialogType = 3,
        BgID = {
          "CGDynamic_C01_012"
        },
        AnimState = "CG/C01/Prefab/CGDynamic_C01_012.prefab"
      }),
      readonly({
        Content = "AvgDialog_18785_Content_6|……",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18785_Content_7|……",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18785_Content_8|她看到了。\n她向上看去，「母亲」垂下三对眼柄，同她对视。",
        DialogType = 3,
        BgID = {
          "C05/Video_C05_02.mp4"
        },
        BgTransition = 5
      }),
      readonly({
        Content = "AvgDialog_18785_Content_9|那是个深红色的庞然巨物，被血液沾染的地方呈现出了透明的白。「母亲」发出微弱荧光，暂且照亮了一方小小天地。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18785_Content_10|借着光，她看见「母亲」光滑的表皮之上，大大小小分布着数不尽的黑色伤口。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18785_Content_11|「对不起……」",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18785_Content_12|黑色黏液翻涌，搅碎了滩底的平静。",
        DialogType = 3,
        ScreenEffect = {"mucus", 1}
      }),
      readonly({
        Content = "AvgDialog_18785_Content_13|「母亲」发出了一声尖利的哀鸣，触肢一阵翻动，将什么东西送入了雏鸟的胸腔。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18785_Content_14|湿滑冰冷的软体触肢缠绕着她，黑色的池水不再堵塞她的口鼻，反而如羊水一般，托举起了她的生命。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18785_Content_15|<Change>「对不起……」\n「我还……不想死……」",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18785_Content_16|水面维持着长久的平静，就连极地呼啸的风，都无法让粘稠的池水泛起涟漪。",
        DialogType = 3,
        DialogAnim = 1,
        ScreenEffect = {"mucus", 2},
        BgID = {
          "SScene_Black"
        },
        BgTransition = 7
      }),
      readonly({
        TalkRole = {1110},
        Content = "AvgDialog_18785_Content_17|弥利亚姆大人，圣女会不会已经……",
        DialogType = 2,
        BgID = {
          "SScene_SnowAltars"
        },
        BgTransition = 4
      }),
      readonly({
        TalkRole = {1168},
        Content = "AvgDialog_18785_Content_18|她于上一个星辰正位时刻出生，是“看得见”的孩子。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        TalkRole = {1168},
        Content = "AvgDialog_18785_Content_19|世界上，没有人比她更值得得到神之血脉的承认。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        Content = "AvgDialog_18785_Content_20|消瘦的女人被簇拥着，站在能够睥睨所有人的最高处。\n薄纱模糊了她的面容，即便是近侍，也无法读出主人心中所想。",
        DialogType = 3,
        RolePos = {3}
      }),
      readonly({
        TalkRole = {1168},
        Content = "AvgDialog_18785_Content_21|墨菲……",
        DialogType = 1
      })
    })
  },
  [18809] = {
    ID = 18809,
    CnID = "测试剧情_5_11_战斗后1",
    BaseSortID = 12,
    data_list = readonly({
      readonly({
        BaseSortID = 12,
        ChatID = "1",
        Content = "AvgDialog_18809_Content_1|墨菲没多忸怩，她拽着拉蒙娜走到一旁，动手解起了衣服。\n随着前襟最后一颗纽扣的解开，拉蒙娜看见了少女体内的「神」。",
