        BgID = {
          "SScene_DeckIllusion"
        },
        BgTransition = 4
      }),
      readonly({
        ChatID = "2",
        Content = "AvgDialog_18809_Content_2|心口处赫然有着一块透明皮肤，这块透明肌理拉扯着周遭的皮肤与肌肉，让整块胸腹腔都呈现着灰败衰退的白色。",
        DialogType = 3,
        BgID = {
          "SScene_CG_C05_002"
