      }),
      readonly({
        TalkRole = {1199},
        Content = "AvgDialog_18815_Content_9|嗯……",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_18815_Content_10|墨菲向前走了两步，突然身体一阵摇晃，顺着桅杆软绵绵倒下。",
        DialogType = 3,
        RoleExit = {1199},
        RoleShake = {1199}
