        Content = "AvgDialog_18798_Content_17|……带她下去。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1159,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_18798_Content_18|远离天体，她兴许能好受些。",
        DialogType = 2
      })
    })
  },
  [18797] = {
    ID = 18797,
    CnID = "CG测试_6_9_黑纹浮现2",
    BaseSortID = 17,
    data_list = readonly({
      readonly({
