  [38844] = {
    ID = 38844,
    CnID = "CG测试_大型支线_萨尔瓦多_关卡1_后",
    BaseSortID = 33,
    data_list = readonly({
      readonly({
        BaseSortID = 33,
        Content = "AvgDialog_38844_Content_1|长枪横扫地面击向年轻人的小腿。陷入疯狂的年轻男人脚下一阵踉跄，扑倒在地，你趁机反剪他的手臂，将他按在地上。",
        DialogType = 3,
        BgID = {
          "SScene_YardDay"
        }
      }),
      readonly({
        TalkRole = {1653},
        Content = "AvgDialog_38844_Content_2|放开我，让我净化！让我净化！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1025},
        Content = "AvgDialog_38844_Content_3|这是怎么回事？",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_38844_Content_4|沉稳的声音在你们身后响起，围绕在周围的议论声逐渐变小直至停歇，人们自动让开了一条路，让身穿黑色神职长袍的主教可以顺利通行。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38844_Content_5|萨尔瓦多主教蒙着双眼，却如能视物一般准确地向你们走来。满脸忧色的索菲亚紧随其后。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1653},
        Content = "AvgDialog_38844_Content_6|索菲亚……索菲亚！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38844_Content_7|年轻人突然激动起来，他以出乎你意料的力量一把挣脱了你的牵制，一下扑到索菲亚身前——",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_38844_Content_8|小心！",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_38844_Content_9|然后猛地跪了下去。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1653},
        Content = "AvgDialog_38844_Content_10|索菲亚，索菲亚，我知道错了索菲亚，求求你净化我吧！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38844_Content_11|爱、爱德华……？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38844_Content_12|是我，是我！我不该欺骗你姐姐的，我后悔了，我真的后悔了！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38844_Content_13|他一边哭，一边用膝行着向前，用极为别扭的姿势不断朝索菲亚鞠躬。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38844_Content_14|恶魔蒙蔽了我的双眼，污染了我的灵魂，求你鞭打我，净化我吧！审判将至，我不想被无罪的净土驱逐在外啊！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38844_Content_15|冷静点，爱德华，你到底在说什么呀？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38844_Content_16|求你了，索菲亚！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38844_Content_17|爱德华，停下吧。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_38844_Content_18|年轻人保持着鞠躬的姿势抬起头，怔怔地望向萨尔瓦多。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38844_Content_19|主……教……？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38844_Content_20|一道耀目的光在你的视线边缘一闪而过，你还没完全将残留的光斑从眼睛里眨去，就听到爱德华趋向癫狂的声音。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38844_Content_21|不……不是……你也是<Red:罪人>，我们都是罪人！\n忏悔，净化！不然我们都将在无尽苦海中燃烧！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Sequence = "PlayVideo(Blade_Flash1.mp4)"
      }),
      readonly({
        Content = "AvgDialog_38844_Content_23|年轻人的身体晃了晃，直直地倒在了地上。奥吉尔默默收起了用来敲晕他的长枪，转头看向你。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38844_Content_24|在他伤害到其他人前，先把他带到安全的地方吧。然后把警察叫来，让专业的人处理他。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38844_Content_25|圣堂里的人都出来了，现在应该是空的。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38844_Content_26|就这么办吧。\n希望他醒来之后能清醒一些。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38844_Content_27|他蹲下身，和你一起将爱德华从地上扶起来，架在肩上。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38844_Content_28|我来吧，%player%%sirormadam%。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38844_Content_29|没事，我都扛习惯了。站起来了反而还不好转手。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38844_Content_30|这……那就麻烦你了。\n我在这里再待一会儿，看看有没有被爱德华吓到或者弄伤的人需要帮助。",
        DialogType = 1,
        RolePos = {4},
        RoleExit = {0}
      }),
      readonly({
        Content = "AvgDialog_38844_Content_31|你点点头，正要转身，视线边缘再次闪过与方才相似的光。",
        DialogType = 3,
        RolePos = {0},
        BgID = {
          "CGDynamic_SD_L_B02_3"
        },
        AnimState = "CG/CG_SD/Prefab/CGDynamic_SD_L_B02_3.prefab"
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38844_Content_32|？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38844_Content_33|还好吗，%player%？\n如果身体不适，我一个人就可以了。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38844_Content_34|没什么，大概是被玻璃晃到眼睛了。\n我们走吧。",
        DialogType = 2
      })
    })
  },
  [38841] = {
    ID = 38841,
    CnID = "CG测试_大型支线_萨尔瓦多_关卡6_后",
    BaseSortID = 34,
    data_list = readonly({
      readonly({
        BaseSortID = 34,
        TalkRole = {1001},
        Content = "AvgDialog_38841_Content_1|唔！",
        DialogType = 2,
        BgID = {
          "SScene_YardDay"
        }
      }),
      readonly({
        Content = "AvgDialog_38841_Content_2|圆钝的牙齿咬入衣物，用力拉扯，那人已经彻底被饥饿逼疯，只知道抓着你的手臂用力撕咬。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_38841_Content_3|主君！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38841_Content_4|见你的动作被限制，周围同样饥饿的人也纷纷朝你看来。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38841_Content_5|杀了他们！不然他们会一直冲过来的，快杀了他们！",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_38841_Content_6|一双双赤红的眼睛望向了你，一双双手朝你抓来，后面跟着一张张大张的嘴和森白的牙齿。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "CGDynamic_C01_012"
        }
      }),
      readonly({
        Content = "AvgDialog_38841_Content_7|奥吉尔的喊叫被无限拉长。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38841_Content_8|你听到布料被撕裂。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38841_Content_9|热度再次袭来，然后是一阵刺痛，你知道，那是袭击你的人终于咬住了你的手。",
        DialogType = 3,
        BgID = {
          "SScene_Blood"
        },
        BgTransition = 4
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_38841_Content_10|主君！",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        RoleExit = {1123},
        ExitDirection = {"1123:2"},
        Sequence = "PlayVideo(CG_SD/Video_SD_L_B02_1.mp4)"
      }),
      readonly({
        Content = "AvgDialog_38841_Content_12|下一秒，一块巨大的石板落在了你的身前。",
        DialogType = 3,
        BgID = {
          "Sscene_CG_SD_L_B02_4"
        }
      }),
      readonly({
        Content = "AvgDialog_38841_Content_13|癫狂地朝你扑来的人们，弥漫的鲜血，混乱而令人心惊的惨叫……所有的一切都被隔绝在石板之后。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38841_Content_14|一只戴着黑色手套的手覆在你的小臂上，微凉的布料抚平了疼痛，也拂去了在你手臂上滑落的鲜血。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38841_Content_15|咬你的人已经不知去向，站在你身侧，握着你的小臂的，是穿着黑色长袍的主教。",
        DialogType = 3,
        BgID = {
          "SScene_Black"
        },
        BgTransition = 5
      }),
      readonly({
        Content = "AvgDialog_38841_Content_16|他身后悬着四块石板，每块上面都印刻着复杂的符文，每个符文上面都有蓝光流转，如同被缩小无数倍的星河。",
        DialogType = 3,
        BgID = {
          "CG_SD/Video_SD_L_B02_2.mp4"
        },
        BgTransition = 5
      }),
      readonly({
        Content = "AvgDialog_38841_Content_17|其中一缕蓝光顺着他的手臂流向了你，你低头，小臂上的咬伤已经停止出血，甚至在你的注视下逐渐痊愈。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38841_Content_18|萨尔瓦多……主教？",
        DialogType = 2
      })
    })
  },
  [38843] = {
    ID = 38843,
    CnID = "CG测试_大型支线_萨尔瓦多_关卡7_前",
    BaseSortID = 35,
    data_list = readonly({
      readonly({
        BaseSortID = 35,
        Content = "AvgDialog_38843_Content_1|将罪恶净化",
        Chapter = "the Cleansing;Part 7",
        DialogType = 4,
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38843_Content_2|主教……萨尔瓦多主教……",
        DialogType = 2,
        RolePos = {0},
        RoleHide = {1},
        ScreenEffect = {"retro", 1},
        BgID = {
          "CG_SD/Video_SD_S_C01EX_4.mp4"
        }
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38843_Content_3|爱德华？",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_4|腥甜的气味随着脚步的靠近愈发浓烈，萨尔瓦多早已摒弃了寻常的视觉，却在再度苏醒后变得能看到属于灵魂的光亮。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_5|此刻，他眼前的那个灵魂在黑暗中浮浮沉沉，几欲熄灭。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38843_Content_6|天啊，爱德华，快扶着我，我带你去医院。",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38843_Content_7|不！我……不。这是我自找的。",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_8|灵魂再次闪烁，甚至愈发暗淡下去。\n他的时间不多了。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38843_Content_9|你警告过我的，不要再以他人的苦痛为生，不要再欺骗。我应该改正的，但我一直没听……咳！",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_10|咳呛，一滩液体砸到了地上。\n鲜血的味道更加刺鼻了。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38843_Content_11|现在她死了……<Blue:米莉>死了……！<Blue:汤普森>那个疯子要我为她陪葬。我……我不想死，主教阁下，但我也……",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38843_Content_12|对不起，对不起……宽恕我吧，主教阁下，只有父神能宽恕我了，只有父神……",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38843_Content_13|……“那些曾经犯错的，祂也愿意张开怀抱，只要他们真心地进行悔改”。",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_14|莹莹的蓝光自下而上映亮了部分彩窗，彩窗上的父神垂着眼眸静静地望着，一如数百年来所做的那样。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_15|在萨尔瓦多的手下，年轻人满身的伤飞速愈合，甚至没留下多少疤痕。",
        DialogType = 3,
        ScreenEffect = {"retro", 2},
        BgID = {
          "CGDynamic_C01_012"
        }
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38843_Content_16|睁开眼吧，爱德华，珍惜父神予以你的机会。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_17|蓝光如蛇一般在你身上游走，所有的疼痛疲惫都随着它的到访一扫而空。\n你浑身一轻，感到前所有为的精力充沛。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        BgTransition = 5
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_38843_Content_18|萨尔瓦多主教……是……",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_19|石板上的符文如呼吸一般规律闪烁，更多的蓝光像巨树的根须向四面八方延展。无数的伤害与死亡、痛哭与哀嚎，都在这骤然降临的神迹中得到缓解。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_20|圣堂熏香的气味轻拂过你的鼻尖，浅浅的，淡淡的，仿佛不曾存在，却又将属于鲜血的气味完全遮盖。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38843_Content_21|……唤醒体。",
        DialogType = 2,
        DialogAnim = 1,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        BgTransition = 5
      }),
      readonly({
        Content = "AvgDialog_38843_Content_22|他猛地一扭身，张嘴就要朝你手上咬去。牙齿伴随着湿热的吐息靠近你的手臂，你汗毛直立，绷紧身体，做好了疼痛袭来的准备。",
        DialogType = 3,
        RoleHide = {1},
        ScreenEffect = {"retro", 1},
        BgID = {
          "Sscene_CG_SD_L_B02_4"
        },
        BgTransition = 5
      }),
      readonly({
        Content = "AvgDialog_38843_Content_23|突然，一只戴了黑色手套的手覆盖在你手臂之上。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_24|布料的微凉，和圣堂熏香令人沉寂安心的气味弥散开来。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38843_Content_25|那时候你也是这样治愈我的吗？\n这……是你的能力吗？",
        DialogType = 2,
        ScreenEffect = {"retro", 2},
        BgID = {
          "SScene_CourtYard"
        },
        BgTransition = 5
      }),
      readonly({
        Content = "AvgDialog_38843_Content_26|萨尔瓦多望向你，透过白色绷带而来的目光却依旧温和，甚至悲悯。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1025},
        Content = "AvgDialog_38843_Content_27|你又一次救了那些罪人。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_38843_Content_28|一个冰冷的声音打断你的话语，你转身，不出意料地看到了索菲亚的身影。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38843_Content_29|你身受<Yellow:「赐福」>，拥有常人所没有的力量，却只知道放纵这些罪恶的灵魂，任由他们散播苦难。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38843_Content_30|你才是这里最大的罪人，萨尔瓦多。我发誓要让你认清自己的罪孽。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_38843_Content_31|索菲亚小姐，你到底在说什么？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38843_Content_32|还不明白吗？你们眼前的这位主教，这位滥用神力的伪善者，掩藏自己的身份，一次又一次地将那些罪恶的人从死亡的边缘救回。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38843_Content_33|他以仁慈的名义给予他们一次又一次机会，让义人一次又一次受难——不能再这样下去了。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38843_Content_34|<Yellow:提灯>给予了我指引，<Yellow:纯银塑身的持灯者>降使命于我，令我开始光明的审判。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_35|她举起手，一把形状奇特的手持镜对准了夜空，阳光落入其中的瞬间变得猩红。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38843_Content_36|我将在今日<Red:净化>罪恶，迎来无罪的净土。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38843_Content_37|天色骤然暗了下去，太阳消失在空中，一旁的红色虚影却越来越大。\n那是月亮，一个巨大的，血色的月亮。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "CGDynamic_C01_012"
        }
      }),
      readonly({
        Content = "AvgDialog_38843_Content_38|黑色吞噬了整片天空，月光倾倒，将所有的一切都染成刺目的红。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_White"
        }
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38843_Content_39|罪人们啊，切开你们的肉体，将你们的罪恶流出——",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_38843_Content_40|本在互相厮打的人们骤然转头，用刀刃和牙齿撕开自己的皮肉。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38843_Content_41|将那些不愿净化的清除！",
        DialogType = 1
      }),
      readonly({
        Sequence = "PlayVideo(CG_SD/Video_SD_L_B02_4.mp4)"
      }),
      readonly({
        Content = "AvgDialog_38843_Content_43|他们一个接一个转向你，眼里反射着红月的光。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        }
      })
    })
  },
  [38842] = {
    ID = 38842,
    CnID = "CG测试_大型支线_萨尔瓦多_关卡8_前",
    BaseSortID = 36,
    data_list = readonly({
      readonly({
        BaseSortID = 36,
        Content = "AvgDialog_38842_Content_1|我们的过错",
        Chapter = "To Err, To Forgive;Part 8",
        DialogType = 4
      }),
      readonly({
        Content = "AvgDialog_38842_Content_2|血月高悬，猩红的光如同最有效的催化剂，瞬间将人群点燃。",
        DialogType = 3,
        BgID = {
          "Sscene_CG_SD_L_B02_6"
        },
        BgTransition = 4
      }),
      readonly({
        Content = "AvgDialog_38842_Content_3|斗殴变为虐打，自残变为自杀，而那些本就在积极寻死的，更是开始以匪夷所思的方式结束自己的生命。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38842_Content_4|腥味将本来萦绕在你们上空的熏香气息给彻底淹没。红光之下，飞溅的血液看上去如墨般漆黑，癫狂的人们形容狰狞，宛如恶鬼。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38842_Content_5|在这片人间炼狱中，唯有索菲亚的衣裙仍旧干净。她抹去飞溅到脸上的血液，放声大笑。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38842_Content_6|流吧，流出你们身体里的罪恶！流出黑色的罪孽！",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38842_Content_7|忏悔吧，罪人！在严厉的持灯者降下审判前，净化你们肮脏的灵魂！",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38842_Content_8|手持镜不断闪烁，猩红的光刺痛了你的眼睛，甚至穿过双眼，直直地深入你的头脑和精神。",
        DialogType = 3,
        BgID = {
          "CG_SD/Video_SD_L_B02_7.mp4"
        },
        BgTransition = 2
      }),
      readonly({
        Content = "AvgDialog_38842_Content_9|有什么东西被越扯越紧，越扯越紧，是什么？好难受，好疼，好想吐……",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_38842_Content_10|主……君……",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38842_Content_11|好红，为什么这么红？到处都是深重的红色，压得你喘不过气。你必须离开这个光，必须离开……",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38842_Content_12|微凉，然后是圣堂的熏香。",
        DialogType = 3,
        BgID = {
          "SScene_Black"
        },
        BgTransition = 4
      }),
      readonly({
        Content = "AvgDialog_38842_Content_13|蓝色的光映亮了部分黑暗，你猛地睁开眼，发现奥吉尔跪在你身前，嘴角流下了一股黑色的液体。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38842_Content_14|和他进行断链训练时一模一样。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38842_Content_15|奥吉尔！",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_38842_Content_16|你赶紧专注精神，银钥匙在你胸口微微震动。短暂的银色闪光后，奥吉尔重新站了起来。",
        DialogType = 3,
        Sequence = "PlayVideo(Avg/UI_Key_Work_rgb.mp4)"
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38842_Content_17|净化，<Big:净化！>",
        DialogType = 1,
        RolePos = {2},
        BgID = {
          "CGDynamic_SD_L_B02_5"
        },
        AnimState = "CG/CG_SD/Prefab/CGDynamic_SD_L_B02_5.prefab"
      }),
      readonly({
        Content = "AvgDialog_38842_Content_18|手持镜愈发明亮，你正要挡住眼睛，却发现自己面前落下了一个阴影。",
        DialogType = 3,
        BgID = {
          "Sscene_CG_SD_L_B02_6"
        }
      }),
      readonly({
        Content = "AvgDialog_38842_Content_19|巨大的石板悬在你的身前，繁复的符文上蓝光流转，但已比先前要暗淡不少。",
        DialogType = 3,
        BgID = {
          "CGDynamic_C01_012"
        }
      }),
      readonly({
        Content = "AvgDialog_38842_Content_20|你回头，却发现已经看不到萨尔瓦多的身影。",
        DialogType = 3,
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38842_Content_21|奥吉尔，去夺下那面镜子。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_38842_Content_22|可是，主君你——",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38842_Content_23|我能照顾好自己。主教阁下给我们争取的时间不多了，动作快！",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_38842_Content_24|是！",
        DialogType = 1,
        RolePos = {3}
      })
    })
  },
  [38845] = {
    ID = 38845,
    CnID = "CG测试_大型支线_萨尔瓦多_关卡8_后",
    BaseSortID = 37,
    data_list = readonly({
      readonly({
        BaseSortID = 37,
        Content = "AvgDialog_38845_Content_1|奥吉尔用力一掷，长枪钉在了银镜之上。",
        DialogType = 3,
        BgID = {
          "SScene_White"
        }
      }),
      readonly({
        Content = "AvgDialog_38845_Content_2|银镜的碎片如坠落的星辰，随之彻底瓦解的，是天上遍布裂痕的鲜红月亮。",
        DialogType = 3,
        BgID = {
          "SScene_White"
        },
        BgTransition = 2
      }),
      readonly({
        Content = "AvgDialog_38845_Content_3|怪物发出一声悲戚的尖叫，随后轰然倒下。庞大的身躯迅速溶解成一滩深色的血液，只留下一个匍匐在地的人形。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38845_Content_4|血月散去，阳光重新洒向地面，将那个躺在血泊中的人照亮。\n索菲亚呆呆地望着天空，嘴里仍在低语。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38845_Content_5|<Yellow:伊芙>女士……我辜负了你，辜负了<Yellow:持灯者>……\n我没能净化他们，没能净化罪恶……",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38845_Content_6|持灯者……纯银塑身之人……请你……",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_38845_Content_7|她吸入一口气，然后，再也没能将它呼出来。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38845_Content_8|整个广场一片狼藉——被怪物所伤的人躺在地上，不少已经失去生命，还有些正痛苦地呻吟着，不明白自己为什么会变成现在的模样。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_YardDay"
        },
        BgTransition = 3
      }),
      readonly({
        TalkRole = {1567},
        Content = "AvgDialog_38845_Content_9|呃……我的头好痛……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1568},
        Content = "AvgDialog_38845_Content_10|这是哪里？我怎么……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1674},
        Content = "AvgDialog_38845_Content_11|主教阁下，那是主教阁下吗？他这是怎么了？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38845_Content_12|请……等……",
        DialogType = 2,
        RolePos = {0},
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        Content = "AvgDialog_38845_Content_13|蓝光不知何时彻底散去了。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38845_Content_14|萨尔瓦多跪在石板之间，他朝你抬起头，白色的绷带下流出两行血泪。",
        DialogType = 3,
        BgID = {
          "SScene_CG_SD_L_B02_1"
        }
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_38845_Content_15|主君，主教这是怎么了？",
        DialogType = 2,
        BgID = {
          "CGDynamic_SD_L_B02_1"
        },
        AnimState = "CG/CG_SD/Prefab/CGDynamic_SD_L_B02_1.prefab"
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38845_Content_16|应该是链接者精神力不够，但这样严重的不稳……我从来没见过。",
        DialogType = 2,
        BgID = {
          "Sscene_CG_SD_L_B02_2"
        }
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38845_Content_17|我的链接者……是……这里的前任主教……我不能……透支他……",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38845_Content_18|苍白的使者……请……请你……",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        Content = "AvgDialog_38845_Content_19|他颤抖着抬起手，轻轻覆在你的肩上。\n但你已经几乎感觉不到他的重量了。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38845_Content_20|他在迅速消散，除非——",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38845_Content_21|你握住萨尔瓦多的手，闭上了眼睛。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "CGDynamic_C01_012"
        }
      }),
      readonly({
        Content = "AvgDialog_38845_Content_22|黑暗。\n黑暗如此安详，像一个怀抱，又像一场深眠。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        Content = "AvgDialog_38845_Content_23|纷繁的光点在你的意识中浮现：慌乱的是周围的市民，坚定的是奥吉尔，还有一个散发着浅淡的、几乎看不见的蓝光的，是虚弱的主教。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "CG_SD/Video_SD_S_C01EX_4.mp4"
        },
        BgTransition = 2
      }),
      readonly({
        Content = "AvgDialog_38845_Content_24|你向它靠近，听到朦胧的交谈声。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38845_Content_25|我家族一直致力于消除苦难，传播父神的恩泽，为什么却沦落到这个地步？",
        DialogType = 1,
        RolePos = {4},
        ScreenEffect = {"retro", 1},
        BgID = {
          "SScene_ChurchNight"
        },
        BgTransition = 2
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38845_Content_26|闭嘴！不准你这样污蔑我父亲，他不是那样的人！不是！",
        DialogType = 1,
        RolePos = {4},
        BgID = {
          "SScene_LondonDaytime"
        },
        BgTransition = 2
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38845_Content_27|主教阁下，为什么世界总是充满苦难？",
        DialogType = 1,
        RolePos = {4},
        BgID = {
          "SScene_GraveyardDay"
        },
        BgTransition = 2
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38845_Content_28|如果世上没有罪人，是不是……像我姐姐、我母亲，像济贫院里的孩子那样的人，就不会再受他人所害？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38845_Content_29|是不是就能摆脱苦难，永远快乐地生活？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38845_Content_30|这是我的责任。",
        DialogType = 1,
        RolePos = {3},
        ScreenEffect = {"retro", 2},
        BgID = {
          "SScene_dreamarea"
        },
        BgTransition = 2
      }),
      readonly({
        Content = "AvgDialog_38845_Content_31|萨尔瓦多的身影浮现在了你的身旁。\n回忆在你们面前不断切换，他看上去没什么表情，你却能感受到一丝哀伤。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38845_Content_32|我一直知道的，她心中始终怀有怨恨。我以为她会放下，结果却只是放任了恨意的滋长。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38845_Content_33|他说那天是你救了他，是这样吗，萨尔瓦多主教？可是为什么？\n他做了那么多坏事，骗了那么多人，你为什么还要帮助他？",
        DialogType = 1,
        RolePos = {4},
        ScreenEffect = {"retro", 1},
        BgTransition = 2
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38845_Content_34|第二次机会？谁能给我家第二次机会，谁能给我姐姐，我母亲第二次机会？\n她们死了，萨尔瓦多主教，她们回归父神的怀抱，只剩下我……",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38845_Content_35|只剩下我……",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38845_Content_36|父神垂怜，让我重新获得一次生命。我应当做得更好，现在却重蹈覆辙。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1320},
        Content = "AvgDialog_38845_Content_37|那些窃贼、赌徒、瘾君子，他们到你这里来寻求的根本不是宽恕和机会，而是自我安慰！一个能继续作恶的借口！",
        DialogType = 1,
        RolePos = {4},
        ScreenEffect = {"retro", 1},
        BgTransition = 2
      }),
      readonly({
        TalkRole = {1320},
        Content = "AvgDialog_38845_Content_38|罪人不知悔改，不会悔改。无尽的宽容只会让善者心寒，恶者猖狂。\n这样下去，你谁也救不了。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38845_Content_39|我宽恕他们，给予他们慰藉，正如我宽恕所有人，给予所有人慰藉。\n所有人都享有父神的爱，所有人都同时具有行差踏错与回归正途的资格。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38845_Content_40|苦是父神不愿意看到的，苦是父神希望消解的，也是我作为祂的代行者应当消解的。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38845_Content_41|我造成的苦难，必须由我亲自弥补。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38845_Content_42|他伸出手轻轻一拂，泛黄的回忆泛着水一般的波纹缓缓消散，重新聚拢成象征他精神的光点。",
        DialogType = 3,
        ScreenEffect = {"retro", 2},
        BgID = {
          "CG_SD/Video_SD_S_C01EX_4.mp4"
        },
        BgTransition = 2
      }),
      readonly({
        Content = "AvgDialog_38845_Content_43|他转向你，将捧着的光点递到你的面前。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38845_Content_44|请你帮助我，苍白的使者。\n帮我消除他们身上的苦，让他们能够安然地走完剩下的路。",
        DialogType = 1,
        RolePos = {2},
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38845_Content_45|接过光点",
        DialogType = 5,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38845_Content_46|蓝色的光在你面前如蛛丝一般摇摆，一头链接着一个年迈但温和的精神，另一头则深入你面前的光点之中。",
        DialogType = 3,
        BgID = {
          "Sscene_CG_SD_L_B02_7_A"
        },
        BgTransition = 2
      }),
      readonly({
        Content = "AvgDialog_38845_Content_47|你小心地将细线截断，用属于你自己的颜色将它浸染。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38845_Content_48|白色顺着丝线一路向内，向内，光斑亮起，慢慢地驱散黑暗。",
        DialogType = 3,
        BgID = {
          "CGDynamic_SD_L_B02_6"
        },
        AnimState = "CG/CG_SD/Prefab/CGDynamic_SD_L_B02_6.prefab"
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38845_Content_49|谢谢你。",
        DialogType = 2,
        RoleHide = {1}
      })
    })
  },
  [38846] = {
    ID = 38846,
    CnID = "CG测试_大型支线_萨尔瓦多_关卡9",
    BaseSortID = 38,
    data_list = readonly({
      readonly({
        BaseSortID = 38,
        Content = "AvgDialog_38846_Content_1|燃起白色的希望",
        Chapter = "Pale-Flamed Hope;Part 9",
        DialogType = 4,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_2|石板再次升起。",
        DialogType = 3,
        RolePos = {3},
        BgID = {
          "SScene_Black"
        },
        BgTransition = 4
      }),
      readonly({
        RoleHide = {1},
        BgTransition = 3,
        Sequence = "PlayVideo(CG_SD/Video_SD_L_B02_5.mp4)"
      }),
      readonly({
        Content = "AvgDialog_38846_Content_4|萨尔瓦多抬起手，血液从他身上、从他四周源源不断地流向石板。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "CG_SD/Video_SD_L_B02_6.mp4"
        }
      }),
      readonly({
        Content = "AvgDialog_38846_Content_5|蓝光再次沿着纹路流转，一明一暗，宛如呼吸。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_6|创生的父神，仁慈的造主，请聆听我的祈求。",
        DialogType = 1,
        RolePos = {0},
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_7|温润的蓝以石板为中心向四周深处密匝的须根，它们穿过人群，清凉的风驱散了残存的血腥味，留下淡淡的熏香气息。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_8|站着的人们缓缓坐下。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_9|坐着的那些张着嘴，呆呆地看着面前堪称神迹的一幕。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_10|那些失去意识、甚至停止呼吸的，都在微风中缓缓睁开了眼。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_11|请消去他们的伤痛，抚平他们的心。",
        DialogType = 1,
        RolePos = {2},
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_12|人们的目光变得空茫，身体愈发放松。慌乱与恐惧一扫而空，取而代之的是一种舒缓和宁静。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_13|让他们不再受苦难折磨，并给予他们赐福。",
        DialogType = 1,
        RolePos = {2},
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_14|潮汐般的光向四周涌去，所有人都闭上了眼，像是沉浸在宁静之中。",
        DialogType = 3,
        BgID = {
          "SScene_White"
        },
        BgTransition = 3
      }),
      readonly({
        Content = "AvgDialog_38846_Content_15|皎洁的明月俯瞰着一切，一如往常，唯有一团糟的广场证明着方才的癫狂。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38846_Content_16|石板轻响，又化作看不见的虚影融进夜色。萨尔瓦多整了整衣衫，走到索菲亚身旁。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_17|……你不该救我的。",
        DialogType = 1,
        RolePos = {4},
        BgID = {
          "SScene_YardDay"
        },
        BgTransition = 2
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_18|“凡是迷途知返的，都能回到我的怀抱”。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_19|“因为你们皆是我的子，而我爱着你们所有”。\n但你错了，主教，《圣典》也错了。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_20|有的人是永远也不会变的。",
        DialogType = 1,
        RolePos = {4},
        BgID = {
          "CGDynamic_C02_006_out"
        }
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_21|你来干什么？",
        DialogType = 1,
        RolePos = {4},
        ScreenEffect = {"retro", 1},
        BgID = {
          "SScene_GraveyardDay"
        },
        BgTransition = 2
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38846_Content_22|索菲亚，我——",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_23|闭嘴！害死我姐姐和妈妈还不够，你还要来她们坟前耀武扬威吗？！",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38846_Content_24|我是来道歉的，我没想到……",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_25|索菲亚尖刻地笑了。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_26|你也是这样和<Blue:汤普森>道歉的吗，在害死他唯一的亲人，害死<Blue:米莉>之后？\n你让我恶心，爱德华·贝利。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38846_Content_27|我是真的后悔了，索菲亚。我知道我无法获得你的宽恕——",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_28|如果你真的后悔，汤普森杀你那天你就不该去找萨尔瓦多主教。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_29|没错，我知道你是怎么活下来的，你这个懦夫。<Yellow:提灯>告诉我了。\n给你「<Yellow:赐福>」是主教最愚蠢的决定。你就该死，贝利，受尽折磨而死。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38846_Content_30|我也不想这样的，我试过控制自己，我试过的！在主教救了我之后我每天都回去圣堂报到，我每周都到你家的济贫院去做义工，你还记得吗？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38846_Content_31|我想变好，我真的想。是那个亚格罗的家伙，是他说这是个万无一失的生意，要我引荐一个担保人。我也是受害者啊！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_32|到现在你还在推卸责任，到现在……你都没有真正悔过。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_33|她从裙子的内袋里拿出了一个银白的物件，光滑的表面在阳光下微微一闪，将反射的阳光染成了不详的鲜红。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38846_Content_34|索菲亚……？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_35|忏悔吧。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_36|听从正义的持灯者的教诲，将你灵魂中的罪恶净化。\n只有这样，才可能获得宽恕。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_37|你是什么？",
        DialogType = 1,
        RolePos = {4},
        BgID = {
          "SScene_White"
        },
        BgTransition = 2
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38846_Content_38|我……我是爱德华……",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_39|镜子一闪，跪在地上的年轻人眼神再度迷茫。\n他颤抖着举起手上的棍子，重重砸到自己身上。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_40|我再问一次，你是什么？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38846_Content_41|我是罪人。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_42|你犯下了什么罪过？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38846_Content_43|我贪婪成性，我放纵欲望，我任由恶魔污染我的灵魂，然后将痛苦带给无辜之人。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_44|你应该怎么做？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38846_Content_45|我应当向我所害的人忏悔，我应当向神明忏悔。\n我应当受鞭笞之刑，应当流血直到黑色的罪恶流出，以获得<Red:净化>。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1657},
        Content = "AvgDialog_38846_Content_46|审判将至，唯有纯净的灵魂得以进入无罪的净土。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1675},
        Content = "AvgDialog_38846_Content_47|<Red:愿提灯长明>。",
        DialogType = 1,
        RolePos = {0},
        RoleHide = {1657, 1651}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_48|罪人不会改的，只要他们存在，苦难就永远不可能消失。\n只有把他们全部去除，世界才能获得安宁。",
        DialogType = 1,
        RolePos = {4},
        ScreenEffect = {"retro", 2},
        BgID = {
          "SScene_YardDay"
        },
        BgTransition = 2
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_49|……父神的造物永远留有祂的光亮，每个人都有可能被蒙蔽，同样的，每个人都可能会重新发现父神的光。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_50|我们不能因为一个人一时的行为就剥夺他的全部人生。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_51|你这样说，却完全没有想过那些为他们所害的人。在那些爱德华们找回光亮的时候，又有多少个米莉需要为此牺牲？多少个奥利维亚？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_52|罪就是罪，错就是错，一旦犯下就没有回头。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_53|她看向你们。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1651},
        Content = "AvgDialog_38846_Content_54|带我走吧，把我扔给你们腐败的法律。但记住，审判之日终将降临。\n届时，你们都将被无罪的净土驱逐。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1676},
        Content = "AvgDialog_38846_Content_55|特殊物件已经收容完毕了，守密人。受影响的平民也已经安排到各大医院中，检查无事后便能离开。",
        DialogType = 1,
        RolePos = {2},
        RoleHide = {1651, 1135},
        BgID = {
          "SScene_YardDay"
        },
        BgTransition = 1
      }),
      readonly({
        TalkRole = {1676},
        Content = "AvgDialog_38846_Content_56|官方说法是，这是一次工厂有毒气体泄漏导致的群体致幻事件，市政府明天就会公开道歉，并对相关人员做出处分。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38846_Content_57|我知道了，辛苦你们了。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1676},
        Content = "AvgDialog_38846_Content_58|这都是我们应该做的。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_59|穿着制服的年轻男子踟蹰了一下，又说：",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1676},
        Content = "AvgDialog_38846_Content_60|你是怎么做到的？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38846_Content_61|什么？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1676},
        Content = "AvgDialog_38846_Content_62|当时情况非常混乱，你却仅靠自己和一个唤醒体，就将伤亡控制到只有十数，这几乎是一个奇迹。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_63|你和奥吉尔悄悄对视一眼，小骑士双手背在身后，轻轻咳嗽了两声。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_38846_Content_64|这大概就是我和主君的默契吧。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1676},
        Content = "AvgDialog_38846_Content_65|无论如何，我仅代表审查会第一响应队向你表示感谢。\n危机之中你没有放弃我们的人，让他们得以安全回家。而且……",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        NextChatID = {"1", "2"},
        TalkRole = {1676},
        Content = "AvgDialog_38846_Content_66|我们中有不少人是在这里长大的，圣堂区对我们意义重大。\n非常感谢你所做的一切。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        ChatID = "1",
        NextChatID = {"3"},
        Content = "AvgDialog_38846_Content_67|那是我们应该做的。",
        DialogType = 5
      }),
      readonly({
        ChatID = "2",
        Content = "AvgDialog_38846_Content_68|道谢永远不嫌多。",
        DialogType = 5
      }),
      readonly({
        ChatID = "3",
        TalkRole = {1123},
        Content = "AvgDialog_38846_Content_69|索菲亚小姐……她接下来会怎么样？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1676},
        Content = "AvgDialog_38846_Content_70|审问，等我们搞清楚那个特殊物件是哪里来的之后，我们会对她进行判决。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1676},
        Content = "AvgDialog_38846_Content_71|执行异端仪式造成大范围混乱，数人死伤……主教希望她不会被判死刑，但我并不乐观。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38846_Content_72|萨尔瓦多主教。",
        DialogType = 2,
        RoleHide = {1},
        BgID = {
          "SScene_ChurchDay"
        }
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_73|你们要离开了？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38846_Content_74|是的，这次的事件非常感谢你的帮助。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_75|事情因我而起，你们还为我隐瞒身份，该是我感谢你们才是。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1123},
        Content = "AvgDialog_38846_Content_76|你真的不跟我们回去吗？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38846_Content_77|不用担心无法照顾教区，只要条件合适，我们是允许唤醒体在外自己活动的。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_78|谢谢你的好意，但，我还是更希望留在这里。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_79|萨尔瓦多转向圣坛，露出温和的笑。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_80|父神让我复生于此，想必也是希望我帮助更多的人吧。\n如果你有需要，<Yellow:苍白之火>，可以随时来找我。我一定会为你竭尽全力。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38846_Content_81|不好意思，但……请问<Yellow:苍白的使者>，还有<Yellow:苍白之火>，究竟是什么？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_82|是<Yellow:《圣典》>中父神的预言。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_83|“将有无边的黑暗降临世界，那个灵魂苍白温暖的即为希望的使者，%heorshe%将燃起白色的火焰，照亮前进的方向。”",
        DialogType = 1,
        RolePos = {2},
        BgID = {
          "SScene_LondonDaytime"
        },
        BgTransition = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_38846_Content_84|这也不一定是我吧？世上有那么多人呢。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_85|我虽蒙着双眼，却不会错认灵魂的光辉。\n你的是那样温暖，那样明亮，这么多年，我从未见过第二个。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_86|【这里看主线怎么设计，看是否需要提及提灯相关信息】",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_87|年轻的守密人转身离去，萨尔瓦多目送着那点光亮，在门轴转动之时轻声祈祷。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1135},
        Content = "AvgDialog_38846_Content_88|愿你以苍白的希望照亮黑暗。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_38846_Content_89|<Yellow:伦蒂尼恩圣堂区异常事件报告>\n\nA.F. 315 @2@3，伦蒂尼恩大圣堂区，父神济世大圣堂前广场突发暴乱。在场民众出现严重暴力行为与自残行径，无法正常沟通。\n……\n异常行为在不明光源闪烁后加剧，并演变为大范围的同类相食行为。经查，不明光源实为一把镜面纯银的手持镜。该镜通过反射阳光及月光获取能量，受到镜子反光照射的个体，将会受到内心最强的欲望的驱使，包括但不限于暴力、暴食、嗜睡等，进而做出过激行为。\n该镜子由守密人%player%及唤醒体奥吉尔回收，初步判定其中含有银芯或类银芯成分，详情请见弥萨格大学特殊用具研究部出具的研究报告。\n……\n经由密斯底亚协定审查会审问，<Blue:索菲亚·查兹坦>承认，自己于三年前加入了提灯教会，并在上一次教会活动上自教会首领提灯（即<Yellow:伊芙>女士）处获得仪式镜。\n当探员进一步询问时，索菲亚·查兹坦转而低声祈祷，不再给出任何回应。\n……",
        DialogType = 7,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        BgTransition = 5
      }),
      readonly({
        Content = "AvgDialog_38846_Content_90|夕阳驱散了空中残留的灰霾，教堂的钟敲响，河边的码头响起船只的汽笛声。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_38846_Content_91|一幢高楼的房顶，一个披着斗篷的身影背对阳光孑然独立。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1320},
        Content = "AvgDialog_38846_Content_92|即使投入了异变的罪人，也没有<Red:圣痕>出现。\n看来<Yellow:那面镜子>的价值也就这样了。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1320},
        Content = "AvgDialog_38846_Content_93|给予罪人宽恕，赐予他们「赐福」……你还真是一点都没变呢，萨尔瓦多主教。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1320},
        Content = "AvgDialog_38846_Content_94|火刑架无法改变你，死而复生也无法改变你。你要什么时候才能看清现实呢？或许——",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_38846_Content_95|她的手遥遥在空中一点，仿佛隔空触摸着什么不可见的东西。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1320},
        Content = "AvgDialog_38846_Content_96|那个有着预言中苍白而又温暖的灵魂的<Yellow:守密人>，可以带来更多的变量。你说，%heorshe%会不会愿意加入我们呢？",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_38846_Content_97|一条巨犬从女人身旁的阴影中浮现，那扭曲的肢体竟与异变的索菲亚有几分相似。听到女人的话后它打了个鼻息，似乎是在回应。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1320},
        Content = "AvgDialog_38846_Content_98|也是，明天总是新的一天。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1320},
        Content = "AvgDialog_38846_Content_99|走吧，亲爱的。有机会的话，我们还会与他们相遇的。",
        DialogType = 1
      })
    })
  },
  [58879] = {
    ID = 58879,
    CnID = "测试剧情_大型支线_莱克_关卡11_后",
    BaseSortID = 39,
    data_list = readonly({
      readonly({
        BaseSortID = 39,
        TalkRole = {1001},
        Content = "AvgDialog_58879_Content_1|就是现在，阿波菲斯！",
        DialogType = 2,
        BgID = {
          "SScene_White"
        }
      }),
      readonly({
        Content = "AvgDialog_58879_Content_2|在你的一声令下，漆黑的王蛇迅速蹿出并穿过N的身体，将祂一圈一圈缠绕起来。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_58879_Content_3|自王蛇体内涌出的黑雾与N自身的黑雾不断交融，竟逐渐使祂拥有了实体。",
        DialogType = 3,
        Audio = {
          "Play_A_MUS_Stnad_Ver4_96BPM"
        }
      }),
      readonly({
        TalkRole = {1574},
        Content = "AvgDialog_58879_Content_4|好久不见，卡纳克豢养的小宠物。你的主人现在还没消气吗？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1805},
        Content = "AvgDialog_58879_Content_5|主人对你毫无憎恨之情。他所做的，亦是被您允许的。我们只是忠实地按照剧本行事罢了。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1574},
        Content = "AvgDialog_58879_Content_6|是么……有意思。这一点甚至连我自己都没意识到。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_58879_Content_7|王蛇细长的蛇信轻轻吞吐，将低沉和缓的声音传到你们耳边。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1805},
        Content = "AvgDialog_58879_Content_8|我只能将祂在密境的投影困住一段时间。投影退散，密境即刻解除。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1805},
        Content = "AvgDialog_58879_Content_9|接下来……就交给你们了。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_58879_Content_10|莱克一步步走到N的面前。",
        DialogType = 3,
        BgID = {
          "SScene_CG_SD_S_C05_1"
        },
        BgTransition = 3
      }),
      readonly({
        TalkRole = {1125},
        Content = "AvgDialog_58879_Content_11|看来好运最后还是选择眷顾我了。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1574},
        Content = "AvgDialog_58879_Content_12|当心，侦探先生。对一个无可救药的赌徒来说，一场赌局最可怕的不是输，而是赢。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1574},
        Content = "AvgDialog_58879_Content_13|不信的话，不妨问问这条黑蛇的主人。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1125},
        Content = "AvgDialog_58879_Content_14|看来你对我还是缺乏了解，但你有一点说对了。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_58879_Content_15|莱克举起手枪，正对着N雾气涌动的面容。",
        DialogType = 3,
        BgID = {
          "CGDynamic_SD_SD_S_C05_1"
        },
        AnimState = "CG/CG_SD/Prefab/CGDynamic_SD_S_C05_1.prefab"
      }),
      readonly({
        TalkRole = {1125},
        Content = "AvgDialog_58879_Content_16|我确实是个无可救药的赌徒。无关好运与否，即使明知自己会一无所有，我也会欣然赴局。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1125},
        Content = "AvgDialog_58879_Content_17|拥有命运施舍的好运才敢下赌注，那叫正常人，不叫赌徒。你当初选中我，不也是看到了这一点吗？",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1574},
        Content = "AvgDialog_58879_Content_18|呵…哈哈哈…果然是个疯子。你沉溺于自己本能欲望的模样真是愚蠢又天真，赌徒先生。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1125},
        Content = "AvgDialog_58879_Content_19|彼此彼此。比起别的赌徒，我还有个最大的优点，那就是——",
        DialogType = 1,
        RoleHide = {1},
        BgID = {
          "SScene_CG_SD_S_C05_3"
        },
        BgTransition = 4
      }),
      readonly({
        DialogAnim = 0,
        BgID = {
          "CGDynamic_SD_SD_S_C05_2"
        },
        AnimState = "CG/CG_SD/Prefab/CGDynamic_SD_S_C05_2.prefab"
      }),
      readonly({
        TalkRole = {1125},
        Content = "AvgDialog_58879_Content_21|我愿赌服输。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_58879_Content_22|扳机轻轻扣下。",
        DialogType = 3,
        BgID = {
          "SScene_CG_SD_S_C05_5"
        },
        BgTransition = 4
      }),
      readonly({
        Content = "AvgDialog_58879_Content_23|一声枪响，N的头柔顺地倒向一旁。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_58879_Content_24|舞台碎裂，密境崩塌，王蛇亦消失无踪。",
        DialogType = 3,
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        TalkRole = {1125},
        Content = "AvgDialog_58879_Content_25|%player%，小心巨石！快跳到我身上！",
        DialogType = 1,
        BgID = {
          "SScene_OperaHouseDark"
        },
        BgTransition = 4,
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx"
      }),
      readonly({
        Content = "AvgDialog_58879_Content_26|你从善如流地跳到莱克背上，紧紧攀住祂的衣领。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_58879_Content_27|从他的肩膀望去，N脸上的空洞边缘还在缓慢蠕动。",
        DialogType = 3,
        Audio = {
          "A_MUS_Pressure_002_118BPM"
        }
