        RolePos = {0}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_58894_Content_25|谢天谢地，终于有东西肯回应我了！",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_58894_Content_26|你激动地扑向声音的来源，却发现这里只有一只小小的红色邮筒。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1801},
        Content = "AvgDialog_58894_Content_27|咕噜咕噜，消化不良，救命……救……",
