      }),
      readonly({
        TalkRole = {
          1166,
          nil,
          "serious"
        },
        Content = "AvgDialog_44437_Content_43|陷阱……",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1166,
          nil,
          "smile"
        },
        Content = "AvgDialog_44437_Content_44|还记得你之前问我的问题吗？",
