  [49399] = {
    ID = 49399,
    CnID = "测试剧情_主线_关卡7_12_前",
    BaseSortID = 57,
    data_list = readonly({
      readonly({
        BaseSortID = 57,
        Content = "AvgDialog_49399_Content_1|风暴之壁",
        Chapter = "Chapter 7;Storm Wall;Part 12",
        DialogType = 4,
        BgID = {
          "SScene_Black"
        },
        ShortAudioEffect = {
          "Play_UI_AVG_Chapter_Pop"
