      readonly({
        Content = "AvgDialog_49837_Content_6|这种恐惧与直面猎犬、对抗圣胎时都不一样……",
        DialogType = 3,
        BgID = {
          "CGDynamic_C07_006"
        },
        AudioAmbient = {
