        RoleHide = {1},
        ScreenEffect = {"sandStorm", 1},
        BgID = {
          "SScene_CG_C07_021"
        },
        BgTransition = 4
      }),
      readonly({
        Content = "AvgDialog_49400_Content_28|沙漠的宁静被一阵急促的风声所打破，天际迅速变得暗沉，仿佛一切亮色都被即将到来的怒涛吞噬。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Desert_Sand"
        }
