      readonly({
        Content = "AvgDialog_49400_Content_40|砂砾在她的周身无情地呼啸狂舞，却丝毫未能撼动她的步伐。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_CG_C07_008"
