        ShortAudioEffect = {
          "Play_A_SFX_ShatterStone"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Small_Snowstorm"
        }
      }),
      readonly({
        Content = "AvgDialog_50762_Content_11|漆黑的甬道被硬生生劈开了一道裂口，雪亮的白光洒落肩头。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1138,
