        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx"
      }),
      readonly({
        Content = "AvgDialog_60890_Content_17|一道强烈的光芒突然绽放开。在巨大的双子造物身后，出现了一道缝隙。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Sound_Lock"
