        RolePos = {
          2,
          "AvgHorizontal"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60890_Content_25|不，不能让门打开……",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_60890_Content_26|你想要做些什么。你努力催动银钥匙，但你的精神力此时被死死压制，银钥匙没有半点反应。",
