      }),
      readonly({
        TalkRole = {1821},
        Content = "AvgDialog_60890_Content_31|力量，是门内的力量……双子神像，就要完成融合。",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1821},
