  [66601] = {
    ID = 66601,
    CnID = "测试剧情_关卡9_1_后",
    BaseSortID = 93,
    data_list = readonly({
      readonly({
        BaseSortID = 93,
        TalkRole = {1122},
        Content = "AvgDialog_66601_Content_1|战斗的胜负，已经无关紧要……\n最终的赢家是我，守密人。",
        DialogType = 1,
        BgID = {
          "SScene_SchoolBlackPool"
