        BgTransition = 4,
        AudioAmbient = {
          "Play_A_SFX_Amb_Rain_Smalle"
        }
      }),
      readonly({
        Content = "AvgDialog_74778_Content_47|在阿库特睁开眼睛的那天也好，授钥仪式那天也好，决意成为门扉的守护者那天也好……",
        DialogType = 3
