        Sequence = "SetRole(1183,3);FadeDarkRole(1183,1)",
        AudioManageEvent = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        Content = "AvgDialog_74778_Content_70|那衣袍一抖，金发男人仿佛在躲避你的追随，竟加快了脚步。",
        DialogType = 3,
        Sequence = "RoleHurt(1183)"
      }),
      readonly({
