        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        ChatID = "65",
        Content = "AvgDialog_18876_Content_65|詹金不知何时跑了回来。她将水桶往地上一摔，拦在了艾继丝身前。",
