        RolePos = {0}
      }),
      readonly({
        ChatID = "29",
        TalkRole = {1189},
        Content = "AvgDialog_18859_Content_29|这就不是我能妄议的了。\n只有那位至高无上的存在，才能给予你你想要的答案。",
        DialogType = 1,
        RolePos = {2},
        Audio = {
          "Set_Avg_Mus_As_More"
