  [18853] = {
    ID = 18853,
    CnID = "主线剧情1_9_战斗前3",
    BaseSortID = 31,
    data_list = readonly({
      readonly({
        BaseSortID = 31,
        ChatID = "1",
        Content = "AvgDialog_18853_Content_1|骚乱结束，人们重新排成了队伍。\n艾继丝站在孩子们中间，面色苍白，微微颤抖。",
        DialogType = 3,
