        }
      }),
      readonly({
        ChatID = "4",
        TalkRole = {1025},
        Content = "AvgDialog_18873_Content_4|你在意的朋友，你周围的人……全都会为此付出代价。",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        ChatID = "5",
