        }
      }),
      readonly({
        ChatID = "10",
        TalkRole = {1136},
        Content = "AvgDialog_18873_Content_10|詹金，别打了！\n……我去。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        ChatID = "11",
        TalkRole = {
          1154,
