      readonly({
        TalkRole = {
          1118,
          nil,
          "surprised"
        },
        Content = "AvgDialog_18907_Content_27|艾继丝，你胳膊上的伤……",
        DialogType = 1,
        RolePos = {4},
        Sequence = "SetRole(1136,2,Nervous)"
      }),
      readonly({
        Content = "AvgDialog_18907_Content_28|艾继丝慌乱地拢起袖子，摇头躲避拉蒙娜的视线。",
        DialogType = 3,
        RoleShake = {1136},
        ShortAudioEffect = {
