        }
      }),
      readonly({
        TalkRole = {1136},
        Content = "AvgDialog_18907_Content_32|<Small:他们会有危险的，不可以……>",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "serious"
