        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Run_Two"
        },
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        TalkRole = {1154},
        Content = "AvgDialog_18908_Content_58|艾继丝！你去哪里！",
        DialogType = 1,
        RoleExit = {1154},
        ExitDirection = {"1154:2"}
      }),
      readonly({
        Content = "AvgDialog_18908_Content_59|不知何时，济贫院内起了雾气。\n这雾气突如其来，周围的一切都笼上了一层水气，显得影影绰绰的。",
        DialogType = 3,
        ScreenEffect = {"smoke", 1},
        BgID = {
          "SScene_Corridor"
        },
