        }
      }),
      readonly({
        Content = "AvgDialog_18908_Content_76|他从床上抱来做工精致的玩偶，对女孩露出微笑。",
        DialogType = 3,
        Sequence = "SetRole(1187,3)",
        ShortAudioEffect = {
