        BgTransition = 2,
        Sequence = "SetRole(1187,4);SetRole(1154,2)",
        ShortAudioEffect = {
          "Play_A_SFX_Bulang_Feedback_One"
        }
      }),
      readonly({
        TalkRole = {
          1154,
          nil,
          "angry"
        },
        Content = "AvgDialog_18908_Content_82|不、不必了！我对你们这些上流社会的艺术家不感兴趣。",
