      readonly({
        ChatID = "11",
        TalkRole = {1025},
        Content = "AvgDialog_18895_Content_12|<Italic:有一天她不见了，他到处寻找。>",
        DialogType = 6,
        ScreenEffect = {"smoke", 2},
