        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        ChatID = "2",
        Content = "AvgDialog_18887_Content_2|铁门吱呀一声被打开，一群白衣怪人鱼贯而入。\n孩子们在灰蒙蒙的雾气中排成小队，任由他们挑选。",
        DialogType = 3,
        RoleHide = {1123},
        RoleExit = {1014, 1252},
        Sequence = "SetRole(1014,2);SetRole(1252,4)",
