        RoleHide = {1},
        BgID = {
          "SScene_ClockTower"
        }
      }),
      readonly({
        ChatID = "48",
        TalkRole = {
          1123,
          nil,
          "sad"
        },
        Content = "AvgDialog_18898_Content_48|艾继丝……用她的牺牲，拯救了所有留下的人。",
        DialogType = 1,
        RolePos = {4},
        BgID = {
          "SScene_Ward"
