        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        ChatID = "50",
        TalkRole = {1001},
        Content = "AvgDialog_18898_Content_50|<Blue:肖恩·安德森调查员>……他遇害后，被雕塑家协会强行提炼了银芯，又用尽了残留的意识帮助艾继丝。",
        DialogType = 2
