        DialogType = 2
      }),
      readonly({
        ChatID = "52",
        TalkRole = {1001},
        Content = "AvgDialog_18898_Content_52|拉蒙娜，我们能拯救什么吗？我们能改变什么吗？",
        DialogType = 2
      }),
      readonly({
        ChatID = "53",
