  [18893] = {
    ID = 18893,
    CnID = "新主线剧情1_15",
    BaseSortID = 40,
    data_list = readonly({
      readonly({
        BaseSortID = 40,
        Content = "AvgDialog_18893_Content_1|波提切利之春",
        Chapter = "Chapter 1;Botticelli's Spring;Part 15",
        DialogType = 4,
        ShortAudioEffect = {
          "Play_UI_AVG_Chapter_Pop"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_18893_Content_2|13:20，伦蒂尼恩\n弥萨格大学",
        DialogType = 6,
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        NextChatID = {"1", "2"},
        Content = "AvgDialog_18893_Content_3|你和拉蒙娜刚回到校门，就看到詹金和一名穿着校服的学生在地上打成一团。",
        DialogType = 3,
        BgID = {
          "SScene_Woods"
        },
        BgTransition = 1,
        Sequence = "SetRole(1154,2);SetRole(1179,4)",
        Audio = {
          "Play_A_MUS_Fun_001_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Campus_Corner"
        }
      }),
      readonly({
        ChatID = "1",
        Content = "AvgDialog_18893_Content_4|…………",
        DialogType = 5
      }),
      readonly({
        NextChatID = {"3"},
        TalkRole = {1001},
        Content = "AvgDialog_18893_Content_5|…………",
        DialogType = 2,
        Audio = {
          "Play_A_MUS_Fun_001_118BPM"
        }
      }),
      readonly({
        ChatID = "2",
        Content = "AvgDialog_18893_Content_6|老鼠咬雪貂",
        DialogType = 5
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_18893_Content_7|我好像看到了什么世界奇观。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1154,
          nil,
          "scared"
        },
        Content = "AvgDialog_18893_Content_8|哈？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18893_Content_9|什么奇观？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_18893_Content_10|老鼠袭击雪貂。",
        DialogType = 2,
        ShortAudioEffect = {
          "Play_A_SFX_Ops"
        }
      }),
      readonly({
        TalkRole = {
          1154,
          nil,
          "angry"
        },
        Content = "AvgDialog_18893_Content_11|你说谁是老鼠啊！",
        DialogType = 1,
        RolePos = {2},
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Emm"
        }
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18893_Content_12|你说谁是雪貂啊！",
        DialogType = 1,
        RolePos = {4},
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Emm"
        }
      }),
      readonly({
        ChatID = "3",
        TalkRole = {1118},
        Content = "AvgDialog_18893_Content_13|汉娜？詹金？你们这是……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1154,
          nil,
          "angry"
        },
        Content = "AvgDialog_18893_Content_14|这可不能怪我，是她先喊警卫的！",
        DialogType = 1,
        RolePos = {2},
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_OMG"
        }
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18893_Content_15|哎呀，开个玩笑嘛。过得太认真，生活没趣味。",
        DialogType = 1,
        RolePos = {4},
        Audio = {
          "Set_Avg_Mus_As_More"
        }
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18893_Content_16|所以她来找的人就是你们了吧？你们是在哪儿认识的，莉莉安济贫院？啊！她就是那个小詹金吧？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {
          1118,
          "UI_Story_D_Image_Face_Sweat.png"
        },
        Content = "AvgDialog_18893_Content_17|不愧是雷欧王国第一雪貂。你这是在为校报搜罗明天的素材吗？",
        DialogType = 2,
        ShortAudioEffect = {
          "Play_A_SFX_PullOut"
        }
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18893_Content_18|那可不止，拉蒙娜你是知道我的，信息就是我的生命啊。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18893_Content_19|那么，光天化日之下，可怜的孤女独自前往深林冒险，究竟所为何事？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18893_Content_20|她苦苦寻觅之人，又能否给予她些许光明？\n前线记者汉娜·皮斯利，即将进行跟踪报道！",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_18893_Content_21|汉娜一边说着，一边啪地从不知道哪里摸出一本笔记本，期待地看着你们，像是随时准备记录你们的一言一行。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_OpenTheBook"
        }
      }),
      readonly({
        TalkRole = {1154},
        Content = "AvgDialog_18893_Content_22|……我算是明白了，你们这个什么鬼大学的，一个二个都不说人话。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {
          1001,
          "UI_Story_D_Image_Face_Speechless.png"
        },
        Content = "AvgDialog_18893_Content_23|我是无辜的，真的。",
        DialogType = 2,
        ShortAudioEffect = {
          "Play_A_SFX_OMG"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "smile"
        },
        Content = "AvgDialog_18893_Content_24|当她不在就好。\n倒是你，詹金，出什么事儿了吗？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_18893_Content_25|詹金从包里翻出一叠折得皱巴巴的报纸，递到你和拉蒙娜面前。",
        DialogType = 3,
        RoleHide = {1},
        Sequence = "ShowItem(9602)",
        ShortAudioEffect = {
          "Play_A_SFX_OpenTheBook_02"
        },
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        TalkRole = {1154},
        Content = "AvgDialog_18893_Content_26|之前我们约好了，你要帮我找姐姐的。现在，是你兑现承诺的时候了。",
        DialogType = 1,
        RolePos = {2},
        Sequence = "SetRole(1118,4)"
      }),
      readonly({
        Content = "AvgDialog_18893_Content_27|她将报纸展开，指向一篇题为《立体的画作》的本地奇闻。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18893_Content_28|笔者以纪实故事的风格写道，他在南华克大街44号的蜡像馆看到过一件惊人的展品：蜡像艺术家罗杰斯的新作《春》。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_WaxDoor"
        },
        BgTransition = 2,
        Audio = {
          "Play_A_MUS_Thinking_004_118BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_18893_Content_29|似乎是为了提高可信度，旁边还煞有介事地配了一张照片。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_18893_Content_30|这是仿照波提切利的名画《春》制成的蜡像群组，位于正中间的，是一座涂着滑稽颜料、表情痛苦的女性蜡像。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1154},
        Content = "AvgDialog_18893_Content_31|这个人……不知道为什么，我觉得她很像我的姐姐。",
        DialogType = 1,
        RolePos = {2},
        BgID = {
          "SScene_Woods"
        },
        BgTransition = 2,
        Sequence = "SetRole(1118,4)",
        ShortAudioEffect = {
          "Play_A_SFX_Recover_Remember"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "serious"
        },
        Content = "AvgDialog_18893_Content_32|罗杰斯……那个米勒医生，就是他介绍给莎拉的。济贫院出事后，他就神秘失踪了。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {
          1154,
          nil,
          "sad"
        },
        Content = "AvgDialog_18893_Content_33|所以，就是这家伙害死了我姐姐……和……艾继丝……",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1154},
        Content = "AvgDialog_18893_Content_34|我一刻都等不了。我们什么时候出发？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1118},
        Content = "AvgDialog_18893_Content_35|考虑到对方可能很危险，我更希望你愿意在这里等我们的消息。不过——你一定有别的想法吧。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1154},
        Content = "AvgDialog_18893_Content_36|那是我姐姐，我不可能不去！\n再说了，指不定你们什么时候就要我帮忙钻通风口呢！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {
          1001,
          "UI_Story_D_Image_Face_Sweat.png"
        },
        Content = "AvgDialog_18893_Content_37|这唯一的技能可真是相当有用。",
        DialogType = 2,
        ShortAudioEffect = {
          "Play_A_SFX_Emm"
        }
      }),
      readonly({
        TalkRole = {1118},
        Content = "AvgDialog_18893_Content_38|看来得提交加急外勤申请了。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_18893_Content_39|我正准备去找阿利斯泰尔教授，希望他乐意给我们开后门。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Smile"
        },
        Content = "AvgDialog_18893_Content_40|只要你开口，肯定没问题。更重要的是——我们需要威廉先暂缓我们的报告提交时间。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18893_Content_41|关于这点，你们倒是不用担心。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_18893_Content_42|？",
        DialogType = 2,
        ShortAudioEffect = {
          "Play_A_SFX_OMG"
        }
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18893_Content_43|就在一个小时前吧，威廉拿着外勤许可离开了学校。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1179},
        Content = "AvgDialog_18893_Content_44|我本来想跟踪他，看看能不能挖到什么新闻，结果在路上跟丢了，这才走回来。看方向，好像是往伦蒂尼恩西区去了。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Smile"
        },
        Content = "AvgDialog_18893_Content_45|南华克大街就在西区。\n看来这次，我们可以亲眼见证名牌调查员威廉的风采了。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_18893_Content_46|他都出动了吗……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_18893_Content_47|18:24，伦蒂尼恩西区\n南华克大街",
        DialogType = 6,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        BgTransition = 4,
        ShortAudioEffect = {
          "Play_A_SFX_Amb_Mist"
        },
        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_18893_Content_48|感谢几位的配合，接下来我一个人就行了。",
        DialogType = 1,
        RolePos = {3},
        BgID = {
          "SScene_WaxDoor"
        },
        BgTransition = 1,
        Audio = {
          "Play_A_Mus_Strange_Chp2_Ver2_118BPM",
          "1200"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Mist"
        }
      }),
      readonly({
        TalkRole = {1073},
        Content = "AvgDialog_18893_Content_49|这不行，先生，上头的命令很明确，要我们陪同你进行调查。\n再说了，罗杰斯也是我们的嫌疑人，可不能让你一个人辛苦。",
        DialogType = 2,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {1074},
        Content = "AvgDialog_18893_Content_50|而且，有我们在，你的身份才能更好地隐藏，不是吗？",
        DialogType = 2,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_18893_Content_51|……",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        TalkRole = {1073},
        Content = "AvgDialog_18893_Content_52|放心吧先生，我们有枪，跑得也快，不会拖你后腿的。",
        DialogType = 2,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_18893_Content_53|好吧，请务必提高警戒。必要的时候，以自己的生命为优先。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_18893_Content_54|汇报。抵达任务地点，南华克街44号，罗杰斯蜡像馆。目标确认：确认蜡像馆主人罗杰斯与雕塑家协会的可能联系。",
        DialogType = 1,
        RolePos = {3},
        ShortAudioEffect = {
          "Play_A_SFX_No_Signal"
        }
      }),
      readonly({
        TalkRole = {1155},
        Content = "AvgDialog_18893_Content_55|任务地点抵达确认，调查目标确认。\n愿银钥指引前路。",
        DialogType = 1,
        RolePos = {
          1,
          "AvgVertical"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Brooches_Comfirm"
        }
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_18893_Content_56|愿银钥指引我们。",
        DialogType = 1,
        RolePos = {3},
        RoleHide = {1155},
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [18938] = {
    ID = 18938,
    CnID = "主线剧情_关卡2_1_前",
    BaseSortID = 1,
    data_list = readonly({
      readonly({
        BaseSortID = 1,
        ChatID = "1",
        Content = "AvgDialog_18938_Content_1|伽拉忒亚",
        Chapter = "Chapter02;Galatea;Part 1",
        DialogType = 4,
        BgID = {
          "SScene_Black"
        },
        ShortAudioEffect = {
          "Play_UI_AVG_Chapter_Pop"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        ChatID = "2",
        Content = "AvgDialog_18938_Content_2|洪积295年夏\n斯卡伯勒，北约克郡",
        DialogType = 6,
        Audio = {
          "Play_A_MUS_Undergound_Main_104BPM"
        }
      }),
      readonly({
        ChatID = "3",
        TalkRole = {1194},
        Content = "AvgDialog_18938_Content_3|这是我最钟爱的艺术品——伽拉忒亚。",
        DialogType = 1,
        RolePos = {4},
        PlayEnterAnim = 1,
        BgID = {
          "SScene_WaxUnderground"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Important_People"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Private_Room"
        }
      }),
      readonly({
        ChatID = "4",
        TalkRole = {1194},
        Content = "AvgDialog_18938_Content_4|听说过<Blue:皮格马利翁>的故事吧？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        ChatID = "5",
        TalkRole = {1194},
        Content = "AvgDialog_18938_Content_5|他用象牙雕刻了一座美丽的少女像，像对待妻子那样爱抚她、装扮她……",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        ChatID = "6",
        TalkRole = {1194},
        Content = "AvgDialog_18938_Content_6|并将全部的热情与爱恋都献给了她。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        ChatID = "7",
        TalkRole = {1194},
        Content = "AvgDialog_18938_Content_7|“伽拉忒亚”——这就是那个少女的名字。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        ChatID = "8",
        TalkRole = {1194},
        Content = "AvgDialog_18938_Content_8|抱歉，我不小心说了太多，你一定感到厌烦了。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        ChatID = "9",
        TalkRole = {1038},
        Content = "AvgDialog_18938_Content_9|没、没有的事，先生。求您了，先生……",
        DialogType = 2
      }),
      readonly({
        ChatID = "10",
        TalkRole = {1038},
        Content = "AvgDialog_18938_Content_10|我的父母都是体面的有钱人，他们会给你钱的……",
        DialogType = 2
