        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Peace_Two_Guys_Mid"
        },
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        ChatID = "A2",
        Content = "AvgDialog_18944_Content_51|不是",
        DialogType = 5
      }),
      readonly({
        ChatID = "A2_TO",
        TalkRole = {
          1129,
          nil,
          "shy"
        },
        Content = "AvgDialog_18944_Content_52|没关系，没关系。\n人家啊，最喜欢调教不听话的客人了~",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1129,
          nil,
          "Dream"
        },
        Content = "AvgDialog_18944_Content_53|只要交到我手上，不出三日，保证你们会变得像小绵羊一样，乖巧又可爱。",
        DialogType = 1,
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        ChatID = "CH1_END",
        Content = "AvgDialog_18944_Content_54|少女将你们带到陈列室入口，双手叉腰摆起了管理员的架势。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Two_Guys_Slow"
        }
      }),
      readonly({
        ChatID = "59",
        TalkRole = {
          1129,
          nil,
          "smile"
        },
        Content = "AvgDialog_18944_Content_55|听好了哦，小甜心们。\n这里有三条规则是一定、绝对、千万不能打破的哦~",
        DialogType = 1,
        Audio = {
          "Play_A_Mus_Strange_Chp2_Ver2_118BPM",
          "1000"
