      readonly({
        ChatID = "29",
        TalkRole = {1154},
        Content = "AvgDialog_18960_Content_29|第三……",
        DialogType = 1
      }),
      readonly({
        ChatID = "30",
        TalkRole = {
          1154,
          nil,
          "shy1"
        },
        Content = "AvgDialog_18960_Content_30|这次我给你们添了不少麻烦，姐姐还替我挨了鞭子。",
        DialogType = 1
      }),
      readonly({
