        ShortAudioEffect = {
          "Play_A_SFX_Fall_Down"
        },
        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        TalkRole = {1004},
        Content = "AvgDialog_19019_Content_41|该死的家伙，又是你！滚开！滚开！",
        DialogType = 1,
        RolePos = {4},
        RoleShake = {0}
      }),
      readonly({
