        DialogType = 1,
        RolePos = {4},
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Show_Sash"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_19019_Content_58|莉莉，你在哪里看到的丽莎？",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_19019_Content_59|莉莉只是摇头。",
