    BaseSortID = 21,
    data_list = readonly({
      readonly({
        BaseSortID = 21,
        Content = "AvgDialog_19016_Content_1|芒刺在背",
        Chapter = "Chapter 3;Thorn in My Side;Part 6",
        DialogType = 4,
        BgID = {
