      }),
      readonly({
        TalkRole = {1043},
        Content = "AvgDialog_19016_Content_88|这是……",
        DialogType = 1,
        RolePos = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Show_Something"
        }
      }),
      readonly({
        Content = "AvgDialog_19016_Content_89|从冰冷的塞西莉的怀中，掉出一个油纸布包裹。你轻轻打开，里面放着一份做了标记的地图，一张黑白照片，和一撮淡金色的头发。",
        DialogType = 3,
        ShortAudioEffect = {
