        RolePos = {4}
      }),
      readonly({
        ChatID = "15",
        TalkRole = {1138},
        Content = "AvgDialog_19973_Content_15|她需要回到“<Yellow:主人>”的身边去，所以我来带她走。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        ChatID = "16",
        Content = "AvgDialog_19973_Content_16|拉蒙娜点了点头，然后转身摸了摸莉莉的脑袋。",
