      }),
      readonly({
        ChatID = "21",
        Content = "AvgDialog_19973_Content_21|莉莉的手紧了紧。\n随后，她缓慢但坚决地摇了摇头。",
        DialogType = 3,
        Sequence = "SetRole(1130,4,sad)"
