        ShortAudioEffect = {
          "Play_A_SFX_Fall_Down"
        }
      }),
      readonly({
        ChatID = "4",
        Content = "AvgDialog_18994_Content_4|啪，啪，啪。\n漆黑的隧道中，唐突响起清脆的击掌声。",
        DialogType = 3,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_OnePerson_applaud"
        }
      }),
      readonly({
        ChatID = "5",
        Content = "AvgDialog_18994_Content_5|伴随颇具节奏感的掌声的，是略带赞许笑意的暧昧女声。灰雾缠绕的裙摆从光影边界处逐渐勾勒出轮廓，周围霎时笼罩上淡淡的紫罗兰烟香。",
        DialogType = 3,
