        }
      }),
      readonly({
        ChatID = "6",
        TalkRole = {
          1147,
          nil,
          "Smile1"
        },
        Content = "AvgDialog_18994_Content_6|感谢各位带来的精彩演出，我看大家都已经疲惫不堪了，不妨暂时休战？",
        DialogType = 1,
        RolePos = {4},
        PlayEnterAnim = 1,
