        TalkRole = {
          1147,
          nil,
          "Smile1"
        },
        Content = "AvgDialog_18994_Content_23|不知道这边这位女士，是否做出决定了呢？",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        ChatID = "24",
        Content = "AvgDialog_18994_Content_24|希洛梗了梗脖子，黏液在她的掌心凝成尖刺。",
