        TalkRole = {
          1147,
          nil,
          "Smile2"
        },
        Content = "AvgDialog_18994_Content_35|这么心急吗？可惜，价格早已标定，达芙黛尔的解忧小铺，可没有讨价还价的余地。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
