        TalkRole = {1120},
        Content = "AvgDialog_19079_Content_3|赫伯特，你还没放弃你那荒谬的追求吗？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        ChatID = "4",
        TalkRole = {1180},
        Content = "AvgDialog_19079_Content_4|如果你具备区分荒谬和伟大的能力，或许就会修改你的措辞。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
