        TalkRole = {
          1120,
          nil,
          "smile"
        },
        Content = "AvgDialog_19079_Content_23|呵？束手无策。\n你可看好了，我这替代了人类双手的，到底是什么东西。",
        DialogType = 1,
        RolePos = {2}
      }),
