      }),
      readonly({
        ChatID = "10",
        TalkRole = {
          1124,
          nil,
          "angry"
        },
        Content = "AvgDialog_19046_Content_10|所以你想要向背叛者复仇，想保护搭救你的弗朗西斯。\n但战斗不该是这样的东西。",
        DialogType = 1
