        AudioTalk = {
          "Play_A_SFX_Tinnitus"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Heart_Beat",
          "1000"
        }
      }),
      readonly({
        Content = "AvgDialog_19041_Content_14|你眼前一片模糊的红。",
