        BgID = {
          "SScene_Blood2"
        },
        BgTransition = 2,
        ShortAudioEffect = {
          "Play_A_SFX_Splash_Blood"
        }
      }),
      readonly({
        Content = "AvgDialog_19041_Content_15|血红色的视野中，你听见达芙黛尔诱惑的声线在耳畔响起。",
        DialogType = 3
      }),
      readonly({
