  [19063] = {
    ID = 19063,
    CnID = "主线剧情_关卡4_14_后",
    BaseSortID = 42,
    data_list = readonly({
      readonly({
        BaseSortID = 42,
        ChatID = "1",
        Content = "AvgDialog_19063_Content_1|你们与地狱犬鏖战多时，这场战斗却不似想象中艰难。",
