        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        ChatID = "6",
        TalkRole = {1001},
        Content = "AvgDialog_19063_Content_6|守密人%player%，准备回收唤醒体莉莉、改造体库姆，申请收容相关嫌疑人弗朗西斯·奥斯伍德……",
        DialogType = 2
      }),
      readonly({
        ChatID = "7",
        TalkRole = {1155},
        Content = "AvgDialog_19063_Content_7|……录入……嗞啦……地狱……",
        DialogType = 1,
        RolePos = {0},
        ShortAudioEffect = {
          "Play_A_SFX_No_Signal"
        }
      }),
      readonly({
        ChatID = "8",
        Content = "AvgDialog_19063_Content_8|通讯另一端，艾瑞卡的声音模糊不清。",
