        DialogType = 2,
        ShortAudioEffect = {
          "Play_A_SFX_OMG"
        }
      }),
      readonly({
        TalkRole = {1199},
        Content = "AvgDialog_19082_Content_48|诶！你别乱摸。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_19082_Content_49|墨菲递给你一罐药膏。",
