  [19107] = {
    ID = 19107,
    CnID = "主线剧情_5_3_战斗后1",
    BaseSortID = 7,
    data_list = readonly({
      readonly({
        BaseSortID = 7,
        TalkRole = {1001},
        Content = "AvgDialog_19107_Content_1|这个码头也太大了。",
        DialogType = 2,
        BgID = {
          "SScene_Dock"
        },
        Audio = {
          "Play_A_MUS_Pre_Fight_118BPM"
