  [19139] = {
    ID = 19139,
    CnID = "主线剧情_5_5_战斗前2",
    BaseSortID = 17,
    data_list = readonly({
      readonly({
        BaseSortID = 17,
        ChatID = "1",
        Content = "AvgDialog_19139_Content_1|壮硕高大的男人丝毫不压制怒火，他踢开匍匐脚边的蹈海者，拔起深插在甲板上的巨刃，语气不善。",
