        AudioTalk = {
          "Play_A_SFX_xing"
        },
        ShortAudioEffect = {
          "Play_A_SFX_AVG_LightOpen_02"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "surprised"
        },
        Content = "AvgDialog_19118_Content_8|这道光……和组成密境边界的光幕是一样的！",
        DialogType = 1,
        RolePos = {2},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Show_Sash"
        }
      }),
      readonly({
        TalkRole = {1159},
