      readonly({
        ChatID = "13",
        TalkRole = {1001},
        Content = "AvgDialog_19104_Content_13|遵命，遵命。",
        DialogType = 2
      }),
      readonly({
        ChatID = "14",
        TalkRole = {1001},
        Content = "AvgDialog_19104_Content_14|我们在船头侧楼梯下方……墨菲，你觉得其他人会在哪里？船尾楼里的驾驶舱吗？",
        DialogType = 2,
        RoleHide = {1199},
