        ShortAudioEffect = {
          "Play_A_SFX_Show_Paper"
        }
      }),
      readonly({
        ChatID = "15",
        TalkRole = {1199},
        Content = "AvgDialog_19104_Content_15|我哪知道！不过想去驾驶舱的话得从甲板上走，要不就得穿过动力室。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
