        AudioAmbient = {
          "Play_A_SFX_Amb_HeresyHappy"
        }
      }),
      readonly({
        Content = "AvgDialog_19083_Content_28|弥利亚姆双目轻阖，松开与少女紧握的双手，转身面向陷入狂热的教众。",
        DialogType = 3,
        Sequence = "SetRole(1168,3)"
      }),
      readonly({
        Content = "AvgDialog_19083_Content_29|她双臂高举，黑液顺着肌肤纹理滑落，头纱瞬间被染成浓重的黑色。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_GetUp"
        }
      }),
      readonly({
        Content = "AvgDialog_19083_Content_30|祷言此起彼伏，最终在寒冷的洞窟中调律重合，狂热，扭曲，震耳欲聋。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "EyeOpen"
        },
        Content = "AvgDialog_19083_Content_31|神母已至！",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1110},
        Content = "AvgDialog_19083_Content_32|祂将从@1中复苏，使@2降临！",
        DialogType = 2,
        Sequence = "ShakeDialog"
      }),
      readonly({
        TalkRole = {1109},
        Content = "AvgDialog_19083_Content_33|祂将从@1中复苏，使@2降临！",
