      }),
      readonly({
        ChatID = "9",
        TalkRole = {
          1168,
          nil,
          "EyeOpen"
        },
        Content = "AvgDialog_19129_Content_9|你是那所大学的人。\n如此的年幼……你还是学徒，对么？",
        DialogType = 1,
        RolePos = {2},
        Sequence = "SetRole(1118,4,serious)",
