      }),
      readonly({
        ChatID = "12",
        TalkRole = {
          1118,
          nil,
          "serious"
        },
        Content = "AvgDialog_19129_Content_12|灯芯，提灯……难不成，<Blue:“灯芯”>指代了提灯教会中，某些地位特殊的人？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        ChatID = "13",
        TalkRole = {1166},
        Content = "AvgDialog_19129_Content_13|蹈海者的外形难以行走世间，而他们想要我们的力量……怪人的相互利用，抱团取暖罢了。",
        DialogType = 1,
