        Content = "AvgDialog_23854_Content_28|@2…咕呜……",
        DialogType = 1,
        RolePos = {0},
        ShortAudioEffect = {
          "Play_A_SFX_AVG_Sea_Monster_Fight_01"
        }
      }),
      readonly({
