    data_list = readonly({
      readonly({
        BaseSortID = 17,
        TalkRole = {1199},
        Content = "AvgDialog_23862_Content_1|可恶的家伙，可恶可恶可恶！",
        DialogType = 1,
        RoleShake = {0},
        BgID = {
          "SScene_ShipCornerLogo"
        },
        Audio = {
