    BaseSortID = 23,
    data_list = readonly({
      readonly({
        BaseSortID = 23,
        Content = "AvgDialog_23849_Content_1|舱门被推开一道缝隙，绚烂的光争先恐后涌入昏暗的船舱。",
        DialogType = 3,
        BgID = {
          "SScene_DeckIllusion"
        },
        BgTransition = 2,
