  [23845] = {
    ID = 23845,
    CnID = "新主线剧情_关卡5_8_战斗前1",
    BaseSortID = 24,
    data_list = readonly({
      readonly({
        BaseSortID = 24,
        Content = "AvgDialog_23845_Content_1|你们蹑手蹑脚地一路穿越甲板，墨菲抿着嘴指了指不远处的桥楼，示意机械室就在那里面。",
        DialogType = 3,
        BgID = {
          "SScene_DeckIllusion"
        },
        Sequence = "SetRole(1199,3,serious2)",
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Two_Guys_Slow"
        },
        Audio = {
          "Play_A_MUS_Phantom_Strange_Chp5_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Light"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_23845_Content_2|只要能引开门口蹈海者的注意，你们就能无声无息地潜进楼里……",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_23845_Content_3|你了然地点点头，正在口袋里摸索着能被扔出去的杂物时，沉重的脚步由远及近地传来。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Bad_Misty"
        },
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        Content = "AvgDialog_23845_Content_4|墨菲倒吸一口冷气，满脸惊惧。她左右环视了一圈，最后猛地掀开了货箱上的防水布，手脚并用地爬进了箱子里。",
        DialogType = 3,
        RoleExit = {1199},
        ExitDirection = {"1199:1"},
        Sequence = "SetRole(1199,3,scared)",
        AudioTalk = {
          "Play_A_SFX_AVG_WoodenDrop",
          "500"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Turn_Jump"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_23845_Content_5|<Small:墨菲？>",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_23845_Content_6|箱子不再有任何回音和动静，像静寂的黑洞般吞噬了墨菲。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1159},
        Content = "AvgDialog_23845_Content_7|噤声，那边有人来了。",
        DialogType = 1,
        RolePos = {
          2,
          "AvgHorizontal"
        }
      }),
      readonly({
        Content = "AvgDialog_23845_Content_8|用古老语言唤走蹈海者守卫的，无疑是个巨人。\n你们的角度无法看见正身，但其映在甲板上影子格外巨大。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_23845_Content_9|巨大到，仿佛足以踏平山川、吞食日月——",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_23845_Content_10|巨刃被从远处粗暴地投向你们，力量之大撕破了空气，带起了猛烈的冲击波。",
        DialogType = 3,
        BgTransition = 2,
        ShortAudioEffect = {
          "Play_A_SFX_AVG_Broadsword_Whoosh"
        },
        Audio = {
          "Play_A_MUS_Geliya_Fight_Chp5_118BPM"
        }
      }),
      readonly({
        TalkRole = {
          1159,
          nil,
          "angry"
        },
        Content = "AvgDialog_23845_Content_11|小心！",
        DialogType = 1,
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Hit_Jump_Shock"
        }
      }),
      readonly({
        Content = "AvgDialog_23845_Content_12|坚实的触肢卷住你的腰，一把把你拽离了巨刃落点。",
        DialogType = 3,
        RoleHide = {1},
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        AudioTalk = {
          "Play_A_SFX_AVG_TentacleImpact"
        },
        ShortAudioEffect = {
          "Play_A_SFX_AVG_Broadsword_Impact",
          "400"
        }
      }),
      readonly({
        TalkRole = {1159},
        Content = "AvgDialog_23845_Content_13|蹈海者大多身体羸弱，擅使轻兵。这把巨剑另有主人，小心应对。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1104},
        Content = "AvgDialog_23845_Content_14|身体羸弱…我同意你对这些家伙的看法。",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {1104},
        Content = "AvgDialog_23845_Content_15|但作为战争前锋，缺乏自我意识的家伙可是不能再好用了。",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        Content = "AvgDialog_23845_Content_16|壮硕高大的男人拖着长长的尾鳍，踢开匍匐脚边的蹈海者，迈着沉重的步子走向你们。",
        DialogType = 3,
        Sequence = "SetRole(1104,3);FadeDarkRole(1104,1)",
        AudioTalk = {
          "Play_A_SFX_Be_Hit_Normal",
          "400"
        },
        ShortAudioEffect = {
          "Play_A_SFX_AVG_Sea_Monster_Fight_01"
        }
      }),
      readonly({
        Content = "AvgDialog_23845_Content_17|他拔起深插在甲板上的巨刃，语气嘲弄，投向你的眼神充满了审视和兴致。",
        DialogType = 3,
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_AVG_Broadsword_WhooshImpact"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_23845_Content_18|地位高于蹈海者的唤醒体……难道这家伙也是弥利亚姆的同伙？！",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1104},
        Content = "AvgDialog_23845_Content_19|“弥利亚姆的同伙”？啧，真难听。",
        DialogType = 1,
        Sequence = "FadeDarkRole(1104,1)"
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_23845_Content_20|吾名戈利亚。\n记住了，这是踏破诸海之人的名讳！",
        DialogType = 1,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [23851] = {
    ID = 23851,
    CnID = "新主线剧情_关卡5_8_后",
    BaseSortID = 25,
    data_list = readonly({
      readonly({
        BaseSortID = 25,
        TalkRole = {1001},
        Content = "AvgDialog_23851_Content_1|好惊人的力量……！就算以唤醒体的标准来看都堪称恐怖。",
        DialogType = 2,
        BgID = {
          "SScene_DeckIllusion"
        },
        Sequence = "SetRole(1166,2,smile)",
        Audio = {
          "Play_A_MUS_Geliya_Fight_Chp5_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Light"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        TalkRole = {1159},
        Content = "AvgDialog_23851_Content_2|这力量……",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1159},
        Content = "AvgDialog_23851_Content_3|弥利亚姆将她被赐予的力量，分给了你。",
        DialogType = 1,
        RolePos = {4},
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        TalkRole = {
          1166,
          nil,
          "serious"
        },
        Content = "AvgDialog_23851_Content_4|哦？你这小矮子怎么会……",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_23851_Content_5|图鲁的迟疑甫一显露，巨人也若有所思地停止了攻击。\n他眯着眼睛上下打量图鲁，视线最后停留在了那顶夸张的王冠上。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1166,
          nil,
          "Surprised"
        },
        Content = "AvgDialog_23851_Content_6|这个冠冕的形制是……！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_23851_Content_7|戈利亚瞳孔紧缩，用赤裸而尖锐的目光盯着你们，最后竟肆无忌惮地放声大笑了起来。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_23851_Content_8|哈，哈哈哈哈！有意思，太有意思了！",
        DialogType = 1,
        RolePos = {2},
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_GetUp"
        }
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_23851_Content_9|要是叫那女人看到这场面，她会露出什么样的表情呢——不会直接发疯吧？哈哈哈哈，我太期待那个时刻了！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_23851_Content_10|狂笑在密境空间回荡，气氛变得更加剑拔弩张。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1166,
          nil,
          "smile"
        },
        Content = "AvgDialog_23851_Content_11|别这么紧张，我不打算在这里解决掉你们。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {
          1166,
          nil,
          "smile"
        },
        Content = "AvgDialog_23851_Content_12|提灯教会那些废物，连点守备的活都做不好，居然让这小矮子溜了进来……不过也多亏了他们的无能，现在这场仪式可变得更精彩了。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_23851_Content_13|提灯教会……蹈海者和提灯教会竟然是一伙人？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1166,
          nil,
          "smile"
        },
        Content = "AvgDialog_23851_Content_14|哈？别把我和那群疯子相提并论。蹈海者的外形难以行走世间，而他们想要我们的力量……怪人的相互利用，抱团取暖罢了。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_23851_Content_15|不仅和提灯教会有牵连，而且你口中的<Blue:仪式>……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_23851_Content_16|戈利亚……你究竟是什么人？",
        DialogType = 2,
        Audio = {
          "Play_A_MUS_Thinking_003_118BPM"
        }
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_23851_Content_17|我是什么人？哈哈哈哈哈！为什么不问问你身边那家伙呢？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_23851_Content_18|我，还有这些蹈海者从何而来——您不会猜不到吧？毕竟您可是至高无上的……",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {
          1159,
          nil,
          "angry"
        },
        Content = "AvgDialog_23851_Content_19|僭越！",
        DialogType = 1,
        RolePos = {4},
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Hit_Jump_Shock"
        }
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_23851_Content_20|真吓人真吓人——但可惜，我可不是你那些忠心耿耿的臣子。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_23851_Content_21|我还得继续为仪式做准备，没空和你们继续纠缠不清。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_23851_Content_22|尽管夹着触手东躲西藏吧，但你知道的——那个女人想要的东西，只有你能给。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {
          1166,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_23851_Content_23|分去那无能之神力量的代行者……唔！",
        DialogType = 1,
        RolePos = {2},
        ShortAudioEffect = {
          "Play_A_SFX_Twist_Muscle"
        }
      }),
      readonly({
        Content = "AvgDialog_23851_Content_24|嘲弄之言话音未落，紫色虚影突然从横贯戈利亚脖子的伤痕中逸出。它像纱巾般盘踞围绕在颈间，最后竟凝结成了蛇形。",
        DialogType = 3,
        RoleHide = {1},
        ScreenEffect = {"redScreen", 1},
        BgID = {
          "SScene_Black"
        },
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_AVG_BigSnakeSteam_01"
        },
        Audio = {
          "Play_A_MUS_Very_Hard_Ver2_124BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_23851_Content_25|戈利亚因蛇影的出现而脸色扭曲，那蛇毒牙竟将利齿钉入了颈间的断痕。",
        DialogType = 3,
        ScreenEffect = {"redScreen", 2},
        BgID = {
          "SScene_Blood2"
