        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        TalkRole = {1199},
        Content = "AvgDialog_23842_Content_2|当时和他约好的敲门暗号是什么来着……三轻一重？轻轻重轻？",
        DialogType = 1,
