      readonly({
        Content = "AvgDialog_23842_Content_5|图鲁眼疾手快地扶住了门不让它关上，他和你对视一眼，你们同时闪身进了门中。",
        DialogType = 3,
        Sequence = "SetRole(1159,3)",
