        Audio = {
          "Play_A_MUS_Mofei_Fun_Ver2_Chp5_110BPM",
          "800"
        }
      }),
      readonly({
        Content = "AvgDialog_23842_Content_7|皮肤黝黑，身着船员服饰的中年男人拍了拍墨菲的头表示关心。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Caress"
        },
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        TalkRole = {
          1112,
          nil,
          "Smlie"
        },
        Content = "AvgDialog_23842_Content_8|说到做到可是成年人必须遵守的事。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1112},
        Content = "AvgDialog_23842_Content_9|说起来，这两位是？",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {
          1199,
          nil,
          "serious2"
        },
        Content = "AvgDialog_23842_Content_10|这个带着王冠的臭脸小子叫图鲁，而旁边这个人的名字是……",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {
          1199,
          nil,
          "surprised"
        },
        Content = "AvgDialog_23842_Content_11|……",
        DialogType = 1,
        RolePos = {2},
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_OMG"
        }
      }),
      readonly({
        TalkRole = {
          1199,
          nil,
          "shy"
        },
        Content = "AvgDialog_23842_Content_12|我、我是不是没有问过你的名字……",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_23842_Content_13|墨菲不好意思地挠挠头，躲到了船长身后，把这不合时宜的社交活动扔给了唯一的成年人。",
        DialogType = 3,
        Sequence = "SetRole(1199,3,serious2)",
        ShortAudioEffect = {
          "Play_A_SFX_GetUp"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_23842_Content_14|我是%player%，是弥萨格大学的学生。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_23842_Content_15|您就是船长吧？我校有记录，曾有一名本校前辈登上过索纳尼尔号。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_23842_Content_16|船长从腰包中掏出烟盒，刚捻起最后一撮烟叶，墨菲就轻轻拍在了他的手上。",
        DialogType = 3,
        RoleShake = {1199},
        ShortAudioEffect = {
          "Play_A_SFX_Show_Wallet"
        }
      }),
      readonly({
        TalkRole = {1199},
        Content = "AvgDialog_23842_Content_17|不是答应过我以后再也不抽烟了吗。",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        Content = "AvgDialog_23842_Content_18|船长无奈地笑着，收起了烟盒。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Show_Sash"
        }
      }),
      readonly({
        TalkRole = {1112},
        Content = "AvgDialog_23842_Content_19|我记得你这身校服。可惜了，现在不是个好时机。\n如果换作其他日子登船，我还能给你倒杯酒好好聊聊天。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        TalkRole = {1201},
        Content = "AvgDialog_23842_Content_20|埃尔顿，我的名字是埃尔顿。",
        DialogType = 1,
        RolePos = {3},
        RoleHide = {1199, 1112}
      }),
      readonly({
        Content = "AvgDialog_23842_Content_21|在你们自我介绍时，墨菲自己在昏暗舱室里转了一圈。等她再次出现在你们视线中时，满脸都是疑惑。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Normal_Short"
        }
      }),
      readonly({
        TalkRole = {
          1199,
          nil,
          "serious2"
        },
        Content = "AvgDialog_23842_Content_22|船长，希莱斯特不在你身边吗？",
        DialogType = 1,
        RolePos = {2},
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
