        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
      }),
      readonly({
        Content = "AvgDialog_24081_Content_8|埃尔顿露出一个苦笑，他又习惯性地想去摸烟盒。但刚拿到那冰冷的小铝盒，他的手就猛地抖了一下，盒子摔在地上，洒了满地烟叶。",
        DialogType = 1,
