  [24083] = {
    ID = 24083,
    CnID = "新主线剧情_关卡5_12_剧情节点1",
    BaseSortID = 33,
    data_list = readonly({
      readonly({
        BaseSortID = 33,
        Content = "AvgDialog_24083_Content_1|在希莱斯特的指引下，两人在迷宫般的舱室间穿行。\n不多时，她们拐入了一个昏暗的舱室。",
        DialogType = 3,
        BgID = {
          "SScene_ShipCornerLogo"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Two_Guys_Slow"
        },
        Audio = {
          "Play_A_MUS_Thinking_002_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Cabin"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_24083_Content_2|沉重的脚步声穿透上方甲板，每一步都如同命运之神落下的铁锤，在灵魂上敲出阵阵难以忍受的恐惧。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Playaround"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "serious"
        },
        Content = "AvgDialog_24083_Content_3|<Small:好沉重的脚步声……希莱斯特，你知道这声音是谁发出的吗？>",
        DialogType = 1,
        RolePos = {
          1,
          "AvgHorizontal"
        }
      }),
      readonly({
        Content = "AvgDialog_24083_Content_4|希莱斯特摇了摇头，那张脸上不再能看出任何情绪。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "serious"
        },
        Content = "AvgDialog_24083_Content_5|<Small:难道是蹈海者派来追击我们的人吗……希望守密人不要和脚步主人产生正面冲突，我不在身边，%heorshe%单打独斗，很可能不是对方的对手……>",
        DialogType = 1,
        RolePos = {
          1,
          "AvgHorizontal"
        }
      }),
      readonly({
        TalkRole = {1170},
        Content = "AvgDialog_24083_Content_6|……来了。",
        DialogType = 1,
        RolePos = {
          2,
          "AvgHorizontal"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "surprised"
        },
        Content = "AvgDialog_24083_Content_7|什么？",
        DialogType = 1,
        RolePos = {
          1,
          "AvgHorizontal"
        }
      }),
      readonly({
        Content = "AvgDialog_24083_Content_8|希莱斯特话音未落，急促的脚步就在本层甲板响起。由远及近，最终停在了她们藏身的舱室外。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Run_Mid"
        }
      }),
      readonly({
        Content = "AvgDialog_24083_Content_9|拉蒙娜示意希莱斯特不要有动作，自己则握紧武器，藏身在了门后。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Zhanjin_Fight_Sence_04"
        }
      }),
      readonly({
        Content = "AvgDialog_24083_Content_10|舱室沉重的门被推开，琥珀色的光线投进舱室。她紧绷的神经，也因瞥到的那片披风而陡然松弛了下来。",
        DialogType = 3,
        BgTransition = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Iron_Door_Open_01"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "smile"
        },
        Content = "AvgDialog_24083_Content_11|守密人。",
        DialogType = 1,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [24080] = {
    ID = 24080,
    CnID = "新主线剧情_关卡5_12_剧情节点2",
    BaseSortID = 34,
    data_list = readonly({
      readonly({
        BaseSortID = 34,
        Content = "AvgDialog_24080_Content_1|你摇摇头，竖起食指抵在嘴唇上，示意她暂时保持安静。但在视线扫过阴影中的人时，反而是你差点没忍住惊呼出声。",
        DialogType = 3,
        BgID = {
          "SScene_ShipCornerLogo"
        },
        Sequence = "SetRole(1170,4);SetRole(1118,2)",
        ShortAudioEffect = {
          "Play_A_SFX_Show_Sash"
        },
        Audio = {
          "Play_A_MUS_Strange_002_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Cabin"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        TalkRole = {1118},
        Content = "AvgDialog_24080_Content_2|<Small:她是希莱斯特，是一名唤醒体……>",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_24080_Content_3|你在索纳尼尔号上，曾数次在幻影中见过她——这个熟悉又陌生的影子，居然就是控制着密境的希莱斯特。",
        DialogType = 3,
        RoleHide = {1118},
        Sequence = "SetRole(1170,3)"
      }),
      readonly({
        Content = "AvgDialog_24080_Content_4|本该被弥利亚姆控制着的关键人物，居然和拉蒙娜一同逃了出来——意外至极，却又在意料之中。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_24080_Content_5|毕竟你的搭档，从来都不是坐以待毙的人。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "surprised"
        },
        Content = "AvgDialog_24080_Content_6|<Small:……等、等等？这是档案编号-6291的唤醒体图鲁？！>",
        DialogType = 1,
        RolePos = {3},
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Hit_Jump_Shock"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_24080_Content_7|<Small:我们先去与船长和墨菲会合，到时我一点点和你解释发生了什么。>",
        DialogType = 2,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [24078] = {
    ID = 24078,
    CnID = "新主线剧情_关卡5_12_后",
    BaseSortID = 35,
    data_list = readonly({
      readonly({
        BaseSortID = 35,
        Content = "AvgDialog_24078_Content_1|腐败的腥臭逐渐飘入鼻腔。",
        DialogType = 3,
        BgID = {
          "SScene_Cabin"
        },
        ShortAudioEffect = {
          "Play_A_SFX_AVG_Sea_Monster_Fight_01"
        },
        Audio = {
          "Play_A_MUS_Very_Hurry_124BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Cabin"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_24078_Content_2|蹈海者们受到首领的召唤，从四面八方的舱室鱼贯而出。\n而为首追击你们的，正是那让你尤为忌惮的巨人。",
        DialogType = 3,
        Sequence = "SetRole(1166,3,smile)",
        ShortAudioEffect = {
          "Play_A_SFX_AVG_Sea_Monster_FightVo_01"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_SeaMonster"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "serious"
        },
        Content = "AvgDialog_24078_Content_3|好难缠的敌人……！",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_24078_Content_4|别和他纠缠！图鲁，掩护我们离开！",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_24078_Content_5|你拉着拉蒙娜逃离了战斗，不顾一切地想要跑向舱室之外。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Run_Short"
        }
      }),
      readonly({
        Content = "AvgDialog_24078_Content_6|戈利亚战斗的方式一如既往地直接，他好整以暇地露出笑容，对着你们逃离的方向投出了巨刃。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_AVG_Broadsword_Whoosh"
        }
      }),
      readonly({
        TalkRole = {1159},
        Content = "AvgDialog_24078_Content_7|小心！",
        DialogType = 2,
        RoleHide = {1},
        BgTransition = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Hit_Jump_Shock"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Cabin"
        }
      }),
      readonly({
        Content = "AvgDialog_24078_Content_8|你猛地将拉蒙娜往前一推，巨刃却扎穿了小腿，将你整个人都钉在了地上，别在胸前的通讯器也随之掉落。",
        DialogType = 3,
        RoleHide = {1},
        ScreenEffect = {"redScreen", 1},
        AnimState = "UI_Story_Panel_AvgDialogBg_doudong_vx",
        AudioTalk = {
          "Play_A_SFX_Splash_Blood",
          "300"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Be_Hit_Normal",
          "Play_A_SFX_AVG_Broadsword_Impact"
        },
        Audio = {
          "Play_A_MUS_Geliya_Fight_Chp5_118BPM"
        }
      }),
      readonly({
        Content = "AvgDialog_24078_Content_9|剧痛让你眼前一阵发白，脑中响起了蜂鸣般的噪音，甚至盖过了拉蒙娜的惊叫。",
        DialogType = 3,
        RoleHide = {1},
        ScreenEffect = {"redScreen", 2},
        BgTransition = 2,
        ShortAudioEffect = {
          "Play_A_SFX_Big_Memory_Confusion"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_NO_Thinking"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_24078_Content_10|唔……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_24078_Content_11|弥萨格大学的调查员，加上窃取了利莫里亚神力的唤醒体……只有这点本事？",
        DialogType = 1,
        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        Content = "AvgDialog_24078_Content_12|图鲁闪身挡在你身前，而拉蒙娜冷汗涔涔地跪在你身边，试图拔出戈利亚的巨刃。",
        DialogType = 3,
        RoleHide = {1166},
        Sequence = "SetRole(1159,2);SetRole(1118,4,threat)",
        ShortAudioEffect = {
          "Play_A_SFX_Show_Something"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_24078_Content_13|图鲁，带她们走。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "angry"
        },
        Content = "AvgDialog_24078_Content_14|你在说什么傻话？！",
        DialogType = 1,
        RolePos = {4},
        RoleShake = {0}
      }),
      readonly({
        Content = "AvgDialog_24078_Content_15|拉蒙娜越发用力地去拔戈利亚的武器，利刃划破了手套，暗红的血液瞬间洇透了她的袖口。",
        DialogType = 3,
        BgTransition = 2,
        AudioTalk = {
          "Play_A_SFX_WaterDrop",
          "300"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Turn_Jump"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_24078_Content_16|我不会有事。弥利亚姆不是想要留人喂养将要出生的神明吗？保护好希莱斯特和墨菲，阻止仪式……我会想办法逃出来。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_24078_Content_17|你的大脑一片空白，木然地编着连自己都无法说服的理由。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1159},
        Content = "AvgDialog_24078_Content_18|你……",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_24078_Content_19|保护他们离开！",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1159},
        Content = "AvgDialog_24078_Content_20|……",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_24078_Content_21|图鲁不再争辩，最后看了你一眼，似乎是在确认你的决心。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "angry"
        },
        Content = "AvgDialog_24078_Content_22|图鲁！快放我下来！",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_24078_Content_23|两只强壮的触手分别缠住拉蒙娜和希莱斯特，转眼间，图鲁已经绑着两人冲进了走廊深处。",
        DialogType = 3,
        RoleExit = {1159, 1118},
        ExitDirection = {"1159:1", "1118:1"},
        ShortAudioEffect = {
          "Play_A_SFX_Something_Flash"
        }
      }),
      readonly({
        Content = "AvgDialog_24078_Content_24|戈利亚狂笑着拔出了武器，在你身前蹲下，掐着你的下巴迫使你直视他。",
        DialogType = 3,
        PlayEnterAnim = 1,
        Sequence = "SetRole(1166,3)",
        ShortAudioEffect = {
          "Play_A_SFX_AVG_Broadsword_WhooshImpact"
        }
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_24078_Content_25|我说过吧：在我看够好戏前，可别被什么杂兵打败了。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_24078_Content_26|他的语气半是嘲弄半是认真，让人根本捉摸不透他的真实用意。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1166},
        Content = "AvgDialog_24078_Content_27|不过你倒是个有胆识的家伙。\n可惜了，这一次弥利亚姆可是指定了要拿人回去交差。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_24078_Content_28|只是简单的玩弄吗？还是戈利亚真的，对弥利亚姆有异心……",
        DialogType = 3,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
