        AudioAmbient = {
          "Play_A_SFX_Amb_Snake"
        }
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "null"
        },
        Content = "AvgDialog_24091_Content_32|现在……还有回圜的余地。\n回到教团，你依旧是尊贵的「神母」。",
        DialogType = 1,
        RolePos = {0},
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "null"
        },
        Content = "AvgDialog_24091_Content_33|你的葬礼将成为神国历史上最盛大的祭典，受万人敬仰……你的名字亦将载于史书，流传万古。",
        DialogType = 1,
