        BgID = {
          "CGDynamic_C00M_02WhiteOut"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Stop_Running"
        }
      }),
      readonly({
        Content = "AvgDialog_34974_Content_5|希莱斯特喘息着放下罗盘，她在船长的搀扶下坐了下来，双手交叠着搭在腿上，看起来比之前更加虚弱。",
        DialogType = 3,
        RoleHide = {1118},
        BgID = {
          "SScene_ShipCornerLogo"
        },
