        }
      }),
      readonly({
        TalkRole = {
          1201,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_34974_Content_35|唔……！",
        DialogType = 1,
        RolePos = {
          2,
          "AvgHorizontal"
        },
        RoleShake = {0},
        BgID = {
          "SScene_White"
        },
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
