      readonly({
        TalkRole = {
          1118,
          nil,
          "angry"
        },
        Content = "AvgDialog_34968_Content_100|什么人！",
        DialogType = 1,
        RolePos = {3}
      }),
      readonly({
        Content = "AvgDialog_34968_Content_101|偷听者举着骨质长矛匆匆离开，拉蒙娜追上去，只看见一个黑袍身影消失在走廊尽头。",
