        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_35533_Content_10|我还是我吗？",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_35533_Content_11|我……是谁？",
