        RolePos = {0},
        BgID = {
          "SScene_Black"
        },
        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Surprised"
        },
        Content = "AvgDialog_35533_Content_23|守密人，守密人！你听得见我的声音吗？",
        DialogType = 1,
