        Audio = {
          "Play_A_Mus_Peace_Talk_Ver2_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Cabin"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_35533_Content_24|……我这是怎么了？",
        DialogType = 2,
        ScreenEffect = {
          "awake",
          1,
          1
        },
        BgID = {
          "SScene_CoralCabin"
        },
        Sequence = "SetRole(1118,3,serious)"
      }),
      readonly({
        Content = "AvgDialog_35533_Content_25|你在拉蒙娜的搀扶下坐了起来，环视四周，发现自己身处货舱中，被融蚀赘生物和你的同伴包围着。",
        DialogType = 3,
