  [35531] = {
    ID = 35531,
    CnID = "主线剧情_关卡6_11_战斗后1",
    BaseSortID = 30,
    data_list = readonly({
      readonly({
        BaseSortID = 30,
        Content = "AvgDialog_35531_Content_1|你和拉蒙娜一路绕行，终于行至动力室另一侧门前。",
        DialogType = 3,
        BgID = {
          "SScene_Black"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Two_Guys_Slow"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_PowerRoom"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_35531_Content_2|这扇门在你们与弥利亚姆的战斗中受到波及，门板彻底变了形，摇摇欲坠地挂在门框上。你们没费什么力就挤了进来。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_GetUp",
