  [35824] = {
    ID = 35824,
    CnID = "主线剧情_关卡6_12_前",
    BaseSortID = 33,
    data_list = readonly({
      readonly({
        BaseSortID = 33,
        Content = "AvgDialog_35824_Content_1|前路迷途",
        Chapter = "Chapter 6;Wandering Path;Part 12",
        DialogType = 4,
        BgID = {
          "SScene_Black"
        },
        ShortAudioEffect = {
          "Play_UI_AVG_Chapter_Pop"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        Content = "AvgDialog_35824_Content_2|弥利亚姆站在一片废墟之上，双足被翘起的铁片划伤，暗色鲜血直流。",
        DialogType = 3,
        BgID = {
          "SScene_EngineRoomPostbattle"
