  [35831] = {
    ID = 35831,
    CnID = "主线剧情_关卡6_12_战斗后1",
    BaseSortID = 35,
    data_list = readonly({
      readonly({
        BaseSortID = 35,
        TalkRole = {1107},
        Content = "AvgDialog_35831_Content_1|污浊@2……咕呜！",
        DialogType = 2,
        BgID = {
          "SScene_EngineRoomPostbattle"
        },
        ShortAudioEffect = {
