      }),
      readonly({
        TalkRole = {1201},
        Content = "AvgDialog_35830_Content_10|我的船就停在码头，不如到我的船上取取暖吧。",
        DialogType = 1,
        RolePos = {4}
      }),
      readonly({
        Content = "AvgDialog_35830_Content_11|凯刻斯凝滞在原地，半晌，他才僵硬地开口。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Stop_Running"
