        Content = "AvgDialog_35826_Content_42|墨菲？！",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
