        TalkRole = {1001},
        Content = "AvgDialog_35828_Content_60|可是墨菲她——",
        DialogType = 2,
        BgID = {
          "CGDynamic_C01_012"
        }
      }),
      readonly({
        TalkRole = {1199},
        Content = "AvgDialog_35828_Content_61|一个两个…都这幅样子……一群自说自话的家伙。",
        DialogType = 1,
        RolePos = {0},
        RoleHide = {1},
        ScreenEffect = {"smoke", 1},
