      }),
      readonly({
        TalkRole = {1199},
        Content = "AvgDialog_35828_Content_62|没有人向我征询过哪怕一次意见……哼。\n用你们的牺牲换来幸存……我说过我想要了吗？",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
