        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        Content = "AvgDialog_35828_Content_70|光芒瞬间迸发，竟硬生生将你弹出了精神世界。",
        DialogType = 3,
        BgID = {
          "SScene_White"
        }
      }),
      readonly({
        Content = "AvgDialog_35828_Content_71|过于耀眼的光芒刺痛了双眼，让人无法自控地流下了泪水。",
        DialogType = 3
      }),
      readonly({
        DialogType = 3,
        Sequence = "PlayVideo(C06/Video_C06_06.mp4)"
      }),
      readonly({
        Content = "AvgDialog_35828_Content_73|浑浊的液体流尽，双眼终于得以再次聚焦于少女。",
        DialogType = 3,
        BgID = {
          "SScene_CG_C06_010"
        }
      }),
      readonly({
        Content = "AvgDialog_35828_Content_74|刀身深埋进胸口，沐浴着月光的少女睁开了眼。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_35828_Content_75|象征着死亡的满月近在咫尺，年轻的脸庞上却无半分恐惧之意。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1199},
        Content = "AvgDialog_35828_Content_76|做到了……我做到了。",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {1199},
        Content = "AvgDialog_35828_Content_77|我……刺穿了……祂不会出生了……",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {1199},
        Content = "AvgDialog_35828_Content_78|这样一来……",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        Content = "AvgDialog_35828_Content_79|紧握刀柄的手无力垂下，鲜红的、粘稠的、深黑的液体从刀口涌出，顺着指间淌入大海。",
        DialogType = 3,
        BgID = {
          "CGDynamic_C06_03"
        }
      }),
      readonly({
        Content = "AvgDialog_35828_Content_80|血液快速从身躯里流失，墨菲肤色苍白无比，浑身却散发着一股异样的生命力。",
        DialogType = 3,
        BgID = {
