        Sequence = "PlayVideo(C06/Video_C06_07.mp4)",
        ShortAudioEffect = {
          "Play_A_SFX_Video_C06_07"
        }
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "crazy"
        },
        Content = "AvgDialog_35828_Content_82|不……不、不不<Big:不不><BigShake:啊啊啊——>",
        DialogType = 1,
        RolePos = {0},
        BgID = {
          "SScene_CG_C06_018"
        }
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "crazy"
        },
        Content = "AvgDialog_35828_Content_83|全能的神，宽恕我，宽恕这个孩子，宽恕您虔诚的信者……",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        TalkRole = {
          1168,
          nil,
          "crazy"
        },
        Content = "AvgDialog_35828_Content_84|正位之时，正位之时将至，将至……",
        DialogType = 1,
        RolePos = {0}
      }),
      readonly({
        DialogType = 3,
        Sequence = "PlayVideo(C06/Video_C06_08.mp4)",
