          "Play_A_Mus_Cult_Reburn_Hard_118BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_GODBABY",
          "900"
        }
      }),
      readonly({
        Content = "AvgDialog_35828_Content_86|「胎盘」碎裂，「心脏」也随之崩溃——无数双手破体而出，胸腔被挤得粉碎。",
        DialogType = 3,
        BgID = {
          "SScene_CG_C06_011"
