      readonly({
        TalkRole = {1759},
        Content = "AvgDialog_45437_Content_5|为使者大人献礼！",
        DialogType = 2,
        RolePos = {0},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx"
      }),
      readonly({
        Content = "AvgDialog_45437_Content_6|队伍的最后，泰旖丝悠游地坐在棺椁之上，由四位亚兰战士抬入。",
        DialogType = 3,
        RoleHide = {
          1759,
