  [45422] = {
    ID = 45422,
    CnID = "主线剧情_关卡7_9_剧情节点2",
    BaseSortID = 20,
    data_list = readonly({
      readonly({
        BaseSortID = 20,
        TalkRole = {
          1118,
          nil,
          "serious"
        },
        Content = "AvgDialog_45422_Content_1|有点麻烦。我们并不知道遗骸所在。\n工厂内通道复杂，隔间众多，一间间搜不知要搜到什么时候。",
        DialogType = 1,
        RolePos = {2},
        BgID = {
          "SScene_AbandonedFactories"
