        Content = "AvgDialog_45414_Content_9|喂，你这家伙——",
        DialogType = 1,
        RolePos = {4},
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
      }),
      readonly({
        TalkRole = {
          1753,
          nil,
          "Flustered"
        },
        Content = "AvgDialog_45414_Content_10|遗骸、遗骸就在前面的暗室里！",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_45414_Content_11|同一时间-废弃工厂管道",
