      readonly({
        TalkRole = {1125},
        Content = "AvgDialog_45435_Content_56|<Yellow:圣树遗骸的污染>？看来那位达芙黛尔卖给雕塑家协会的消息，比我们还要多些啊。",
        DialogType = 1,
