      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_45418_Content_59|拉蒙娜，你的身体状况不适合和我们一起。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_45418_Content_60|你掖上她的被角。\n被热浪侵袭的少女颤巍巍地瞪你一眼，没有说话。",
        DialogType = 3,
        Sequence = "SetRole(1118,3,serious)",
        ShortAudioEffect = {
