    CnID = "主线剧情_关卡7_12_后",
    BaseSortID = 30,
    data_list = readonly({
      readonly({
        BaseSortID = 30,
        Content = "AvgDialog_45415_Content_1|风暴愈怒，亚兰士兵哭嚎着，狂乱着，大声呼喊着，祈求着，诅咒着。",
