      readonly({
        TalkRole = {
          1125,
          nil,
          "smile"
        },
        Content = "AvgDialog_45430_Content_8|天天听这帮亚兰人念叨丰穰母树，不知道实际上是怎样壮美的景象。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_45430_Content_9|莱克你……在说什么啊……",
