        RolePos = {
          2,
          "AvgHorizontal"
        },
        RoleShake = {0},
        ShortAudioEffect = {
          "Play_A_SFX_Ops"
        }
      }),
      readonly({
        Content = "AvgDialog_45430_Content_14|你抬头望向天际，伸出手掌，描摹母树的轮廓。",
        DialogType = 3,
        RoleHide = {1125},
        ShortAudioEffect = {
          "Play_A_SFX_Lightly_Clothes_Rub_02"
