      readonly({
        TalkRole = {
          1118,
          nil,
          "serious"
        },
        Content = "AvgDialog_45430_Content_29|对某人似乎不起作用。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_45430_Content_30|……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_45430_Content_31|不管你们信不信，这感觉可不太舒服……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_45430_Content_32|似乎在不知不觉间，过去已被篡改，故事就此偏离了既定的轨道。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_45430_Content_33|而你却成为了这些变化的唯一见证者。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_45430_Content_34|身为欲之质体的载体，丰穰母树的存在一定在星球上刻下了足够深刻的烙印。",
        DialogType = 1,
        ScreenEffect = {"retro", 2},
        BgID = {
          "SScene_DesertDay"
