        RoleHide = {1},
        BgID = {
          "CGDynamic_C01_012"
        },
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        TalkRole = {
          1125,
          nil,
          "smile"
        },
        Content = "AvgDialog_45430_Content_44|明天就是亚兰仪式了，你们还不休息吗？",
        DialogType = 1,
        RolePos = {2},
        BgID = {
          "SScene_InTent"
        },
        BgTransition = 6,
        Sequence = "SetRole(1183,4)",
        ShortAudioEffect = {
