        ShortAudioEffect = {
          "Play_A_SFX_Brooches_Shine"
        }
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_45430_Content_61|我早该……早该想到的。",
        DialogType = 1,
        RolePos = {
