        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {
          1156,
          nil,
          "Smile1"
        },
        Content = "AvgDialog_45429_Content_4|哼哼，猜猜守密人在哪顶帽子里？",
        DialogType = 1,
        BgID = {
          "SScene_InTent"
        }
      }),
      readonly({
        TalkRole = {
          1156,
          nil,
          "Smile3"
        },
        Content = "AvgDialog_45429_Content_5|左边也是空的，右边也是空的~",
