        ShortAudioEffect = {
          "Play_A_SFX_Satin_Skill_02"
        }
      }),
      readonly({
        TalkRole = {1156},
        Content = "AvgDialog_45429_Content_8|怎么样，是不是很有亚兰风情的演出呀？",
        DialogType = 1,
        RolePos = {
          2,
          "AvgHorizontal"
        },
        ScreenEffect = {"redScreen", 2}
      }),
      readonly({
        TalkRole = {
          1156,
          nil,
          "smile3"
        },
        Content = "AvgDialog_45429_Content_9|隔空取物~嘿嘿，到我收货的时候啦。",
        DialogType = 1,
        RolePos = {
          2,
          "AvgHorizontal"
        },
        BgID = {
          "SScene_InTent"
        }
      }),
      readonly({
        Content = "AvgDialog_45429_Content_10|她爽快地揭开巨大的魔术帽，出现其中的是她意料之外的身影。",
        DialogType = 3,
        RoleHide = {1156},
        BgTransition = 2,
