        ShortAudioEffect = {
          "Play_A_SFX_Show_Sash"
        }
      }),
      readonly({
        TalkRole = {
          1156,
          nil,
          "Angry"
        },
        Content = "AvgDialog_45429_Content_11|怎么是你？！",
        DialogType = 2,
        RolePos = {0},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_OMG"
        }
      }),
      readonly({
