          "Play_A_SFX_Amb_White_Ocean"
        }
      }),
      readonly({
        Content = "AvgDialog_45443_Content_24|泰旖丝慌乱地蹦回棺椁上，仪态端方，俨然王座上倨傲的女王。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1134},
        Content = "AvgDialog_45443_Content_25|尊敬的客人哟……",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_45443_Content_26|<Red:她装腔拿调的声音被来者干脆地打断>。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_45443_Content_27|艾尔瓦当然不会「打断」女王的宣言。",
        DialogType = 7,
        RoleHide = {1},
        ScreenEffect = {"retro", 2},
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        TalkRole = {1758},
        Content = "AvgDialog_45443_Content_28|使者！是使者的队伍回来了！",
        DialogType = 1,
        RolePos = {2},
