        ShortAudioEffect = {
          "Play_A_SFX_BabyCry_Multiple_01"
        }
      }),
      readonly({
        Content = "AvgDialog_45442_Content_114|他们的表皮变得松弛，仿佛瘫软的泥浆；他们的体液抽离肉体，汇成圣河湍急的流水。",
        DialogType = 3,
        Audio = {
          "Play_A_MUS_Tideng_Deep_Crisis_110BPM_Coda"
        }
      }),
      readonly({
        Content = "AvgDialog_45442_Content_115|他们的骨骼像是皮肉般软化，肢体以非人的方式扭曲、延展、缠绕，用自身的血肉，构成圣树庞大臃肿的茎枝。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_45442_Content_116|他们缓慢而痛苦地，与圣树融为一体。",
        DialogType = 6,
        ScreenEffect = {"disturb", 2},
        BgID = {
          "SScene_Black"
        },
        Sequence = "SlowCaption",
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
  [45436] = {
    ID = 45436,
    CnID = "主线剧情_关卡7_18_前",
    BaseSortID = 40,
    data_list = readonly({
      readonly({
        BaseSortID = 40,
