      }),
      readonly({
        TalkRole = {1686},
        Content = "AvgDialog_45438_Content_3|亚兰人以畸形之人的淋漓鲜血为代价换取种群的繁衍，你们的存在本身就是污秽和罪恶。",
        DialogType = 1
