        DialogType = 1
      }),
      readonly({
        TalkRole = {1686},
        Content = "AvgDialog_45438_Content_5|而最珍贵的孩子，已经在我的囊中，成为去往新世界的适格者。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_45438_Content_6|艾尔瓦面前，一只人面犬匍匐于地。",
        DialogType = 3,
        RoleHide = {1},
        ShortAudioEffect = {
          "Play_A_SFX_HumanFaced_DogRoaring_B"
        }
      }),
      readonly({
        TalkRole = {1686},
        Content = "AvgDialog_45438_Content_7|真乖，不愧是我选中的孩子。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1131,
          nil,
          "sad"
        },
        Content = "AvgDialog_45438_Content_8|涅弗……鲁瑞……",
        DialogType = 2
