        ScreenEffect = {
          "keyWorkEffect",
          1
        },
        ShortAudioEffect = {
          "Play_A_SFX_Brooches_Launch"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60203_Content_33|你们做得很好。接下来的事情，我会带你们一起完成。",
        DialogType = 2,
        ScreenEffect = {
          "keyWorkEffect",
          2
        }
      }),
      readonly({
        Content = "AvgDialog_60203_Content_34|你抬起头，望向克莱门汀，以及她身边茫茫的审查会探员。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1822},
        Content = "AvgDialog_60203_Content_35|守密人%sirormadam%，你不是小孩子了，请你考虑清楚。我们是官方人员，搜查弥萨格，这可是官方的命令。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60203_Content_36|未经允许闯入弥萨格，伤害弥萨格的人员……我没有看到官方，只看到一群强盗。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60203_Content_37|我不管你们真实目的是什么。对待强盗，弥萨格只有一种态度。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_60203_Content_38|开始反击",
        DialogType = 5
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60203_Content_39|唤醒体，列队，迎敌！",
        DialogType = 2,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
