          "Play_A_SFX_Bulang_Feedback_Two"
        }
      }),
      readonly({
        TalkRole = {1196},
        Content = "AvgDialog_60208_Content_49|吱吱——吱吱——",
        DialogType = 2,
        ShortAudioEffect = {
          "Play_A_SFX_Bulang_Feedback_Three"
        }
      }),
      readonly({
