  [60212] = {
    ID = 60212,
    CnID = "主线剧情_关卡8_4_前",
    BaseSortID = 8,
    data_list = readonly({
      readonly({
        BaseSortID = 8,
        Content = "AvgDialog_60212_Content_1|排练",
        Chapter = "Chapter 8;Rehearsal;Part 4",
        DialogType = 4,
        BgID = {
          "SScene_Black"
        },
        ShortAudioEffect = {
          "Play_UI_AVG_Chapter_Pop"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        }
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60212_Content_2|到了。",
        DialogType = 1,
        BgID = {
          "SScene_MusicRoom"
        },
        Audio = {
          "Play_A_MUS_AfterWarVer2_58BPM",
          "300"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Mist",
          "300"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_3|音乐教室？这个地方安全？",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60212_Content_4|从功能性上来说，这里靠近审查会的搜查区域，并不算安全。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_5|嗯，我明白了……最危险的地方就是最安全的地方。很不错的思路。",
        DialogType = 2,
        Audio = {
          "Play_A_MUS_Soft_Thinking_118BPM"
        }
      }),
      readonly({
        TalkRole = {
          1796,
          nil,
          "ShutEye"
        },
        Content = "AvgDialog_60212_Content_6|你想多了。来这里，是因为我喜欢待在有乐器的地方。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_7|……既然都已经选择了帮我，其实可以顺着说说话的。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_8|哈姆林，我听说过你，当今世上首屈一指的指挥家，最近正在伦蒂尼恩巡演。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_9|弥萨格和审查会都曾经对你做过一些调查。没人想到，你会是一个唤醒体。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60212_Content_10|没有想到，弥萨格和审查会会对我感兴趣。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_11|我们在调查里发现，你的巡演轨迹和提灯教会的活动轨迹高度重合。",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_60212_Content_12|你警惕地看着面前这个唤醒体。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_13|你救下了我和唤醒体，对此我很感激。但现在弥萨格正陷入危机，希望你能原谅我的防备。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_14|路上我询问过，你是如何进入弥萨格的，来这里有什么目的。现在，你可以回答我了。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60212_Content_15|你的唤醒体安顿好了吗？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_16|……我让大部分唤醒体赶去了黑池附近。身边只留下了这几个。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60212_Content_17|链接恢复得如何？",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_18|……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_19|靠你乐声的帮助，我和这些唤醒体之间的链接恢复了过来。",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60212_Content_20|你的情况特殊，我只能做到让你维持少量唤醒体的链接。这样应该也足够了。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_60212_Content_21|他轻轻提起指挥棒。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60212_Content_22|现在，向我进攻。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_60212_Content_23|？？？",
        DialogType = 5
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_24|你说什么？",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Shit"
        }
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60212_Content_25|我的雷欧语发音应该没有什么问题。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60212_Content_26|我听见了，我的意思是……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60212_Content_27|来音乐教室的另一个目的，是因为这里有大量的乐器。这些乐器之间的共鸣，能让我的能力得到更好的发挥。",
        DialogType = 1
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60212_Content_28|不想进攻，防守也可以。做好准备。",
        DialogType = 1
      }),
      readonly({
        Content = "AvgDialog_60212_Content_29|还没等你明白过来是什么情况，哈姆林的指挥棒熟练地向下一点。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_60212_Content_30|一声清脆的弦乐，在音乐教室与你的脑海中同时响起。",
        DialogType = 3,
        Audio = {
          "Play_A_MUS_Hamulin_Orch_Rehearsal_84BPM"
        }
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60212_Content_31|演奏开始。",
        DialogType = 1,
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      })
    })
  },
