        DialogType = 2
      }),
      readonly({
        TalkRole = {1817},
        Content = "AvgDialog_60347_Content_12|这么冷的天气，趴在黑池里，可是会生病的。",
        DialogType = 1,
        Sequence = "FadeDarkRole(1817,1)"
      }),
      readonly({
        Content = "AvgDialog_60347_Content_13|德克斯特教授？",
