        DialogType = 3,
        Sequence = "FadeDarkRole(1817,2)"
      }),
      readonly({
        Content = "AvgDialog_60347_Content_16|打理精致的双手杵着手杖，来到你的身前。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Footstep_Water_One_Walking_Slowly_01"
