      readonly({
        TalkRole = {
          1182,
          nil,
          "Smile"
        },
        Content = "AvgDialog_60347_Content_38|现在……",
        DialogType = 1
      }),
      readonly({
        TalkRole = {
          1182,
          nil,
          "Smile"
        },
        Content = "AvgDialog_60347_Content_39|我亲爱的观众，请为我献上，最热烈的掌声。",
        DialogType = 1,
        BgID = {
          "CGDynamic_C01_012"
