        Content = "AvgDialog_60349_Content_4|！！！",
        DialogType = 2,
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        ShortAudioEffect = {
          "Play_A_SFX_Hit_Jump_Shock"
        }
      }),
      readonly({
        Content = "AvgDialog_60349_Content_5|没等你反应过来，地上的身体化为一阵黑雾消失在原地。",
        DialogType = 3,
        BgID = {
          "SScene_OperaHouseDark"
        },
