        ShortAudioEffect = {
          "Play_A_SFX_Brooches_Shine"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Floodlight"
        }
      }),
      readonly({
        Content = "AvgDialog_60356_Content_16|准备进攻！",
        DialogType = 5
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60356_Content_17|唤醒体，准备……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60356_Content_18|第四乐章，停止。",
        DialogType = 1,
        ShortAudioEffect = {
          "Play_A_SFX_Hamulin_Attack_Perc"
        }
      }),
      readonly({
        Content = "AvgDialog_60356_Content_19|熟悉的嗓音。清冷，坚定，不容拒绝。\n指挥棒在你身后轻轻点下，如同在剧院的舞台上那般稳定优雅。",
        DialogType = 3,
        ScreenEffect = {
          "keyWorkEffect",
          2
        },
        Audio = {
          "Stop_Avg_Mus"
        },
        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        Content = "AvgDialog_60356_Content_20|在这指令之下，那维系你精神稳定的乐声消失了，取而代之的，是一阵刺耳嘈杂的尖锐噪音。",
        DialogType = 3,
        RoleHide = {1},
        ScreenEffect = {"disturb", 1},
