        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_60842_Content_58|你……你知道……",
        DialogType = 2,
        RoleHide = {1},
        AnimState = "UI_Story_Panel_Group_Dialog_doudong_vx",
        AudioTalk = {
          "Play_A_SFX_Hit_Jump_Shock"
        }
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60842_Content_59|无上意志的降临不可避免，唯有你可以与之对抗。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60842_Content_60|让双子现世，门扉开启，你才能重新获得与祂对抗的能力。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1796},
        Content = "AvgDialog_60842_Content_61|事急从权，请原谅我先前的失礼。",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {
          1821,
          nil,
          "Sad"
        },
        Content = "AvgDialog_60842_Content_62|哈姆林！你……你这是在做什么？！！",
