        Sequence = "PlayVideo(CG_SD/Video_SD_S_C02EX_3.mp4)",
        AudioTalk = {
          "Play_Video_SD_S_C02EX_3"
        }
      }),
      readonly({
        Content = "AvgDialog_65480_Content_13|她笑了一声，笑声在寂静的空间中回荡，如同冰冷的利刃划过你的肌肤，仿佛在嘲弄着所有试图对抗她的愚蠢。",
        DialogType = 3,
        BgID = {
          "SScene_SubLab"
        },
