      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_65481_Content_33|请告诉我，我要如何才能打败无上意志。我要如何，才能保护他们……",
        DialogType = 2
      }),
      readonly({
        Content = "AvgDialog_65481_Content_34|契诃玛-达阿特。这个名字清晰地在这个空间里响起。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_65481_Content_35|一个泡泡漂浮到你面前，你伸出手指，虔诚地触碰它。",
        DialogType = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Bubbles_DivineCom_drift"
