      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68329_Content_26|和我站在一起，你会死……",
        DialogType = 1,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {1124},
        Content = "AvgDialog_68329_Content_27|死有何惧？",
        DialogType = 2,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_68329_Content_28|第二颗水滴落入你的脑海。",
