  [68336] = {
    ID = 68336,
    CnID = "主线剧情_关卡9_13_前",
    BaseSortID = 36,
    data_list = readonly({
      readonly({
        BaseSortID = 36,
        Content = "AvgDialog_68336_Content_1|告别：K-0617",
        Chapter = "Chapter 9;Farewell:K-0617;Part 13",
        DialogType = 4,
        BgID = {
          "SScene_Black"
        },
        ShortAudioEffect = {
          "Play_UI_AVG_Chapter_Pop"
        },
        Audio = {
          "Stop_Avg_CG_Audio"
        },
        AudioManageEvent = {
          "Stop_Mus",
          "Pause_Ingame_Fight_SFXandVoice"
        },
        BanSpeedUp = 1
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_2|「我可以不写吗？这个东西听着真的很不吉利。我这样问拉蒙娜。」",
        DialogType = 1,
        ScreenEffect = {"lightRain", 1},
        BgID = {
          "SScene_SchoolGraveyard"
        },
        Sequence = "FadeDarkRole(1118,1)",
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_1"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Rain_Smalle",
          "800"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_3|「她说，不行，每个守密人继任之前，都要留下一封遗书。」",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_2"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_4|「她还让我放心，说会帮我好好保管，等我死的时候拿出来，一定会在这些文字被融蚀完之前念完。」",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_3"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_5|「哎，拉蒙娜什么都好，就是这嘴太毒了一点，跟朵尔教授有一拼。」",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_4"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_6|「一年前我在阿库特刚睁开眼时，面前就是拉蒙娜的脸。」",
        DialogType = 1,
        BgID = {
          "SScene_SnowWind"
        },
        BgTransition = 4,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_5"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_7|「那时候她还很客气。或许她最近学业压力确实太大了……」",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_6"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_8|雨点淅淅沥沥，落在那些无名的墓碑与人群头上。",
        DialogType = 3,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        AudioTalk = {
          "Stop_Avg_Vocal"
        },
        ShortAudioEffect = {
          "Play_A_MUS_Funeral_A_70BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Rain_Smalle"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_9|唤醒体、师生、工作人员……所有人肃立在墓园中，即使平日最吵闹的唤醒体，此刻也没有发出半点声音。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        Content = "AvgDialog_68336_Content_10|拉蒙娜站在人群前方，她念诵遗书的声音清晰、稳定，只有手里的纸张，无法抑制地微微颤抖。",
        DialogType = 3,
        BgID = {
          "SScene_SchoolGraveyard"
        },
        BgTransition = 4,
        Sequence = "SetRole(1118,3,Sad2)"
      }),
      readonly({
        Content = "AvgDialog_68336_Content_11|她的头埋得很低。水滴落在纸张上面，或许是雨，或许是别的什么。",
        DialogType = 3,
        BgID = {
          "CGDynamic_C01_012"
        },
        Sequence = "FadeDarkRole(1118,2)",
        AudioAmbient = {
          "Stop_Avg_Amb_Long_Fideout"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_12|「我跟着他们来到了弥萨格。不然呢？我不知道那个阿库特究竟是什么地方，也不知道我究竟是个什么。」",
        DialogType = 2,
        RoleHide = {1},
        ScreenEffect = {"lightRain", 2},
        BgID = {
          "SScene_StudentDorm"
        },
        BgTransition = 6,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_7",
          "350"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_13|「我只能记起来一些常识，比如人需要吃饭和睡觉。\n这两样问题，弥萨格恰巧都能解决。」",
        DialogType = 2,
        RoleHide = {1},
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_8"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_14|「刚来的那段日子，弥萨格迷人的餐厅和宿舍让我觉得自己的选择无比正确——」",
        DialogType = 2,
        RoleHide = {1},
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_9"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_15|「直到一个星期以后，我正式入学。」",
        DialogType = 2,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_10"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_16|「敬告所有向往弥萨格的可怜虫：弥萨格住着一群魔鬼。」",
        DialogType = 2,
        BgID = {
          "SScene_SchoolDust"
        },
        BgTransition = 4,
        Sequence = "SetRole(1124,1);SetRole(1120,3);SetRole(1593,5)",
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_11"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_17|「他们负责训练我们的体能、剑术、急救、银芯运用、融蚀生物认知……」",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_12"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_18|「像拉蒙娜和威廉学长这样的学生是地狱的接班人，他们在这煎熬里如鱼得水。」",
        DialogType = 2,
        PlayEnterAnim = 1,
        RoleHide = {
          1124,
          1120,
          1593
        },
        BgTransition = 4,
        Sequence = "SetRole(1118,2);SetRole(1183,4)",
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_13"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_19|「而我在地狱里煎熬了一年，每一堂课都让我觉得，在丧失的记忆里，我大概是犯下了什么滔天大罪，必须要在地狱里受罚。」",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_14"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_20|「很多人和我说，我有着出众的天赋。我看着我那些一直在及格线徘徊的成绩单，真不知道他们是怎么把这句话说出口的。」",
        DialogType = 2,
        PlayEnterAnim = 1,
        RoleHide = {1118, 1183},
        BgID = {
          "SScene_SchoolOffice"
        },
        BgTransition = 4,
        Sequence = "SetRole(1120,3)",
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_15"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_21|「直到那天，在第一次唤醒体链接课程上，我用了五分钟，和三名唤醒体建立了初步的链接。」",
        DialogType = 2,
        PlayEnterAnim = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_16"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_22|「一名调查员的精神强度，大概能支持链接一名唤醒体。学校轰动了。我想这或许是意味着什么，但我不清楚这究竟是好事还是坏事。」",
        DialogType = 2,
        PlayEnterAnim = 1,
        RoleHide = {1120},
        BgID = {
          "SScene_Black"
        },
        BgTransition = 4,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_17"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_23|「阿利斯泰尔老师告诉我，所有的天赋都需要付出代价，我有一条自己的路需要走，这条路艰难，孤独。我需要承受很多，也需要放弃很多。」",
        DialogType = 2,
        BgID = {
          "SScene_RestrictedArea"
        },
        BgTransition = 4,
        Sequence = "SetRole(1823,3)",
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_18"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_24|「他问我，我想走这条路吗？我没有回答。」",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_19"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_25|「我是一个有梦想的人。我的梦想是跟我爱的人一起围坐在舒适的火炉旁，浪费我们一文不值的生命。」",
        DialogType = 2,
        RoleHide = {1},
        BgID = {
          "SScene_BedRoomDay"
        },
        BgTransition = 4,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_20"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_26|「窗外的雪慢慢地飘着，年复一年，直到我们寿终正寝。我的墓碑上将写着：%heorshe%是一个长寿又幸福的废物。」",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_21"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_27|「守密人。除了能多赚到一些钱以外，这三个字听上去和我的梦想没有半点关系……」",
        DialogType = 2,
        RoleHide = {1},
        BgID = {
          "CGDynamic_C01_012"
        },
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_22"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_28|咚咚咚——",
        DialogType = 3,
        ScreenEffect = {
          "retro",
          1,
          "lightRain",
          2
        },
        BgID = {
          "SScene_StudentDorm"
        },
        BgTransition = 4,
        AudioTalk = {
          "Stop_Avg_Vocal"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Knock_Wood"
        },
        Audio = {
          "Play_A_MUS_Dreamy_Memories_109BPM"
        },
        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        TalkRole = {1118},
        Content = "AvgDialog_68336_Content_29|钥冢仪式明天就要开始了。遗书写好了么，%player%？",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_23"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68336_Content_30|一定要把话说的这么不吉利吗……",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Me_Male_1"
        }
      }),
      readonly({
        TalkRole = {1118},
        Content = "AvgDialog_68336_Content_31|有直面融蚀的勇气，是一名调查员的基本素养。作为守密人的继任者，更是如此。",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_24_1"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68336_Content_32|说的真简单啊……拉蒙娜，说真的，你有考虑过这个问题吗？",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Me_Male_2"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68336_Content_33|我在这里一年，去了好几次钥冢。很多人被授予银钥匙，很多银钥匙都因为主人的丧生而被收回。",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Me_Male_3"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68336_Content_34|他们奉献一生，所有的功绩却都将被遗忘，甚至连名字也无法留下。最后留下的，只有一块无字的墓碑。",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Me_Male_4"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68336_Content_35|你说，他们死之前会想些什么呢？",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Me_Male_5"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Serious"
        },
        Content = "AvgDialog_68336_Content_36|他们会恐惧，痛苦，遗憾。但唯独不会后悔。",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_24_2"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Serious"
        },
        Content = "AvgDialog_68336_Content_37|因为他们的身后，是他们所深爱的一切。因为他们的身前，已经没有别人了。",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_25"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68336_Content_38|我问过威廉学长，他的回答也和你一样。",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Me_Male_6"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68336_Content_39|我不知道，拉蒙娜。",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Me_Male_7"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68336_Content_40|所有人都说，我是弥萨格的希望……可我知道我自己是一个什么样的人。",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Me_Male_8"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68336_Content_41|贪图享乐，自私怯懦。我害怕融蚀，害怕死亡，每天想的是怎么让自己过得舒服一点，怎么让自己活得更久一点。",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Me_Male_9"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68336_Content_42|第一次去现场出任务的时候，我走在所有人后面，生怕自己也染上融蚀。我才二十岁，我还有很多事想做……",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Me_Male_10"
        }
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_68336_Content_43|拉蒙娜，你说我这样的人，有资格当守密人吗？",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Me_Male_11"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_44|在你的预想里，拉蒙娜会失望，会愤怒，会用她的细剑指着你，会摇头摔门而去，就像你每次抱怨自己无法完成课程作业一样。",
        DialogType = 3,
        RoleHide = {1},
        AudioTalk = {
          "Stop_Avg_Vocal"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_45|但她没有。她安静地看着你，听着你的讲述。\n她向你露出一个微笑，像是阿库特第一次相见的那天。",
        DialogType = 3
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Smile"
        },
        Content = "AvgDialog_68336_Content_46|平凡的生活，谁不喜欢呢……每一个守密人与调查员，都曾在某一刻怀疑过。有人选择退却，也有人选择继续向前……",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_26"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Smile"
        },
        Content = "AvgDialog_68336_Content_47|世界从未要求过他们，他们也从未想过要为之付出一切。但到了某一刻，他们依然会做出自己也无法理解的选择。",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_27"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Smile"
        },
        Content = "AvgDialog_68336_Content_48|有些选择，是一个人的本能。你也一样，%player%。",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_28"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Smile"
        },
        Content = "AvgDialog_68336_Content_49|剩下的时间，就留给你自己吧。",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_29"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Smile"
        },
        Content = "AvgDialog_68336_Content_50|无论你做出什么样的决定，弥萨格的大门，永远为你敞开。",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_30"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Smile"
        },
        Content = "AvgDialog_68336_Content_51|愿银钥指引我们。",
        DialogType = 1,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        BgTransition = 5,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_31",
          "1650"
        },
        AudioManageEvent = {
          "Stop_Avg_Vocal"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_52|……",
        DialogType = 3,
        RoleHide = {1},
        ScreenEffect = {"retro", 2},
        BgID = {
          "SScene_Black"
        },
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_53|「拉蒙娜走之后，我想了很多。我回忆这一年在弥萨格的一切。」",
        DialogType = 1,
        ScreenEffect = {"lightRain", 1},
        BgID = {
          "SScene_SchoolGraveyard"
        },
        BgTransition = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_32",
          "350"
        },
        Audio = {
          "Play_A_MUS_Funeral_B_70BPM"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_Rain_Smalle"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_54|「我喜欢很多东西。阿利斯泰尔老师讲的故事，考试的时候同学递的纸条，学校餐厅的小蛋糕，德克斯特教授偷偷塞给我的酒……」",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_33"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_55|「我讨厌很多东西。没写完作业时拉蒙娜脸上的表情，朵尔教授像是看傻子一样的眼神，萝坦老师的剑术课，一点也不通情达理的期末考核制度，所有的体能训练课程，那些没完没了的融蚀……」",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_34"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_56|「我的人生记忆只有一年，一切的记忆，都与弥萨格有关。」",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_35"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_57|「我憎恨这个地方。我眷恋这个地方。但无论如何，我离不开这个地方。」",
        DialogType = 1,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_36"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_58|「你猜错了，拉蒙娜。我或许没有那么卑劣，但也绝没有你想的那么高尚。我只是一个普通得不能再普通的人。」",
        DialogType = 2,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_37"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Serious"
        },
        Content = "AvgDialog_68336_Content_59|「不过……阿利斯泰尔老师的问题，我有答案了。」",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_38"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_60|「为了弥萨格，为了你们，我会继任守密人。我会走上那条属于我的路。」",
        DialogType = 2,
        RoleHide = {1},
        BgID = {
          "SScene_SchoolPanorama"
        },
        BgTransition = 4,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_39"
        },
        ShortAudioEffect = {
          "Play_A_SFX_Pigeons_Flying_01"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_61|「但我也会好好活着。活到九十、一百岁，活到老死。」",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_40"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_62|「我会一边解决融蚀，一边用光我的假期。我会去吃每一款我想吃的食物，看每一处我想看的风景。」",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_41"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_63|「如果遇到解决不了的问题，我就跑，跑得越远越好。」",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_42"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_64|「这份遗书大概是用不到了……很遗憾，弥萨格，你将迎来你历史上最怯懦的守密人。」",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_43"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad2"
        },
        Content = "AvgDialog_68336_Content_65|「但假如，我是说假如，有那么一天，这份遗书真的被念了出来，那我一定是脑子出了什么问题。」",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_44"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_66|「但我希望，诵念它的声音，能是欣慰的。」",
        DialogType = 2,
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_45"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_67|「如果我死了……」",
        DialogType = 2,
        ScreenEffect = {"lightRain", 2},
        BgID = {
          "SScene_Black"
        },
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_46"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_68|「那一定是因为我找到了更重要的东西。」",
        DialogType = 2,
        Sequence = "SetRole(1124,1);SetRole(1120,3);SetRole(1123,5)",
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_47"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_69|「比小蛋糕、比舒适的火炉、比活着都更重要。」",
        DialogType = 2,
        RoleHide = {
          1124,
          1120,
          1123
        },
        Sequence = "SetRole(1183,1);SetRole(1181,3);SetRole(1823,5)",
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_48"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_70|「或许我走上了一条艰辛孤独的道路。」",
        DialogType = 2,
        RoleHide = {1},
        BgID = {
          "SScene_CG_C09_011_F"
        },
        BgTransition = 4,
        Sequence = "ReplaceBg(Gender_Boy,SScene_CG_C09_011_M)",
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_49"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_71|「或许我牺牲了生命与所挂念的一切，不过稍稍延缓了灾难的脚步，什么也没有解决，什么也没有改变。」",
        DialogType = 2,
        RoleHide = {1},
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_50"
        }
      }),
      readonly({
        TalkRole = {
          1118,
          nil,
          "Sad3"
        },
        Content = "AvgDialog_68336_Content_72|「但我一定，是死在莫大的幸福里。」",
        DialogType = 2,
        RoleHide = {1},
        BgID = {
          "SScene_Black"
        },
        AudioTalk = {
          "VOC_AVG_Dia_Final_Lamengna_51"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_73|……",
        DialogType = 3,
        RoleHide = {1},
        AudioTalk = {
          "Stop_Avg_Vocal"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_74|声音停了下来。",
        DialogType = 3,
        RoleHide = {1},
        ScreenEffect = {"lightRain", 1},
        BgID = {
          "SScene_SchoolGraveyard"
        },
        BgTransition = 6
      }),
      readonly({
        Content = "AvgDialog_68336_Content_75|雨仍然淅淅沥沥地下着，弥萨格阒寂无声。",
        DialogType = 3,
        Audio = {
          "Stop_Avg_Mus"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_76|所有的目光都望向黑池。",
        DialogType = 3,
        BgID = {
          "CGDynamic_C01_012"
        },
        Audio = {
          "Play_A_MUS_Dream_Again_Chp0"
        },
        AudioAmbient = {
          "Stop_Avg_Amb"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_77|钟楼之下，地心深处，那个黯淡无光的巨大门扉之内，一个被羽翼包裹的身影纹丝不动。",
        DialogType = 3,
        ScreenEffect = {"lightRain", 2},
        BgID = {
          "SScene_CG_C09_003"
        },
        BgTransition = 3,
        ShortAudioEffect = {
          "Play_A_SFX_Meteor_Passing_By_01",
          "200"
        },
        AudioAmbient = {
          "Play_A_SFX_Amb_TaWeiRoom"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_78|%heorshe%听见弥萨格的雨滴落石碑。%heorshe%听见拉蒙娜哽咽的诵念。%heorshe%听见黑色的融蚀蔓延，缓缓覆盖住自己的名字。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_68336_Content_79|在这场漫长的梦境里，%heorshe%不断地坠落、坠落。那些声音离%heorshe%越来越遥远，逐渐汇成一道低沉的呜咽。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_68336_Content_80|在%heorshe%的坠落中，过往的一切记忆出现在%heorshe%面前，如同一道道流光，与%heorshe%擦肩而过。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_68336_Content_81|沉睡的面庞上，虚无的嘴角微微翘起。\n%heorshe%的故事无人知晓。%heorshe%的记忆与世长存。",
        DialogType = 3
      }),
      readonly({
        Content = "AvgDialog_68336_Content_82|%heorshe%举起自己那双并不存在的手，对着那空无的远处，轻轻挥动。",
        DialogType = 3,
        BgID = {
          "CGDynamic_C01_012"
        }
      }),
      readonly({
        Content = "AvgDialog_68336_Content_83|再见……弥萨格。",
        DialogType = 5,
        DialogAnim = 0,
        BgID = {
          "SScene_Black"
        }
      }),
      readonly({
        DialogAnim = 0,
        Audio = {
          "Stop_Avg_Mus"
        },
        AudioAmbient = {
          "Stop_Avg_Amb"
        },
        AudioManageEvent = {
          "Stop_All_Avg_Sound",
          "Resume_Ingame_Fight_SFXandVoice",
          "1"
        }
      }),
      readonly({
        Sequence = "PlayVideo(LoginPV/LoginPV_1_7.mp4,70276)",
        Audio = {
          "Play_VideoPV1_7Login"
        },
        BanSpeedUp = 1
      })
    })
  },
  [46539] = {
    ID = 46539,
    CnID = "功能引导_相位对弈",
    BaseSortID = 1,
    data_list = readonly({
      readonly({
        BaseSortID = 1,
        TalkRole = {1183},
        Content = "AvgDialog_46539_Content_1|经过一年的授课和近期的任务调查，你现在的资历已经可以接触「相位对弈」了。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        NextChatID = {"A", "B"},
        TalkRole = {1183},
        Content = "AvgDialog_46539_Content_2|说起来，你有从其他人那儿听说过「相位对弈」吗？",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        ChatID = "A",
        Content = "AvgDialog_46539_Content_3|有所了解",
        DialogType = 5
      }),
      readonly({
        NextChatID = {"C"},
        TalkRole = {1183},
        Content = "AvgDialog_46539_Content_4|很好，不过基于学校的规章，我必须向你更全面地讲解其中的风险与规则。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        ChatID = "B",
        Content = "AvgDialog_46539_Content_5|闻所未闻",
        DialogType = 5
      }),
      readonly({
        NextChatID = {"C"},
        TalkRole = {1183},
        Content = "AvgDialog_46539_Content_6|好，那我会从头开始向你介绍。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        ChatID = "C",
        TalkRole = {1183},
        Content = "AvgDialog_46539_Content_7|在对银芯的研究中，我们发现银芯振动时产生的振波，偶尔能够跨越物理的界限。我们将发生振波的位置称为<Yellow:相位>。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_46539_Content_8|而「相位对弈」，正是一种利用相位，与另一个时空的自己进行<Yellow:对战>，从而达到锻炼精神与战斗意识效果的特化训练。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1001},
        Content = "AvgDialog_46539_Content_9|另一个时空的自己……",
        DialogType = 2
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_46539_Content_10|当然，进行战斗的都是唤醒体——不过在相位过程中，某些存在会受到物理界限的<Yellow:扭曲>。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_46539_Content_11|<Yellow:唤醒体的能力>，<Yellow:界域的隔阂>乃至<Yellow:战斗规则>都与现实中大相径庭。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_46539_Content_12|你对唤醒体们的<Yellow:养成也会失效>，不过<Yellow:对方亦然>。某种程度上而言，「相位对弈」是一场<Yellow:公平对决>。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1183},
        Content = "AvgDialog_46539_Content_13|启动相位仪器，尝试一次对弈吧，一切疑问都将在实战中得到解答。愿银钥指引前路。",
        DialogType = 1,
        RolePos = {2}
      })
    })
  },
  [46700] = {
    ID = 46700,
