        ShakeDirection = {1},
        AudioTalk = {
          "Play_A_SFX_Anime_Swing_A"
        }
      }),
      readonly({
        TalkRole = {2246},
        Content = "AvgDialog_132684_Content_21|唧！<Small:<LightGray:（一起玩！）>>",
        DialogType = 1,
        RolePos = {4},
        RoleShake = {1},
        ShakeDirection = {1},
        Sequence = "LightRole(2247,1)",
        AudioTalk = {
          "Play_A_SFX_SeaOtter_Shock_C"
        }
      }),
      readonly({
        TalkRole = {
          1001,
          "UI_Story_D_Image_Face_Surprise1.png"
        },
        Content = "AvgDialog_132684_Content_22|唧——<Small:<LightGray:（不要啊，拉蒙娜，救我——）>>",
        DialogType = 2,
        RoleHide = {2247, 2246},
