        Sequence = "SetRole(2240,3,Noface);LightRole(2240,1)",
        AudioTalk = {
          "Play_A_SFX_SeaOtter_Angry"
        }
      }),
      readonly({
        TalkRole = {1118, "Laugh"},
        Content = "AvgDialog_132684_Content_23|咳。",
        DialogType = 1,
        RolePos = {2},
        Sequence = "LightRole(2240,2)"
      }),
      readonly({
        TalkRole = {1118, "Smile"},
        Content = "AvgDialog_132684_Content_24|搭档，今天没有什么重要事务，请不用担心。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        TalkRole = {1118, "Shy"},
        Content = "AvgDialog_132684_Content_25|我也会腾出今天的时间，来保障你的安全的。",
        DialogType = 1,
        RolePos = {2}
      }),
      readonly({
        Content = "AvgDialog_132684_Content_26|话虽然是这么说，但显然，她也已经和莫丝一样，完全被你手感好到难以置信的毛毛完全控制了。",
        DialogType = 3,
        RoleHide = {1}
      }),
      readonly({
        TalkRole = {
          1001,
          "UI_Story_D_Image_Face_Sweat.png"
